127→/// A log entry for debug capture
128→#[derive(Debug, Clone, Serialize)]
129→pub struct DebugLogEntry {
130→    pub ts: String,
131→    pub level: String,
132→    pub target: String,
133→    pub msg: String,
134→    pub instance: Option<String>,
135→}
