137→// Debug Capture Layer
138→
139→use tracing::{Event, Subscriber};
140→use tracing_subscriber::layer::Context;
141→use tracing_subscriber::Layer;
142→
143→/// A tracing layer that captures log events and sends them to a broadcast channel
144→///
145→/// This layer intercepts all log events and sends them as `DebugLogEntry` to
146→/// a tokio broadcast channel, allowing external consumers (like ai_interface)
147→/// to access protocol-level logs from all libs.
148→pub struct DebugCaptureLayer {
149→    tx: tokio::sync::broadcast::Sender<DebugLogEntry>,
150→    instance_name: Option<String>,
151→}
152→
153→impl DebugCaptureLayer {
154→    pub fn new(
155→        tx: tokio::sync::broadcast::Sender<DebugLogEntry>,
156→        instance_name: Option<String>,
157→    ) -> Self {
158→        Self { tx, instance_name }
159→    }
160→}
161→
162→impl<S> Layer<S> for DebugCaptureLayer
163→where
164→    S: Subscriber,
165→{
166→    fn on_event(&self, event: &Event<'_>, _ctx: Context<'_, S>) {
167→        let metadata = event.metadata();
168→        let level = metadata.level().to_string();
169→        let target = metadata.target().to_string();
170→
171→        // Extract message from event fields
172→        let mut msg = String::new();
173→        let mut visitor = MessageVisitor(&mut msg);
174→        event.record(&mut visitor);
175→
176→        let entry = DebugLogEntry {
177→            ts: chrono::Utc::now().format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string(),
178→            level,
179→            target,
180→            msg,
181→            instance: self.instance_name.clone(),
182→        };
183→
184→        // Send to channel - ignore errors (no receivers)
185→        let _ = self.tx.send(entry);
186→    }
187→}
188→
189→/// Visitor to extract message field from tracing events
190→struct MessageVisitor<'a>(&'a mut String);
191→
192→impl<'a> tracing::field::Visit for MessageVisitor<'a> {
193→    fn record_debug(&mut self, field: &tracing::field::Field, value: &dyn std::fmt::Debug) {
194→        if field.name() == "message" {
195→            *self.0 = format!("{:?}", value);
196→        } else if self.0.is_empty() {
197→            // Capture first field if no message
198→            self.0.push_str(&format!("{}={:?}", field.name(), value));
199→        } else {
200→            self.0.push_str(&format!(" {}={:?}", field.name(), value));
201→        }
202→    }
203→
204→    fn record_str(&mut self, field: &tracing::field::Field, value: &str) {
205→        if field.name() == "message" {
206→            *self.0 = value.to_string();
207→        } else if self.0.is_empty() {
208→            self.0.push_str(&format!("{}={}", field.name(), value));
209→        } else {
210→            self.0.push_str(&format!(" {}={}", field.name(), value));
211→        }
212→    }
213→}
