215→/// Handle for the event capture system
216→///
217→/// Subscribes to pre-serialized JSON line sources and writes them to a JSONL file.
218→/// Sources register `broadcast::Sender<String>` channels -- each source serializes
219→/// its own events before sending, keeping logging_utils dependency-free from
220→/// courier/scribe types.
221→#[derive(Clone)]
222→pub struct CaptureHandle {
223→    /// Broadcast sender for log entries (always active)
224→    log_tx: tokio::sync::broadcast::Sender<DebugLogEntry>,
225→    /// Registered capture sources (pre-serialized JSON lines)
226→    sources: Arc<tokio::sync::RwLock<Vec<tokio::sync::broadcast::Sender<String>>>>,
227→    /// Cancel signal for active capture
228→    cancel_tx: Arc<tokio::sync::Mutex<Option<tokio::sync::oneshot::Sender<()>>>>,
229→    /// Instance name for log entries
230→    instance_name: String,
231→}
232→
233→impl CaptureHandle {
234→    /// Create a new CaptureHandle
235→    pub fn new(
236→        log_tx: tokio::sync::broadcast::Sender<DebugLogEntry>,
237→        instance_name: String,
238→    ) -> Self {
239→        Self {
240→            log_tx,
241→            sources: Arc::new(tokio::sync::RwLock::new(Vec::new())),
242→            cancel_tx: Arc::new(tokio::sync::Mutex::new(None)),
243→            instance_name,
244→        }
245→    }
246→
247→    /// Register a capture source (pre-serialized JSON lines)
248→    ///
249→    /// Each source is a broadcast::Sender<String> that emits pre-serialized JSON lines.
250→    /// The CaptureHandle subscribes to all registered sources when capture starts.
251→    pub async fn register_source(&self, tx: tokio::sync::broadcast::Sender<String>) {
252→        self.sources.write().await.push(tx);
253→    }
254→
255→    /// Start capturing events to a JSONL file
256→    ///
257→    /// Subscribes to all registered sources and the log broadcast channel.
258→    /// Events are written as newline-delimited JSON to the specified file.
259→    pub async fn start_capture(
260→        &self,
261→        file_path: std::path::PathBuf,
262→        include_logs: bool,
263→    ) -> Result<(), String> {
264→        // Check if already capturing
265→        {
266→            let guard = self.cancel_tx.lock().await;
267→            if guard.is_some() {
268→                return Err("Capture already active".to_string());
269→            }
270→        }
271→
272→        // Create parent directory if needed
273→        if let Some(parent) = file_path.parent() {
274→            tokio::fs::create_dir_all(parent)
275→                .await
276→                .map_err(|e| format!("Failed to create capture directory: {}", e))?;
277→        }
278→
279→        // Open file for writing
280→        let file = tokio::fs::File::create(&file_path)
281→            .await
282→            .map_err(|e| format!("Failed to create capture file: {}", e))?;
283→        let writer = tokio::io::BufWriter::new(file);
284→
285→        // Create cancel channel
286→        let (cancel_tx, cancel_rx) = tokio::sync::oneshot::channel::<()>();
287→        {
288→            let mut guard = self.cancel_tx.lock().await;
289→            *guard = Some(cancel_tx);
290→        }
291→
292→        // Subscribe to all sources
293→        let sources = self.sources.read().await;
294→        let mut source_rxs: Vec<tokio::sync::broadcast::Receiver<String>> =
295→            sources.iter().map(|tx| tx.subscribe()).collect();
296→        drop(sources);
297→
298→        // Subscribe to log broadcast if requested
299→        let mut log_rx = if include_logs {
300→            Some(self.log_tx.subscribe())
301→        } else {
302→            None
303→        };
304→
305→        let instance_name = self.instance_name.clone();
306→
307→        // Spawn capture task
308→        tokio::spawn(async move {
309→            use tokio::io::AsyncWriteExt;
310→
311→            let mut writer = writer;
312→            let mut cancel_rx = cancel_rx;
313→
314→            loop {
315→                // Check for cancel
316→                if cancel_rx.try_recv().is_ok() {
317→                    break;
318→                }
319→
320→                let mut got_event = false;
321→
322→                // Poll each source
323→                for rx in source_rxs.iter_mut() {
324→                    while let Ok(line) = rx.try_recv() {
325→                        // Add instance field to the JSON line
326→                        if let Ok(mut obj) = serde_json::from_str::<serde_json::Value>(&line) {
327→                            if let Some(map) = obj.as_object_mut() {
328→                                map.insert(
329→                                    "instance".to_string(),
330→                                    serde_json::Value::String(instance_name.clone()),
331→                                );
332→                            }
333→                            if let Ok(enriched) = serde_json::to_string(&obj) {
334→                                let _ = writer.write_all(enriched.as_bytes()).await;
335→                                let _ = writer.write_all(b"\n").await;
336→                            }
337→                        } else {
338→                            // Write raw if not valid JSON
339→                            let _ = writer.write_all(line.as_bytes()).await;
340→                            let _ = writer.write_all(b"\n").await;
341→                        }
342→                        got_event = true;
343→                    }
344→                }
345→
346→                // Poll log broadcast if enabled
347→                if let Some(ref mut rx) = log_rx {
348→                    while let Ok(entry) = rx.try_recv() {
349→                        if let Ok(json) = serde_json::to_string(&serde_json::json!({
350→                            "type": "log",
351→                            "ts": entry.ts,
352→                            "level": entry.level,
353→                            "target": entry.target,
354→                            "msg": entry.msg,
355→                            "instance": &instance_name,
356→                        })) {
357→                            let _ = writer.write_all(json.as_bytes()).await;
358→                            let _ = writer.write_all(b"\n").await;
359→                        }
360→                        got_event = true;
361→                    }
362→                }
363→
364→                // Flush periodically
365→                if got_event {
366→                    let _ = writer.flush().await;
367→                }
368→
369→                // Small sleep to avoid busy-waiting
370→                tokio::time::sleep(std::time::Duration::from_millis(10)).await;
371→            }
372→
373→            // Final flush
374→            let _ = writer.flush().await;
375→        });
376→
377→        Ok(())
378→    }
379→
380→    /// Stop capturing and flush the file
381→    pub async fn stop_capture(&self) -> Result<(), String> {
382→        let mut guard = self.cancel_tx.lock().await;
383→        if let Some(tx) = guard.take() {
384→            let _ = tx.send(());
385→            // Give the capture task time to flush
386→            tokio::time::sleep(std::time::Duration::from_millis(100)).await;
387→            Ok(())
388→        } else {
389→            Err("No active capture".to_string())
390→        }
391→    }
392→}
