451→/// Initialize rich tracing with tree formatting
452→///
453→/// This sets up a hierarchical logging system with optional file output.
454→/// The tree format shows nested function calls with indentation, making it
455→/// easy to trace execution flow through async code and multiple services.
456→///
457→/// When `debug_tx` is provided in config, all logs are also sent to that
458→/// broadcast channel for external consumers (like ai_interface).
459→///
460→/// # Example Output
461→/// ```text
462→/// 🎯 handle_add_folder name="My Folder"
463→///   ├─📁 create_folder folder_id="f_abc123"
464→///   │ ├─🔐 issue_folder_owner_token
465→///   │ │ └─✓ 8.7ms
466→///   │ └─✓ 45.6ms
467→///   └─✓ 50.1ms
468→/// ```
469→pub fn init_rich_tracing(
470→    config: LogConfig,
471→) -> Result<Option<WorkerGuard>, Box<dyn std::error::Error>> {
472→    let mut guard = None;
473→
474→    // Create filter: use RUST_LOG level if set, otherwise config.level,
475→    // but ALWAYS apply our third-party noise suppressions
476→    let base_level = std::env::var("RUST_LOG").unwrap_or_else(|_| config.level.clone());
477→    let filter = EnvFilter::try_new(format!(
478→        "{},\
479→         hyper=warn,\
480→         hyper_util=warn,\
481→         rustls=error,\
482→         iroh=warn,\
483→         iroh::socket=off,\
484→         iroh::net_report=off,\
485→         iroh::net_report::report=off,\
486→         quinn=warn,\
487→         netlink_proto=error,\
488→         netlink_sys=error,\
489→         netlink_packet_route=off,\
490→         hickory_proto=error,\
491→         hickory_resolver=error,\
492→         hickory_client=error,\
493→         portmapper=off,\
494→         tokio_tungstenite=warn,\
495→         tungstenite=warn,\
496→         netwatch=warn,\
497→         iroh_quinn_proto::connection=warn,\
498→         iroh_relay=warn,\
499→         igd_next::aio::tokio=warn,\
500→         tantivy=warn,\
501→         reqwest=warn,\
502→         asset_protocol=warn,\
503→         loro_internal=off,\
504→         loro_internal::oplog=off,\
505→         loro_internal::oplog::change_store=off,\
506→         loro_internal::oplog::change_store::block_encode=off,\
507→         loro_kv_store=off,\
508→         wgpu_core=warn,\
509→         wgpu_hal=off,\
510→         wgpu_hal::gles=off,\
511→         winit=warn,\
512→         naga=warn",
513→        base_level
514→    ))?;
515→
516→    // Create optional debug capture layer (sends logs to broadcast channel)
517→    let debug_layer = config.debug_tx.map(|tx| {
518→        DebugCaptureLayer::new(tx, config.instance_name.clone())
519→    });
520→
521→    let registry = tracing_subscriber::registry().with(filter).with(debug_layer);
522→
523→    // JSON stdout mode (for ai_interface to parse)
524→    if config.log_to_stdout && config.stdout_json {
525→        let json_layer = fmt::Layer::new()
526→            .json()
527→            .with_ansi(false);
528→
529→        // Also add file layer if configured
530→        if config.log_to_file {
531→            if let (Some(dir), Some(prefix)) = (config.log_dir.as_ref(), config.file_prefix.as_ref())
532→            {
533→                let file_appender = tracing_appender::rolling::daily(dir, prefix);
534→                let (file_writer, file_guard) = tracing_appender::non_blocking(file_appender);
535→
536→                let file_layer = fmt::Layer::new()
537→                    .with_writer(file_writer)
538→                    .json()
539→                    .with_ansi(false);
540→
541→                let _ = registry.with(json_layer).with(file_layer).try_init();
542→                guard = Some(file_guard);
543→            } else {
544→                return Err("Log directory and file prefix required when log_to_file is true".into());
545→            }
546→        } else {
547→            let _ = registry.with(json_layer).try_init();
548→        }
549→    }
550→    // Tree layer for stdout (hierarchical, beautiful)
551→    else if config.log_to_stdout && config.use_tree_format {
552→        let tree_layer = HierarchicalLayer::new(2)
553→            .with_targets(true)  // Always show targets (lib/module prefix like "gurkha::parser")
554→            .with_bracketed_fields(true)
555→            .with_indent_lines(true)
556→            .with_indent_amount(2)
557→            .with_thread_ids(config.show_thread_info)
558→            .with_thread_names(config.show_thread_info)
559→            .with_verbose_exit(config.show_span_events)
560→            .with_verbose_entry(config.show_span_events)
561→            .with_ansi(true);
562→
563→        // File layer (JSON structured for parsing)
564→        if config.log_to_file {
565→            if let (Some(dir), Some(prefix)) = (config.log_dir.as_ref(), config.file_prefix.as_ref())
566→            {
567→                let file_appender = tracing_appender::rolling::daily(dir, prefix);
568→                let (file_writer, file_guard) = tracing_appender::non_blocking(file_appender);
569→
570→                let file_layer = fmt::Layer::new()
571→                    .with_writer(file_writer)
572→                    .json() // Structured JSON for log analysis
573→                    .with_ansi(false);
574→
575→                let _ = registry.with(tree_layer).with(file_layer).try_init();
576→                guard = Some(file_guard);
577→            } else {
578→                return Err("Log directory and file prefix required when log_to_file is true".into());
579→            }
580→        } else {
581→            let _ = registry.with(tree_layer).try_init();
582→        }
583→    }
584→    // Fallback: pretty format without tree
585→    else if config.log_to_stdout {
586→        let stdout_layer = fmt::Layer::new()
587→            .pretty()
588→            .with_ansi(true)
589→            .with_line_number(config.show_source_location)
590→            .with_thread_ids(config.show_thread_info)
591→            .with_thread_names(config.show_thread_info);
592→
593→        if config.log_to_file {
594→            if let (Some(dir), Some(prefix)) = (config.log_dir.as_ref(), config.file_prefix.as_ref())
595→            {
596→                let file_appender = tracing_appender::rolling::daily(dir, prefix);
597→                let (file_writer, file_guard) = tracing_appender::non_blocking(file_appender);
598→
599→                let file_layer = fmt::Layer::new()
600→                    .with_writer(file_writer)
601→                    .json()
602→                    .with_ansi(false);
603→
604→                let _ = registry.with(stdout_layer).with(file_layer).try_init();
605→                guard = Some(file_guard);
606→            } else {
607→                return Err("Log directory and file prefix required when log_to_file is true".into());
608→            }
609→        } else {
610→            let _ = registry.with(stdout_layer).try_init();
611→        }
612→    } else if config.log_to_file {
613→        if let (Some(dir), Some(prefix)) = (config.log_dir.as_ref(), config.file_prefix.as_ref()) {
614→            let file_appender = tracing_appender::rolling::daily(dir, prefix);
615→            let (file_writer, file_guard) = tracing_appender::non_blocking(file_appender);
616→
617→            let file_layer = fmt::Layer::new()
618→                .with_writer(file_writer)
619→                .json()
620→                .with_ansi(false);
621→
622→            let _ = registry.with(file_layer).try_init();
623→            guard = Some(file_guard);
624→        } else {
625→            return Err("Log directory and file prefix required when log_to_file is true".into());
626→        }
627→    } else {
628→        return Err("At least one logging destination must be enabled".into());
629→    }
630→
631→    // Forward log crate to tracing (for legacy log:: calls)
632→    // Use try_init to allow multiple initializations (won't error if already set)
633→    let _ = tracing_log::LogTracer::init();
634→
635→    Ok(guard)
636→}
