638→/// Quick init for development (tree format, debug level, stdout only)
639→///
640→/// Use this in kunki and sthalam during development for beautiful hierarchical logs.
641→pub fn init_dev() -> Result<Option<WorkerGuard>, Box<dyn std::error::Error>> {
642→    init_rich_tracing(LogConfig::default())
643→}
