648→pub fn init_prod(log_dir: &str) -> Result<Option<WorkerGuard>, Box<dyn std::error::Error>> {
649→    init_rich_tracing(LogConfig {
650→        level: "info".to_string(),
651→        log_to_file: true,
652→        log_dir: Some(log_dir.to_string()),
653→        file_prefix: Some("osvauld".to_string()),
654→        use_tree_format: true,
655→        ..Default::default()
656→    })
