659→/// Initialize rich tracing with capture support
660→///
661→/// Like init_rich_tracing but also returns a CaptureHandle for event capture.
662→/// Always creates the debug broadcast channel and DebugCaptureLayer.
663→pub fn init_rich_tracing_with_capture(
664→    config: LogConfig,
665→) -> Result<(Option<WorkerGuard>, CaptureHandle), Box<dyn std::error::Error>> {
666→    // Create broadcast channel for debug capture (always)
667→    let (debug_tx, _) = tokio::sync::broadcast::channel::<DebugLogEntry>(1024);
668→
669→    let instance_name = config.instance_name.clone().unwrap_or_default();
670→    let capture_handle = CaptureHandle::new(debug_tx.clone(), instance_name);
671→
672→    // Override the config to use our debug_tx
673→    let mut config = config;
674→    config.debug_tx = Some(debug_tx);
675→
676→    let guard = init_rich_tracing(config)?;
677→    Ok((guard, capture_handle))
678→}
