 26→/// Helper function to get passphrase - either from argument or by prompting
 27→fn get_passphrase(
 28→    passphrase_opt: Option<String>,
 29→    prompt: &str,
 30→) -> Result<String, Box<dyn std::error::Error>> {
 31→    match passphrase_opt {
 32→        Some(p) => Ok(p),
 33→        None => {
 34→            println!("{}", prompt);
 35→            let passphrase = rpassword::read_password()?;
 36→            if passphrase.is_empty() {
 37→                return Err("Passphrase cannot be empty".into());
 38→            }
 39→            Ok(passphrase)
