149→            #[cfg(not(feature = "profiling"))]
150→            handle_start(&pass, redb_store.clone(), debug_socket, &data_dir, capture_handle).await?;

 1→//! Initialization and setup functions
 2→//!
 3→//! Handles Butler, transport, and P2P initialization.
 4→
 5→use std::sync::Arc;
 6→use butler::{Butler, SyncEvent};
 7→use courier::{Courier, CourierEvent, CourierHandle, CourierMode, HandshakeServices, Transport, TransportConfig};
 8→
 9→/// Initialize P2P after login (matches Tauri pattern)
10→///
11→/// **Context**: Called after Butler identity is set
12→/// **sync_rx**: Receiver for sync events (EnsureSync) - created in main.rs, sender passed to Butler
13→/// **Returns**: (CourierHandle, event receiver) for P2P operations
14→pub async fn init_p2p(
15→    butler: Arc<Butler>,
16→    mut sync_rx: tokio::sync::mpsc::Receiver<SyncEvent>,
17→) -> Result<(CourierHandle, tokio::sync::mpsc::Receiver<CourierEvent>), String> {
18→    // Get device key from Butler (requires identity)
19→    let device_key = butler
20→        .device_key()
21→        .await
22→        .map_err(|e| format!("Failed to get device key: {}", e))?;
23→
24→    tracing::info!("Initializing transport with device key...");
25→
26→    // Initialize Transport
27→    let config = TransportConfig::new(device_key);
28→    let (transport, transport_rx) = Transport::init(config)
29→        .await
30→        .map_err(|e| format!("Failed to initialize transport: {}", e))?;
31→
32→    let transport = Arc::new(transport);
33→    let node_id = transport.node_id();
34→    tracing::info!(node_id = %node_id, "Transport initialized");
35→
36→    // Create HandshakeServices with Butler
37→    let handshake_services = Arc::new(HandshakeServices::new(butler.clone()));
38→
39→    // Initialize Courier with services
40→    let (handle, event_rx, courier) =
41→        Courier::init_with_services(CourierMode::User, transport, Some(handshake_services));
42→
43→    // Spawn courier event loop
44→    tokio::spawn(async move {
45→        courier.run(transport_rx).await;
46→    });
47→
48→    // Forward sync events to Coordinator (Scribe -> Butler -> Coordinator)
49→    // This enables EnsureSync to trigger connections/subscriptions
50→    let handle_for_sync = handle.clone();
51→    tokio::spawn(async move {
52→        while let Some(event) = sync_rx.recv().await {
53→            match event {
54→                SyncEvent::EnsureSync { user_did } => {
55→                    tracing::info!(user_did = %user_did, "Received EnsureSync from Scribe, forwarding to Coordinator");
56→                    if let Err(e) = handle_for_sync.ensure_sync(&user_did) {
57→                        tracing::warn!(user_did = %user_did, error = %e, "Failed to forward EnsureSync");
58→                    } else {
59→                        tracing::info!(user_did = %user_did, "Forwarded EnsureSync to Coordinator");
60→                    }
61→                }
62→                SyncEvent::NewDynamicLayer { page_id, layer_name, permits } => {
63→                    tracing::info!(
64→                        page_id = %page_id,
65→                        layer = %layer_name,
66→                        permit_count = permits.len(),
67→                        "Received NewDynamicLayer from Scribe, forwarding to Coordinator"
68→                    );
69→                    if let Err(e) = handle_for_sync.distribute_layer_permits(&page_id, &layer_name, permits) {
70→                        tracing::warn!(error = %e, "Failed to distribute layer permits");
71→                    }
72→                }
73→                SyncEvent::LayerAccessChanged { page_id, layer_name, permits } => {
74→                    tracing::info!(
75→                        page_id = %page_id,
76→                        layer = %layer_name,
77→                        permit_count = permits.len(),
78→                        "Received LayerAccessChanged from Scribe, forwarding to Coordinator"
79→                    );
80→                    if let Err(e) = handle_for_sync.distribute_layer_permits(&page_id, &layer_name, permits) {
81→                        tracing::warn!(error = %e, "Failed to distribute layer permits for access change");
82→                    }
83→                }
84→            }
85→        }
86→    });
87→
88→    Ok((handle, event_rx))
89→}
