 91→#[tokio::main]
 92→async fn main() -> Result<(), Box<dyn std::error::Error>> {
 93→    // Initialize profiling tools when feature is enabled
 94→    #[cfg(feature = "profiling")]
 95→    let _flame_guard = setup_profiling();
 96→
 97→    // Initialize rich tracing with capture support
 98→    // Check for OSVAULD_LOG_FORMAT=json to output JSON logs (for ai_interface)
 99→    #[cfg(not(feature = "profiling"))]
100→    let use_json = std::env::var("OSVAULD_LOG_FORMAT")
101→        .map(|v| v == "json")
102→        .unwrap_or(false);
103→
104→    #[cfg(not(feature = "profiling"))]
105→    let (_guard, capture_handle) = logging_utils::init_rich_tracing_with_capture(logging_utils::LogConfig {
106→        level: "debug".to_string(),
107→        log_to_stdout: true,
108→        use_tree_format: !use_json,
109→        stdout_json: use_json,
110→        instance_name: Some("kunki".to_string()),
111→        ..Default::default()
112→    })?;
113→
114→    info!("🚀 Kunki CLI starting");
115→
116→    let cli = Cli::parse();
117→
118→    // Initialize Butler's RedbStore for storage
119→    // Check for STHALAM_DATA_DIR env var (like sthalam does for test automation)
120→    let (db_path, data_dir): (std::path::PathBuf, std::path::PathBuf) = if let Ok(data_dir_str) = std::env::var("STHALAM_DATA_DIR") {
121→        let dir = std::path::PathBuf::from(&data_dir_str);
122→        std::fs::create_dir_all(&dir).expect("Failed to create data directory");
123→        (dir.join(format!("{}.db", cli.db_path)), dir)
124→    } else {
125→        // Default: use db_path directly with .db extension, assets in current dir
126→        let current_dir = std::env::current_dir().unwrap_or_else(|_| std::path::PathBuf::from("."));
127→        (std::path::PathBuf::from(format!("{}.db", cli.db_path)), current_dir)
128→    };
129→    info!("Using database: {:?}", db_path);
130→
131→    let redb_store = RedbStore::open(&db_path).map_err(|e| -> Box<dyn std::error::Error> {
132→        Box::new(std::io::Error::new(
133→            std::io::ErrorKind::Other,
134→            format!("Failed to open RedbStore: {}", e),
135→        ))
136→    })?;
137→    let redb_store = Arc::new(redb_store);
138→
139→    match cli.command {
140→        Commands::Init {
141→            username,
142→            passphrase,
143→        } => {
144→            let pass = get_passphrase(passphrase, "Enter passphrase:")?;
145→            handle_init(&username, &pass, redb_store.clone()).await?;
146→        }
147→        Commands::Start { passphrase, debug_socket } => {
148→            let pass = get_passphrase(passphrase, "Enter passphrase to unlock certificate:")?;
149→            #[cfg(not(feature = "profiling"))]
150→            handle_start(&pass, redb_store.clone(), debug_socket, &data_dir, capture_handle).await?;
151→            #[cfg(feature = "profiling")]
152→            handle_start(&pass, redb_store.clone(), debug_socket, &data_dir).await?;
153→        }
154→        Commands::FolderToken {
155→            passphrase,
156→            folder_id,
157→        } => {
158→            let pass = get_passphrase(passphrase, "Enter passphrase to unlock certificate:")?;
159→            handle_folder_token(&pass, &folder_id, redb_store.clone())
160→                .await?;
161→        }
162→    }
163→
164→    Ok(())
165→}
