167→async fn handle_init(
168→    username: &str,
169→    passphrase: &str,
170→    redb_store: Arc<RedbStore>,
171→) -> Result<(), Box<dyn std::error::Error>> {
172→    // Check if already signed up using Butler
173→    if butler::is_signed_up(&redb_store)? {
174→        error!("User already initialized. Use 'start' command to begin.");
175→        return Ok(());
176→    }
177→
178→    info!("Initializing new user: {}", username);
179→
180→    // Create user using Butler (Herald-based identity)
181→    let result = butler::signup(&redb_store, username, passphrase)?;
182→
183→    info!("✔ Identity created");
184→    info!("✔ DID: {}", result.identity.did());
185→    info!("⚠️  IMPORTANT: Save your recovery phrase:");
186→    println!("\n  {}\n", result.mnemonic);
187→
188→    info!("✔ User '{}' created successfully", username);
189→    info!("Use 'start' command with your passphrase to begin P2P service");
190→
191→    Ok(())
192→}
193→
194→async fn handle_start(
195→    passphrase: &str,
196→    redb_store: Arc<RedbStore>,
197→    debug_socket: Option<String>,
198→    data_dir: &std::path::Path,
199→) -> Result<(), Box<dyn std::error::Error>> {
200→    // Check if user exists in Butler
201→    if !butler::is_signed_up(&redb_store)? {
202→        error!("No user found. Please run 'init' first.");
203→        return Ok(());
204→    }
205→
206→    info!("Loading identity...");
207→
208→    // Login with Butler (returns Herald Identity)
209→    let identity = butler::login(&redb_store, passphrase)?;
210→    let identity_data = butler::get_identity_data(&redb_store)?.ok_or("Identity data not found")?;
211→
212→    info!("✔ Logged in as: {}", identity_data.username);
213→    info!("✔ DID: {}", identity.did());
214→
215→    // Create Butler with LayerCache, AssetStore and set identity
216→    let layer_cache = Arc::new(RwLock::new(LayerCache::new(redb_store.clone(), 100)));
217→    let assets_path = data_dir.join("assets");
218→    let asset_store = Arc::new(butler::AssetStore::new(&assets_path).expect("Failed to create asset store"));
219→
220→    // Create sync event channel (Scribe → Coordinator)
221→    // Node mode DOES need EnsureSync - to trigger RefreshSubscriptions when pages are opened
222→    let (sync_tx, sync_rx) = tokio::sync::mpsc::channel::<butler::SyncEvent>(32);
223→
224→    // Create page opened channel for node runtime auto-start
225→    let (page_opened_tx, mut page_opened_rx) = tokio::sync::mpsc::channel::<String>(32);
226→
227→    let butler = Arc::new(Butler::new(redb_store.clone(), layer_cache, asset_store, Some(sync_tx)));
228→    butler.set_identity(identity.clone()).await;
229→    butler.set_page_opened_tx(page_opened_tx).await;
230→
231→    // Create node runtime manager for derivation
232→    let node_runtime = Arc::new(NodeRuntimeManager::new(butler.clone()));
233→
234→    // Spawn task to auto-start node runtime when pages are opened
235→    //
236→    // **Context**: App layers (containing init.lua, node.lua) arrive via SyncOffer
237→    // AFTER the page is opened. First attempt may fail because apps().list() is empty.
238→    // We retry a few times with delay to wait for app layers to sync.
239→    let node_runtime_for_task = node_runtime.clone();
240→    tokio::spawn(async move {
241→        while let Some(page_id) = page_opened_rx.recv().await {
242→            info!(page_id = %page_id, "Page opened, starting node runtime");
243→            let runtime = node_runtime_for_task.clone();
244→            let pid = page_id.clone();
245→            tokio::spawn(async move {
246→                for attempt in 0..10u32 {
247→                    match runtime.start_node_for_page(&pid).await {
248→                        Ok(()) => {
249→                            info!(page_id = %pid, attempt, "Node runtime started");
250→                            return;
251→                        }
252→                        Err(e) => {
253→                            if attempt < 9 {
254→                                debug!(page_id = %pid, attempt, error = %e, "Node runtime not ready, retrying");
255→                                tokio::time::sleep(std::time::Duration::from_secs(2)).await;
256→                            } else {
257→                                warn!(page_id = %pid, error = %e, "Failed to start node runtime after retries");
258→                            }
259→                        }
260→                    }
261→                }
262→            });
263→        }
264→    });
265→
266→
267→    // Initialize Transport layer using the device key from Butler
268→    info!("Initializing transport layer...");
269→    let device_key = butler.device_key().await
270→        .map_err(|e| format!("Failed to get device key: {:?}", e))?;
271→    let transport_config = TransportConfig::new(device_key);
272→    let (transport, event_rx) = Transport::init(transport_config)
273→        .await
274→        .map_err(|e| format!("Failed to init transport: {}", e))?;
275→
276→    let transport = Arc::new(transport);
277→    let node_id = transport.node_id();
278→
279→    info!("✔ Transport initialized");
280→    info!("✔ Node ID: {}", node_id);
281→
282→    // Get relay URLs
283→    let relay_urls = transport.relay_urls();
284→    if !relay_urls.is_empty() {
285→        info!("✔ Relay: {}", relay_urls[0]);
286→    }
287→
288→    // Start debug server if requested (keep reference for updating state later)
289→    let debug_server_arc: Option<Arc<KunkiControlServer>> = if let Some(ref socket_path) = debug_socket {
290→        let socket_path = PathBuf::from(socket_path);
291→        let debug_server = Arc::new(KunkiControlServer::new(socket_path.clone(), "kunki".to_string(), Some(butler.clone())));
292→
293→        // Set initial state (connection_string will be updated after generation)
294→        debug_server.set_state(NodeState {
295→            node_id: node_id.to_string(),
296→            did: identity.did().to_string(),
297→            username: identity_data.username.clone(),
298→            connected_peers: vec![],
299→            relay_url: relay_urls.first().cloned(),
300→            connection_string: None,
301→        }).await;
302→
303→        // Set capture handle for event capture commands
304→        #[cfg(not(feature = "profiling"))]
305→        debug_server.set_capture_handle(capture_handle.clone()).await;
306→
307→        // Spawn debug server
308→        let server = debug_server.clone();
309→        tokio::spawn(async move {
310→            if let Err(e) = server.start().await {
311→                error!(error = %e, "Debug server error");
312→            }
313→        });
314→
315→        info!("✔ Debug server enabled on: {:?}", socket_path);
316→        Some(debug_server)
317→    } else {
318→        None
319→    };
320→
321→    // Create HandshakeServices with Butler
322→    let handshake_services = Arc::new(HandshakeServices::new(butler.clone()));
323→
324→    // Create capture broadcast channel for courier events
325→    let (capture_tx, _) = tokio::sync::broadcast::channel::<String>(1024);
326→
327→    // Register capture sources with CaptureHandle
328→    #[cfg(not(feature = "profiling"))]
329→    {
330→        capture_handle.register_source(capture_tx.clone()).await;
331→    }
332→
333→    // Set capture_tx on butler so ScribeArgs get it
334→    butler.set_capture_tx(capture_tx.clone()).await;
335→
336→    // Initialize Courier with services and capture broadcast
337→    let (courier_handle, mut courier_events, courier) = Courier::init_with_services_and_capture(
338→        CourierMode::Node,
339→        transport.clone(),
340→        Some(handshake_services),
341→        Some(capture_tx),
342→    );
343→
344→    // Note: Router starts accepting connections automatically when Transport::init() is called
345→
346→    // Spawn Courier event processor
347→    tokio::spawn(async move {
348→        courier.run(event_rx).await;
349→    });
350→
351→    // Forward sync events to Coordinator (Scribe → Coordinator)
352→    // This enables EnsureSync to trigger RefreshSubscriptions for connected peers
353→    let handle_for_sync = courier_handle.clone();
354→    let mut sync_rx = sync_rx;
355→    tokio::spawn(async move {
356→        while let Some(event) = sync_rx.recv().await {
357→            match event {
358→                butler::SyncEvent::EnsureSync { user_did } => {
359→                    tracing::info!(user_did = %user_did, "Node received EnsureSync from Scribe, forwarding to Coordinator");
360→                    if let Err(e) = handle_for_sync.ensure_sync(&user_did) {
361→                        tracing::warn!(user_did = %user_did, error = %e, "Failed to forward EnsureSync");
362→                    } else {
363→                        tracing::info!(user_did = %user_did, "Node forwarded EnsureSync to Coordinator");
364→                    }
365→                }
366→                butler::SyncEvent::NewDynamicLayer { page_id, layer_name, permits } => {
367→                    tracing::info!(
368→                        page_id = %page_id,
369→                        layer = %layer_name,
370→                        permit_count = permits.len(),
371→                        "Node received NewDynamicLayer from Scribe"
372→                    );
373→                    if let Err(e) = handle_for_sync.distribute_layer_permits(&page_id, &layer_name, permits) {
374→                        tracing::warn!(error = %e, "Failed to distribute layer permits");
375→                    }
376→                }
377→                butler::SyncEvent::LayerAccessChanged { page_id, layer_name, permits } => {
378→                    tracing::info!(
379→                        page_id = %page_id,
380→                        layer = %layer_name,
381→                        permit_count = permits.len(),
382→                        "Node received LayerAccessChanged from Scribe"
383→                    );
384→                    if let Err(e) = handle_for_sync.distribute_layer_permits(&page_id, &layer_name, permits) {
385→                        tracing::warn!(error = %e, "Failed to distribute layer permits for access change");
386→                    }
387→                }
388→            }
389→        }
390→    });
391→
392→    // Note: Node scripts are now started automatically by Scribe when is_node=true
393→    // Scribe manages the node script lifecycle via node_script_shutdown handle
394→
395→    // Spawn application event handler (logging only)
396→    // Note: Node scripts are now started automatically by Scribe when is_node=true
397→    let _courier_handle = courier_handle.clone(); // Keep handle for future use
398→    tokio::spawn(async move {
399→        while let Some(event) = courier_events.recv().await {
400→            match event {
401→                CourierEvent::PeerAuthenticated {
402→                    node_id,
403→                    did,
404→                    username,
405→                } => {
406→                    info!(
407→                        "📱 Peer authenticated: {} ({}) - node={}",
408→                        username, did, node_id
409→                    );
410→                }
411→                CourierEvent::PeerDisconnected { node_id } => {
412→                    info!("📴 Peer disconnected: {}", node_id);
413→                }
414→                CourierEvent::SpacePublished { node_id, space_id } => {
415→                    info!("📤 Space published to {}: {}", node_id, space_id);
416→                }
417→                CourierEvent::PublishFailed {
418→                    node_id,
419→                    space_id,
420→                    error,
421→                } => {
422→                    warn!("⚠️ Publish failed to {}: {} - {}", node_id, space_id, error);
423→                }
424→                CourierEvent::ViewerSyncComplete {
425→                    node_id,
426→                    space_id,
427→                    pages_synced,
428→                } => {
429→                    info!(
430→                        "📥 Viewer sync complete from {}: {} ({} pages)",
431→                        node_id, space_id, pages_synced
432→                    );
433→                }
434→                CourierEvent::ShareableLinkReceived {
435→                    node_id,
436→                    space_id,
437→                    permit,
438→                } => {
439→                    info!(
440→                        "🔗 Shareable link generated for {}: {} (permit: {}...)",
441→                        node_id, space_id, &permit[..permit.len().min(20)]
442→                    );
443→                }
444→                CourierEvent::ConnectRequested { node_id, permit } => {
445→                    info!(
446→                        "🔌 Connection requested to {}: permit={}...",
447→                        node_id, &permit[..permit.len().min(20)]
448→                    );
449→                }
450→                CourierEvent::ViewerSpaceReceived { node_id, space, page_count } => {
451→                    info!(
452→                        "📂 Viewer received space {} ({}) from {} ({} pages)",
453→                        space.id, space.name, node_id, page_count
454→                    );
455→                }
456→                CourierEvent::PageReceived { node_id, page, is_last } => {
457→                    info!(
458→                        "📄 Viewer received page {} ({}) from {} for space {} (last: {})",
459→                        page.id, page.name, node_id, page.space_id, is_last
460→                    );
461→                }
462→                CourierEvent::SyncConsentComplete { node_id, space_id } => {
463→                    info!(
464→                        "✅ Sync consent complete for space {} with node {}",
465→                        space_id, node_id
466→                    );
467→                }
468→                CourierEvent::ConnectionFailed { node_id, error } => {
469→                    warn!("❌ Connection failed to {}: {}", node_id, error);
470→                }
471→            }
472→        }
473→    });
474→
475→    // Print connection string
476→    println!("\n╔══════════════════════════════════════════╗");
477→    println!("║     CONNECTION STRING                    ║");
478→    println!("╚══════════════════════════════════════════╝");
479→
480→    // Generate connection string using Butler
481→    let encoded_connection = butler.nodes().generate_connection_string(
482→        relay_urls.first().map(|s| s.as_str()),
483→    ).await.map_err(|e| format!("Failed to generate connection string: {:?}", e))?;
484→
485→    println!("{}", encoded_connection);
486→    println!("╚══════════════════════════════════════════╝");
487→
488→    // Update debug server state with connection string
489→    if let Some(ref debug_server) = debug_server_arc {
490→        debug_server.set_state(NodeState {
491→            node_id: node_id.to_string(),
492→            did: identity.did().to_string(),
493→            username: identity_data.username.clone(),
494→            connected_peers: vec![],
495→            relay_url: relay_urls.first().cloned(),
496→            connection_string: Some(encoded_connection.clone()),
497→        }).await;
498→    }
499→
500→    println!("\nℹ️  User: {}", identity_data.username);
501→    println!("ℹ️  DID: {}", identity.did());
502→    println!("ℹ️  Node ID: {}", node_id);
503→    println!("╚══════════════════════════════════════════╝\n");
504→
505→    // Print status
506→    println!("🟢 SERVICE STATUS: ONLINE");
507→    println!("🔐 Press Ctrl+C to stop the service");
508→    println!("🔗 Service is ready to accept connections\n");
509→
510→    // Setup signal handler for graceful shutdown
511→    info!("🎯 Service is now running - waiting for shutdown signal");
512→
513→    tokio::signal::ctrl_c()
514→        .await
515→        .expect("Failed to listen for Ctrl+C");
516→
517→    info!("🛑 Shutdown signal received");
518→    info!("🛑 Initiating graceful shutdown...");
519→
520→    // Note: Node scripts are automatically stopped when Scribe actors stop
521→    // via their node_script_shutdown handles
522→
523→    info!("🔄 Cleaning up...");
524→    info!("✅ P2P service stopped gracefully");
525→    println!("\n🔴 SERVICE STATUS: OFFLINE");
526→
527→    Ok(())
528→}
