530→/// Setup profiling tools (tokio-console and/or tracing-flame)
531→///
532→/// **Modes** (based on environment variables):
533→/// - `FLAME_OUTPUT` + `TOKIO_CONSOLE_PORT` → both layers
534→/// - `FLAME_OUTPUT` only → flame layer only (no console overhead)
535→/// - `TOKIO_CONSOLE_PORT` only → console layer only
536→///
537→/// **Environment variables**:
538→/// - `TOKIO_CONSOLE_PORT`: Port for tokio-console (enables console layer)
539→/// - `FLAME_OUTPUT`: Path for flame graph output file (enables flame layer)
540→#[cfg(feature = "profiling")]
541→fn setup_profiling() -> Option<tracing_flame::FlushGuard<std::io::BufWriter<File>>> {
542→    use tracing_subscriber::prelude::*;
543→
544→    let console_port: Option<u16> = std::env::var("TOKIO_CONSOLE_PORT")
545→        .ok()
546→        .and_then(|p| p.parse().ok());
547→    let flame_path = std::env::var("FLAME_OUTPUT").ok();
548→
549→    match (&flame_path, console_port) {
550→        // Both flame + console
551→        (Some(path), Some(port)) => {
552→            let (flame_layer, guard) = match tracing_flame::FlameLayer::with_file(path) {
553→                Ok((layer, guard)) => (Some(layer), Some(guard)),
554→                Err(e) => {
555→                    eprintln!("Failed to create flame layer: {}", e);
556→                    (None, None)
557→                }
558→            };
559→
560→            let console_layer = console_subscriber::ConsoleLayer::builder()
561→                .server_addr(([127, 0, 0, 1], port))
562→                .spawn();
563→
564→            tracing_subscriber::registry()
565→                .with(console_layer)
566→                .with(flame_layer)
567→                .with(tracing_subscriber::fmt::layer().with_target(true).with_level(true))
568→                .init();
569→
570→            tracing::info!(port = port, path = %path, "Profiling: tokio-console + flame");
571→            guard
572→        }
573→        // Flame only (no console overhead)
574→        // Filter out tokio runtime TRACE spans (normally consumed by console-subscriber)
575→        (Some(path), None) => {
576→            let (flame_layer, guard) = match tracing_flame::FlameLayer::with_file(path) {
577→                Ok((layer, guard)) => (Some(layer), Some(guard)),
578→                Err(e) => {
579→                    eprintln!("Failed to create flame layer: {}", e);
580→                    (None, None)
581→                }
582→            };
583→
584→            let filter = tracing_subscriber::EnvFilter::new(
585→                "info,tokio=off,runtime=off",
586→            );
587→
588→            tracing_subscriber::registry()
589→                .with(filter)
590→                .with(flame_layer)
591→                .with(tracing_subscriber::fmt::layer().with_target(true).with_level(true))
592→                .init();
593→
594→            tracing::info!(path = %path, "Profiling: flame only (no console overhead)");
595→            guard
596→        }
597→        // Console only
598→        (None, Some(port)) => {
599→            let console_layer = console_subscriber::ConsoleLayer::builder()
600→                .server_addr(([127, 0, 0, 1], port))
601→                .spawn();
602→
603→            tracing_subscriber::registry()
604→                .with(console_layer)
605→                .with(tracing_subscriber::fmt::layer().with_target(true).with_level(true))
606→                .init();
607→
608→            tracing::info!(port = port, "Profiling: tokio-console only");
609→            None
610→        }
611→        // Neither - just fmt logging
612→        (None, None) => {
613→            let filter = tracing_subscriber::EnvFilter::new(
614→                "info,tokio=off,runtime=off",
615→            );
616→
617→            tracing_subscriber::registry()
618→                .with(filter)
619→                .with(tracing_subscriber::fmt::layer().with_target(true).with_level(true))
620→                .init();
621→
622→            tracing::info!("Profiling feature enabled but no FLAME_OUTPUT or TOKIO_CONSOLE_PORT set");
623→            None
624→        }
625→    }
626→}
