628→async fn handle_folder_token(
629→    passphrase: &str,
630→    folder_id: &str,
631→    redb_store: Arc<RedbStore>,
632→) -> Result<(), Box<dyn std::error::Error>> {
633→    // Check if user exists using Butler
634→    if !butler::is_signed_up(&redb_store)? {
635→        error!("No user found. Please run 'init' first.");
636→        return Ok(());
637→    }
638→
639→    info!("Loading identity...");
640→
641→    // Login with Butler (returns Herald Identity)
642→    let identity = butler::login(&redb_store, passphrase)?;
643→    let identity_data = butler::get_identity_data(&redb_store)?.ok_or("Identity data not found")?;
644→
645→    info!("✔ Authenticated as: {}", identity_data.username);
646→
647→    info!("Generating folder share token for folder: {}", folder_id);
648→
649→    // Generate space share token using gurkha's stateless function
650→    let signing_key_bytes = identity.secret_signing_key();
651→    let (token, _cid) = gurkha::issue_space_viewer_auth(&signing_key_bytes, folder_id)
652→        .await
