154→
155→    // Create the shell window
156→    let shell = Shell::new().expect("Failed to create shell");
157→
158→    // Set initial state
159→    shell.set_initialized(is_signed_up);
160→    shell.set_authenticated(false);
161→
162→    if is_signed_up {
163→        shell.set_current_screen("login".into());
164→    } else {
165→        shell.set_current_screen("initiation".into());
166→    }
167→
168→    // Register callbacks
169→
170→    // Auth callback: on login success, initialize P2P and event listener
171→    let butler_for_login = butler.clone();
172→    let courier_handle_for_login = courier_handle.clone();
173→    let sync_event_rx_for_login = sync_event_rx.clone();
174→    let shell_weak_for_login = shell.as_weak();
175→    let tokio_handle_for_login = tokio_handle.clone();
176→
177→    let on_login_success: sthalam_shell::callbacks::auth::OnLoginSuccess =
178→        Arc::new(move |identity| {
179→            let butler = butler_for_login.clone();
180→            let courier_handle = courier_handle_for_login.clone();
181→            let sync_rx = sync_event_rx_for_login.clone();
182→            let shell_weak = shell_weak_for_login.clone();
183→            let tokio_handle = tokio_handle_for_login.clone();
184→
185→            tokio_handle.spawn(async move {
186→                butler.set_identity(identity.clone()).await;
187→
188→                // Take the sync receiver (can only be done once)
189→                let sync_rx = sync_rx.lock().unwrap().take();
190→
191→                tracing::info!("Initializing P2P...");
192→                if let Some(sync_rx) = sync_rx {
193→                    match setup::init_p2p(butler.clone(), sync_rx).await {
194→                        Ok((handle, event_rx)) => {
195→                            tracing::info!("P2P initialized successfully");
196→                            *courier_handle.write().await = Some(handle.clone());
197→
198→                            // Auto-reconnect to stored sovereign nodes
199→                            spawn_auto_reconnect(butler.clone(), handle.clone());
200→
201→                            // Spawn event listener
202→                            events::spawn_event_listener(event_rx, shell_weak, butler);
203→                        }
204→                        Err(e) => {
205→                            tracing::error!(error = %e, "Failed to initialize P2P");
206→                        }
207→                    }
208→                } else {
209→                    tracing::error!("Sync event receiver already taken - P2P already initialized?");
210→                }
211→            });
212→        });
213→
214→    sthalam_shell::callbacks::auth::register(&shell, butler.clone(), on_login_success);
215→    sthalam_shell::callbacks::spaces::register(&shell, butler.clone());
216→    sthalam_shell::callbacks::pages::register(&shell, butler.clone());
217→    sthalam_shell::callbacks::nodes::register(
218→        &shell,
219→        butler.clone(),
220→        courier_handle.clone(),
221→        tokio_handle.clone(),
222→    );
223→    sthalam_shell::callbacks::publish::register(
224→        &shell,
225→        butler.clone(),
226→        courier_handle.clone(),
227→        tokio_handle.clone(),
228→    );
229→    sthalam_shell::callbacks::viewer::register(
230→        &shell,
231→        butler.clone(),
232→        courier_handle.clone(),
233→        tokio_handle.clone(),
234→    );
235→
236→    // App launching (select_app callback)
237→
238→    // Channel for sending prepared apps from tokio to Slint thread
239→    let (app_ready_tx, app_ready_rx) = std::sync::mpsc::channel::<(
240→        PreparedPage,
241→        ractor::ActorRef<ScribeMessage>,
242→    )>();
243→
244→    // Store launched app timers (drop = window stops processing)
245→    let app_timers: Rc<RefCell<Vec<LaunchedApp>>> = Rc::new(RefCell::new(vec![]));
246→
247→    // App status for debug server
248→    let app_status: Option<Arc<RwLock<AppStatus>>> =
249→        debug_server.as_ref().map(|s| s.app_status());
250→
251→    {
252→        let butler = butler.clone();
253→        let tokio_handle = tokio_handle.clone();
254→        let app_ready_tx = app_ready_tx.clone();
255→        let shell_weak = shell.as_weak();
256→
257→        shell.on_select_app(move |app_name| {
258→            let page_id = if let Some(shell) = shell_weak.upgrade() {
259→                shell.get_current_page_id().to_string()
260→            } else {
261→                return;
262→            };
263→
264→            if page_id.is_empty() {
265→                tracing::warn!("No page selected");
266→                return;
267→            }
268→
269→            let app_name = app_name.to_string();
270→            tracing::info!(page_id = %page_id, app_name = %app_name, "Selecting app");
271→
272→            let butler = butler.clone();
273→            let tx = app_ready_tx.clone();
274→
275→            tokio_handle.spawn(async move {
276→                // Get scribe for this page
277→                let scribe_ref = match butler.open_page(&page_id).await {
278→                    Ok(s) => s,
279→                    Err(e) => {
280→                        tracing::error!(error = %e, "Failed to open page");
281→                        return;
282→                    }
283→                };
284→
285→                // Check manifest to determine renderer
286→                match renderer_slint::get_app_manifest(&scribe_ref, &app_name).await {
287→                    Ok(manifest) if manifest.renderer == "raylib" => {
288→                        #[cfg(feature = "raylib")]
289→                        {
290→                            launch_raylib_app(
291→                                &page_id,
292→                                &app_name,
293→                                butler,
294→                                scribe_ref,
295→                                manifest,
296→                            )
297→                            .await;
298→                        }
299→                        #[cfg(not(feature = "raylib"))]
300→                        {
301→                            tracing::warn!("Raylib renderer not enabled (compile with --features raylib)");
302→                        }
303→                        return;
304→                    }
305→                    Ok(_) => {} // Slint renderer - continue below
306→                    Err(e) => {
307→                        tracing::warn!(error = %e, "Failed to get manifest, assuming Slint renderer");
308→                    }
309→                }
310→
311→                // Prepare Slint app
312→                match renderer_slint::prepare_page(&butler, &page_id, Some(&app_name), &scribe_ref)
313→                    .await
314→                {
315→                    Ok(prepared) => {
316→                        if tx.send((prepared, scribe_ref)).is_err() {
317→                            tracing::error!("Failed to send prepared app to Slint thread");
318→                        }
319→                        // Wake up Slint event loop to process the channel
320→                        slint::invoke_from_event_loop(|| {}).ok();
321→                    }
322→                    Err(e) => {
323→                        tracing::error!(error = %e, "Failed to prepare page");
324→                    }
325→                }
326→            });
327→        });
328→    }
329→
330→    // Refresh app callback
331→
332→    {
333→        let butler = butler.clone();
334→        let tokio_handle = tokio_handle.clone();
335→
336→        shell.on_refresh_app(move |app_name, app_dir| {
337→            let app_name = app_name.to_string();
338→            let app_dir = PathBuf::from(app_dir.to_string());
339→            tracing::info!(app_name = %app_name, app_dir = %app_dir.display(), "Refresh app");
340→
341→            let butler = butler.clone();
342→
343→            tokio_handle.spawn(async move {
344→                // Find page containing this app by searching Butler's spaces/pages
345→                let page_id = find_page_for_app(&butler, &app_name);
346→
347→                if let Some(page_id) = page_id {
348→                    match butler.open_page(&page_id).await {
349→                        Ok(scribe_ref) => {
350→                            let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
351→                            if let Err(e) = scribe_ref.cast(ScribeMessage::RefreshApp {
352→                                app_name: app_name.clone(),
353→                                app_dir,
354→                                reply: reply_tx,
355→                            }) {
356→                                tracing::error!(error = %e, "Failed to send RefreshApp to Scribe");
357→                                return;
358→                            }
359→
360→                            match reply_rx.await {
361→                                Ok(Ok(changed_files)) => {
362→                                    tracing::info!(
363→                                        app_name = %app_name,
364→                                        changed_count = changed_files.len(),
365→                                        "App refreshed"
366→                                    );
367→                                }
368→                                Ok(Err(e)) => {
369→                                    tracing::error!(error = %e, "RefreshApp failed");
370→                                }
371→                                Err(_) => {
372→                                    tracing::error!("RefreshApp reply channel closed");
373→                                }
374→                            }
375→                        }
376→                        Err(e) => {
377→                            tracing::error!(error = %e, page_id = %page_id, "Failed to open page for refresh");
378→                        }
379→                    }
380→                } else {
381→                    tracing::warn!(app_name = %app_name, "Could not find page containing app");
382→                }
383→            });
384→        });
385→    }
386→
387→    // Collector timer: poll app_ready channel, launch windows, connect debug eval
388→
389→    let collector_timer = {
390→        let app_timers = app_timers.clone();
391→        let butler = butler.clone();
392→        let tokio_handle = tokio_handle.clone();
393→        let app_status = app_status.clone();
394→        let debug_server = debug_server.clone();
395→
396→        let timer = slint::Timer::default();
397→        timer.start(
398→            slint::TimerMode::Repeated,
399→            std::time::Duration::from_millis(100),
400→            move || {
401→                while let Ok((prepared, scribe_ref)) = app_ready_rx.try_recv() {
402→                    tracing::info!(
403→                        page_id = %prepared.page_id,
404→                        app_name = %prepared.app_name,
405→                        "Launching app window"
406→                    );
407→
408→                    if let Some(launched) = renderer_slint::launch_slint_app(
409→                        prepared,
410→                        scribe_ref,
411→                        butler.clone(),
412→                        tokio_handle.clone(),
413→                        app_status.clone(),
414→                    ) {
415→                        // Connect debug eval bridge if debug server is active
416→                        if let Some(ref server) = debug_server {
417→                            let lua_tx = launched.lua_tx.clone();
418→
419→                            // Create eval channel: ControlServer -> forwarding task -> LuaCommand
420→                            let (eval_tx, mut eval_rx) =
421→                                tokio::sync::mpsc::channel::<DebugEvalRequest>(32);
422→                            server.set_eval_channel(eval_tx);
423→
424→                            let lua_tx_for_eval = lua_tx.clone();
425→                            tokio_handle.spawn(async move {
426→                                while let Some(req) = eval_rx.recv().await {
427→                                    let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
428→                                    if lua_tx_for_eval
429→                                        .send(lua_runtime::LuaCommand::DebugEval {
430→                                            code: req.code,
431→                                            response_tx: reply_tx,
432→                                        })
433→                                        .await
434→                                        .is_ok()
435→                                    {
436→                                        let result = reply_rx.await.unwrap_or_else(|_| {
437→                                            Err("Eval reply channel closed".to_string())
438→                                        });
439→                                        let _ = req.response_tx.send(result);
440→                                    } else {
441→                                        let _ = req
442→                                            .response_tx
443→                                            .send(Err("Lua worker channel closed".to_string()));
444→                                    }
445→                                }
446→                            });
447→
448→                            // Also set direct lua_worker_tx for the control server
449→                            server.set_lua_worker_channel(lua_tx);
450→                        }
451→
452→                        app_timers.borrow_mut().push(launched);
453→                    }
454→                }
455→            },
456→        );
457→        timer
458→    };
459→
460→    // UI automation timer (if debug server is enabled)
461→
462→    let _ui_timer = if let Some(mut ui_rx) = ui_rx {
463→        let shell_weak = shell.as_weak();
464→        let timer = slint::Timer::default();
465→        timer.start(
466→            slint::TimerMode::Repeated,
467→            std::time::Duration::from_millis(16), // ~60fps
468→            move || {
469→                if let Some(shell) = shell_weak.upgrade() {
470→                    ui_automation::process_ui_commands(&shell, &mut ui_rx);
471→                }
472→            },
473→        );
474→        Some(timer)
475→    } else {
476→        None
477→    };
478→
479→    // Keep timers alive
480→    let _collector_timer = collector_timer;
481→    let _app_timers = app_timers;
482→
483→    // Run the shell
484→    shell.run().expect("Failed to run shell");
485→}
486→
487→/// Spawn background task to auto-reconnect to stored nodes
488→fn spawn_auto_reconnect(butler: Arc<Butler>, handle: CourierHandle) {
489→    tokio::spawn(async move {
490→        // Owner-side: Reconnect to sovereign nodes
491→        let nodes = butler.nodes().list().unwrap_or_default();
492→        for node in nodes {
493→            tracing::info!(name = %node.name, node_id = %node.node_id, "Auto-connecting to sovereign node");
494→            if let Some(permit) = &node.permit {
495→                if let Err(e) = handle.connect(&node.node_id, permit) {
496→                    tracing::warn!(name = %node.name, error = %e, "Failed to initiate connection");
497→                    let _ = butler.nodes().set_connected(&node.node_id, false);
498→                }
499→            } else {
500→                tracing::info!(name = %node.name, "No permit stored, skipping");
501→                let _ = butler.nodes().set_connected(&node.node_id, false);
502→            }
503→        }
504→
505→        // Viewer-side: Reconnect to node contacts
506→        let node_contacts = butler.contacts().list_nodes().unwrap_or_default();
507→        for contact in node_contacts {
508→            if let (Some(node_id), Some(permit)) = (&contact.node_id, &contact.permit) {
509→                tracing::info!(name = %contact.username, node_id = %node_id, "Auto-connecting to node contact");
510→                if let Err(e) = handle.connect(node_id, permit) {
511→                    tracing::warn!(name = %contact.username, error = %e, "Failed to initiate viewer connection");
512→                }
513→            }
514→        }
515→    });
516→}
517→
518→/// Find the page that contains a given app by searching all spaces/pages
519→fn find_page_for_app(butler: &Butler, app_name: &str) -> Option<String> {
520→    let spaces = butler.spaces().list().ok()?;
521→    for space in &spaces {
522→        let pages = butler.pages().list(&space.id).ok()?;
523→        for page in &pages {
524→            let apps = butler.apps().list(&page.id).ok()?;
525→            if apps.iter().any(|a| a == app_name) {
526→                return Some(page.id.clone());
527→            }
528→        }
529→    }
530→    None
531→}
532→
533→/// Launch a Raylib app (when manifest.renderer == "raylib")
534→#[cfg(feature = "raylib")]
535→async fn launch_raylib_app(
536→    page_id: &str,
537→    app_name: &str,
538→    butler: Arc<Butler>,
539→    scribe_ref: ractor::ActorRef<ScribeMessage>,
540→    manifest: renderer_slint::Manifest,
541→) {
542→    let files = match renderer_slint::get_app_files_from_scribe(&scribe_ref, app_name).await {
543→        Ok(f) => f,
544→        Err(e) => {
545→            tracing::error!(error = %e, "Failed to get app files for Raylib app");
546→            return;
547→        }
548→    };
549→
550→    let lua_code = match files.get("app.lua").or_else(|| files.get(&manifest.entry_logic)) {
551→        Some(code) => code.clone(),
552→        None => {
553→            tracing::error!("No Lua entry file found for Raylib app");
554→            return;
555→        }
556→    };
557→
558→    let game_manifest = renderer_raylib::GameManifest {
559→        name: manifest.name.clone(),
560→        version: manifest.version.clone(),
561→        entry_logic: manifest.entry_logic.clone(),
562→        width: manifest.width.unwrap_or(800),
563→        height: manifest.height.unwrap_or(600),
564→        target_fps: manifest.target_fps.unwrap_or(60),
565→    };
566→
567→    if let Err(e) = renderer_raylib::spawn_app(
568→        page_id,
569→        app_name,
570→        butler,
571→        scribe_ref,
572→        game_manifest,
573→        lua_code,
574→    ) {
575→        tracing::error!(error = %e, "Failed to spawn Raylib app");
576→    }
577→}
578→
579→/// Setup profiling tools (tokio-console and/or tracing-flame)
580→///
581→/// **Modes** (based on environment variables):
582→/// - `FLAME_OUTPUT` + `TOKIO_CONSOLE_PORT` → both layers
583→/// - `FLAME_OUTPUT` only → flame layer only (no console overhead)
584→/// - `TOKIO_CONSOLE_PORT` only → console layer only
585→///
586→/// **Environment variables**:
587→/// - `TOKIO_CONSOLE_PORT`: Port for tokio-console (enables console layer)
588→/// - `FLAME_OUTPUT`: Path for flame graph output file (enables flame layer)
589→#[cfg(feature = "profiling")]
590→fn setup_profiling() -> Option<tracing_flame::FlushGuard<std::io::BufWriter<File>>> {
591→    use tracing_subscriber::prelude::*;
592→
593→    let console_port: Option<u16> = std::env::var("TOKIO_CONSOLE_PORT")
594→        .ok()
595→        .and_then(|p| p.parse().ok());
596→    let flame_path = std::env::var("FLAME_OUTPUT").ok();
597→
598→    match (&flame_path, console_port) {
599→        // Both flame + console
600→        (Some(path), Some(port)) => {
601→            let (flame_layer, guard) = match tracing_flame::FlameLayer::with_file(path) {
602→                Ok((layer, guard)) => (Some(layer), Some(guard)),
603→                Err(e) => {
604→                    eprintln!("Failed to create flame layer: {}", e);
605→                    (None, None)
606→                }
607→            };
608→
609→            let console_layer = console_subscriber::ConsoleLayer::builder()
610→                .server_addr(([127, 0, 0, 1], port))
611→                .spawn();
612→
613→            tracing_subscriber::registry()
614→                .with(console_layer)
615→                .with(flame_layer)
616→                .with(tracing_subscriber::fmt::layer().with_target(true).with_level(true))
617→                .init();
618→
619→            tracing::info!(port = port, path = %path, "Profiling: tokio-console + flame");
620→            guard
621→        }
622→        // Flame only (no console overhead)
623→        // Filter out tokio runtime TRACE spans (normally consumed by console-subscriber)
624→        (Some(path), None) => {
625→            let (flame_layer, guard) = match tracing_flame::FlameLayer::with_file(path) {
626→                Ok((layer, guard)) => (Some(layer), Some(guard)),
627→                Err(e) => {
628→                    eprintln!("Failed to create flame layer: {}", e);
629→                    (None, None)
630→                }
631→            };
632→
633→            let filter = tracing_subscriber::EnvFilter::new(
634→                "info,tokio=off,runtime=off",
635→            );
636→
637→            tracing_subscriber::registry()
638→                .with(filter)
639→                .with(flame_layer)
640→                .with(tracing_subscriber::fmt::layer().with_target(true).with_level(true))
641→                .init();
642→
643→            tracing::info!(path = %path, "Profiling: flame only (no console overhead)");
644→            guard
645→        }
646→        // Console only
647→        (None, Some(port)) => {
648→            let console_layer = console_subscriber::ConsoleLayer::builder()
649→                .server_addr(([127, 0, 0, 1], port))
650→                .spawn();
651→
652→            tracing_subscriber::registry()
653→                .with(console_layer)
654→                .with(tracing_subscriber::fmt::layer().with_target(true).with_level(true))
655→                .init();
656→
657→            tracing::info!(port = port, "Profiling: tokio-console only");
658→            None
659→        }
660→        // Neither - just fmt logging
661→        (None, None) => {
662→            let filter = tracing_subscriber::EnvFilter::new(
663→                "info,tokio=off,runtime=off",
664→            );
665→
666→            tracing_subscriber::registry()
667→                .with(filter)
668→                .with(tracing_subscriber::fmt::layer().with_target(true).with_level(true))
669→                .init();
670→
671→            tracing::info!("Profiling feature enabled but no FLAME_OUTPUT or TOKIO_CONSOLE_PORT set");
672→            None
673→        }
674→    }
675→}
