  1→//! Control Server for UI Testing Automation
  2→//!
  3→//! Simplified version using sthalam_shell. Removed unused commands:
  4→//! ui_click, ui_type, ui_get_text, ui_get_screen, ui_list_elements,
  5→//! upload_asset, update_node_address, state.
  6→
  7→use butler::Butler;
  8→use control_server::{
  9→    async_trait, CommandHandler, ControlServer as BaseControlServer, Response, error_codes,
 10→    commands::butler as butler_cmds,
 11→};
 12→use courier::CourierHandle;
 13→use renderer_slint::{AppStatus, DebugEvalRequest};
 14→use std::path::PathBuf;
 15→use std::sync::Arc;
 16→use tokio::sync::{mpsc, oneshot, RwLock};
 17→
 18→// UI Command (simplified — no element-level interaction)
 19→
 20→/// UI automation command (processed on Slint main thread)
 21→#[derive(Debug)]
 22→pub enum UiCommand {
 23→    DirectLogin {
 24→        passphrase: String,
 25→        response_tx: oneshot::Sender<Result<String, String>>,
 26→    },
 27→    SignUp {
 28→        username: String,
 29→        passphrase: String,
 30→        response_tx: oneshot::Sender<Result<String, String>>,
 31→    },
 32→    OpenApp {
 33→        page_id: String,
 34→        app_name: String,
 35→        response_tx: oneshot::Sender<Result<String, String>>,
 36→    },
 37→    CreateSpace {
 38→        name: String,
 39→        template_path: String,
 40→        response_tx: oneshot::Sender<Result<(String, String), String>>,
 41→    },
 42→    AddNode {
 43→        connection_string: String,
 44→        response_tx: oneshot::Sender<Result<String, String>>,
 45→    },
 46→    AddWebsite {
 47→        connection_string: String,
 48→        response_tx: oneshot::Sender<Result<String, String>>,
 49→    },
 50→    RefreshApp {
 51→        app_name: String,
 52→        app_dir: String,
 53→        response_tx: oneshot::Sender<Result<Vec<String>, String>>,
 54→    },
 55→    RefreshPage {
 56→        page_dir: String,
 57→        response_tx: oneshot::Sender<Result<Vec<String>, String>>,
 58→    },
 59→}
 60→
 61→// Shell Handler
 62→
 63→/// Shell-specific command handler
 64→pub struct ShellHandler {
 65→    butler: Arc<RwLock<Option<Arc<Butler>>>>,
 66→    courier_handle: Arc<RwLock<Option<CourierHandle>>>,
 67→    ui_tx: Arc<RwLock<Option<mpsc::Sender<UiCommand>>>>,
 68→    eval_tx: Arc<RwLock<Option<mpsc::Sender<DebugEvalRequest>>>>,
 69→    lua_worker_tx: Arc<RwLock<Option<mpsc::Sender<lua_runtime::LuaCommand>>>>,
 70→    app_status: Arc<RwLock<AppStatus>>,
 71→}
 72→
 73→impl ShellHandler {
 74→    pub fn new(courier_handle: Arc<RwLock<Option<CourierHandle>>>) -> Self {
 75→        Self {
 76→            butler: Arc::new(RwLock::new(None)),
 77→            courier_handle,
 78→            ui_tx: Arc::new(RwLock::new(None)),
 79→            eval_tx: Arc::new(RwLock::new(None)),
 80→            lua_worker_tx: Arc::new(RwLock::new(None)),
 81→            app_status: Arc::new(RwLock::new(AppStatus::new())),
 82→        }
 83→    }
 84→
 85→    pub fn app_status(&self) -> Arc<RwLock<AppStatus>> {
 86→        self.app_status.clone()
 87→    }
 88→
 89→    pub fn set_butler_blocking(&self, butler: Arc<Butler>) {
 90→        *self.butler.blocking_write() = Some(butler);
 91→    }
 92→
 93→    pub fn set_ui_channel_blocking(&self, tx: mpsc::Sender<UiCommand>) {
 94→        *self.ui_tx.blocking_write() = Some(tx);
 95→    }
 96→
 97→    pub fn set_eval_channel_blocking(&self, tx: mpsc::Sender<DebugEvalRequest>) {
 98→        *self.eval_tx.blocking_write() = Some(tx);
 99→    }
100→
101→    pub fn set_lua_worker_channel_blocking(&self, tx: mpsc::Sender<lua_runtime::LuaCommand>) {
102→        *self.lua_worker_tx.blocking_write() = Some(tx);
103→    }
104→}
105→
106→impl Clone for ShellHandler {
107→    fn clone(&self) -> Self {
108→        Self {
109→            butler: self.butler.clone(),
110→            courier_handle: self.courier_handle.clone(),
111→            ui_tx: self.ui_tx.clone(),
112→            eval_tx: self.eval_tx.clone(),
113→            lua_worker_tx: self.lua_worker_tx.clone(),
114→            app_status: self.app_status.clone(),
115→        }
116→    }
117→}
118→
119→/// Helper to get string param
120→fn get_param(params: &Option<serde_json::Value>, key: &str) -> Option<String> {
121→    params.as_ref()?.get(key)?.as_str().map(|s| s.to_string())
122→}
123→
124→#[async_trait]
125→impl CommandHandler for ShellHandler {
126→    async fn handle(&self, method: &str, params: Option<serde_json::Value>, id: u64) -> Option<Response> {
127→        match method {
128→            // Lua Eval
129→            "eval" => {
130→                let code = get_param(&params, "code")?;
131→                let eval_tx = self.eval_tx.read().await;
132→                let Some(tx) = eval_tx.as_ref() else {
133→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "Lua eval not available - no app is open"));
134→                };
135→                let (response_tx, response_rx) = oneshot::channel();
136→                if tx.send(DebugEvalRequest { code, response_tx }).await.is_err() {
137→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "Failed to send eval request"));
138→                }
139→                match response_rx.await {
140→                    Ok(Ok(value)) => Some(Response::ok(id, value)),
141→                    Ok(Err(e)) => Some(Response::err(id, error_codes::OPERATION_FAILED, e)),
142→                    Err(_) => Some(Response::err(id, error_codes::INTERNAL_ERROR, "Eval request dropped")),
143→                }
144→            }
145→
146→            // Butler Commands (shared)
147→            "list_spaces" => {
148→                let butler = self.butler.read().await;
149→                match butler.as_ref() {
150→                    Some(b) => Some(butler_cmds::list_spaces(b, id).await),
151→                    None => Some(Response::err(id, error_codes::NOT_AUTHENTICATED, "Butler not available")),
152→                }
153→            }
154→
155→            "list_pages" => {
156→                let space_id = get_param(&params, "space_id")?;
157→                let butler = self.butler.read().await;
158→                match butler.as_ref() {
159→                    Some(b) => Some(butler_cmds::list_pages(b, &space_id, id).await),
160→                    None => Some(Response::err(id, error_codes::NOT_AUTHENTICATED, "Butler not available")),
161→                }
162→            }
163→
164→            "list_layers" => {
165→                let page_id = get_param(&params, "page_id")?;
166→                let butler = self.butler.read().await;
167→                match butler.as_ref() {
168→                    Some(b) => Some(butler_cmds::list_layers(b, &page_id, id).await),
169→                    None => Some(Response::err(id, error_codes::NOT_AUTHENTICATED, "Butler not available")),
170→                }
171→            }
172→
173→            "list_apps" => {
174→                let page_id = get_param(&params, "page_id")?;
175→                let butler = self.butler.read().await;
176→                let Some(b) = butler.as_ref() else {
177→                    return Some(Response::err(id, error_codes::NOT_AUTHENTICATED, "Butler not available"));
178→                };
179→                match b.apps().list(&page_id) {
180→                    Ok(apps) => {
181→                        let apps_json: Vec<serde_json::Value> = apps.iter()
182→                            .map(|name| serde_json::json!({"name": name}))
183→                            .collect();
184→                        Some(Response::ok(id, serde_json::json!({
185→                            "page_id": page_id,
186→                            "apps": apps_json,
187→                            "count": apps_json.len()
188→                        })))
189→                    }
190→                    Err(e) => Some(Response::err(id, error_codes::OPERATION_FAILED, format!("Failed to list apps: {}", e))),
191→                }
192→            }
193→
194→            "list_nodes" => {
195→                let butler = self.butler.read().await;
196→                let Some(b) = butler.as_ref() else {
197→                    return Some(Response::err(id, error_codes::NOT_AUTHENTICATED, "Butler not available"));
198→                };
199→                match b.nodes().list() {
200→                    Ok(nodes) => {
201→                        let nodes_json: Vec<serde_json::Value> = nodes.iter()
202→                            .map(|n| serde_json::json!({
203→                                "node_id": n.node_id,
204→                                "name": n.name,
205→                                "connected": n.is_connected,
206→                            }))
207→                            .collect();
208→                        Some(Response::ok(id, serde_json::json!({
209→                            "nodes": nodes_json,
210→                            "count": nodes_json.len()
211→                        })))
212→                    }
213→                    Err(e) => Some(Response::err(id, error_codes::OPERATION_FAILED, format!("Failed to list nodes: {}", e))),
214→                }
215→            }
216→
217→            "is_node_authenticated" => {
218→                let node_id = get_param(&params, "node_id")?;
219→
220→                let courier = self.courier_handle.read().await;
221→                let Some(courier_handle) = courier.as_ref() else {
222→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "P2P not connected"));
223→                };
224→
225→                match courier_handle.is_node_authenticated(&node_id).await {
226→                    Ok(is_auth) => Some(Response::ok(id, serde_json::json!({
227→                        "node_id": node_id,
228→                        "authenticated": is_auth
229→                    }))),
230→                    Err(e) => Some(Response::err(id, error_codes::OPERATION_FAILED, format!("Failed to check auth: {}", e))),
231→                }
232→            }
233→
234→            // Auth Commands
235→            "login" => {
236→                let passphrase = get_param(&params, "passphrase")?;
237→                let ui_tx = self.ui_tx.read().await;
238→                let Some(tx) = ui_tx.as_ref() else {
239→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "UI automation not available"));
240→                };
241→                let (response_tx, response_rx) = oneshot::channel();
242→                if tx.send(UiCommand::DirectLogin { passphrase, response_tx }).await.is_err() {
243→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "Failed to send login command"));
244→                }
245→                match response_rx.await {
246→                    Ok(Ok(did)) => Some(Response::ok(id, serde_json::json!({"success": true, "did": did}))),
247→                    Ok(Err(e)) => Some(Response::err(id, error_codes::OPERATION_FAILED, e)),
248→                    Err(_) => Some(Response::err(id, error_codes::INTERNAL_ERROR, "Login command dropped")),
249→                }
250→            }
251→
252→            "sign_up" => {
253→                let username = get_param(&params, "username")?;
254→                let passphrase = get_param(&params, "passphrase")?;
255→                let ui_tx = self.ui_tx.read().await;
256→                let Some(tx) = ui_tx.as_ref() else {
257→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "UI automation not available"));
258→                };
259→                let (response_tx, response_rx) = oneshot::channel();
260→                if tx.send(UiCommand::SignUp { username, passphrase, response_tx }).await.is_err() {
261→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "Failed to send signup command"));
262→                }
263→                match response_rx.await {
264→                    Ok(Ok(did)) => Some(Response::ok(id, serde_json::json!({"success": true, "did": did}))),
265→                    Ok(Err(e)) => Some(Response::err(id, error_codes::OPERATION_FAILED, e)),
266→                    Err(_) => Some(Response::err(id, error_codes::INTERNAL_ERROR, "Signup command dropped")),
267→                }
268→            }
269→
270→            // App Commands
271→            "open_app" => {
272→                let page_id = get_param(&params, "page_id")?;
273→                let app_name = get_param(&params, "app_name")?;
274→
275→                {
276→                    let mut status = self.app_status.write().await;
277→                    status.page_id = Some(page_id.clone());
278→                    status.app_name = Some(app_name.clone());
279→                    status.status = "loading".to_string();
280→                    status.error = None;
281→                    status.loaded_at = None;
282→                }
283→
284→                let ui_tx = self.ui_tx.read().await;
285→                let Some(tx) = ui_tx.as_ref() else {
286→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "UI automation not available"));
287→                };
288→                let (response_tx, response_rx) = oneshot::channel();
289→                if tx.send(UiCommand::OpenApp { page_id: page_id.clone(), app_name: app_name.clone(), response_tx }).await.is_err() {
290→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "Failed to send open_app command"));
291→                }
292→                match response_rx.await {
293→                    Ok(Ok(msg)) => Some(Response::ok(id, serde_json::json!({
294→                        "success": true,
295→                        "page_id": page_id,
296→                        "app_name": app_name,
297→                        "message": msg
298→                    }))),
299→                    Ok(Err(e)) => Some(Response::err(id, error_codes::OPERATION_FAILED, e)),
300→                    Err(_) => Some(Response::err(id, error_codes::INTERNAL_ERROR, "Open app command dropped")),
301→                }
302→            }
303→
304→            "get_app_status" => {
305→                let status = self.app_status.read().await.clone();
306→                Some(Response::ok(id, serde_json::to_value(status).unwrap_or(serde_json::Value::Null)))
307→            }
308→
309→            "refresh_app" => {
310→                let app_name = get_param(&params, "app_name")?;
311→                let app_dir = get_param(&params, "app_dir")?;
312→                let ui_tx = self.ui_tx.read().await;
313→                let Some(tx) = ui_tx.as_ref() else {
314→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "UI automation not available"));
315→                };
316→                let (response_tx, response_rx) = oneshot::channel();
317→                if tx.send(UiCommand::RefreshApp { app_name: app_name.clone(), app_dir: app_dir.clone(), response_tx }).await.is_err() {
318→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "Failed to send refresh_app command"));
319→                }
320→                match response_rx.await {
321→                    Ok(Ok(changed_files)) => Some(Response::ok(id, serde_json::json!({
322→                        "success": true,
323→                        "app_name": app_name,
324→                        "app_dir": app_dir,
325→                        "changed_files": changed_files,
326→                        "changed_count": changed_files.len()
327→                    }))),
328→                    Ok(Err(e)) => Some(Response::err(id, error_codes::OPERATION_FAILED, e)),
329→                    Err(_) => Some(Response::err(id, error_codes::INTERNAL_ERROR, "RefreshApp command dropped")),
330→                }
331→            }
332→
333→            "refresh_page" => {
334→                let page_dir = get_param(&params, "page_dir")?;
335→                let ui_tx = self.ui_tx.read().await;
336→                let Some(tx) = ui_tx.as_ref() else {
337→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "UI automation not available"));
338→                };
339→                let (response_tx, response_rx) = oneshot::channel();
340→                if tx.send(UiCommand::RefreshPage { page_dir: page_dir.clone(), response_tx }).await.is_err() {
341→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "Failed to send refresh_page command"));
342→                }
343→                match response_rx.await {
344→                    Ok(Ok(updated_apps)) => Some(Response::ok(id, serde_json::json!({
345→                        "success": true,
346→                        "page_dir": page_dir,
347→                        "updated_apps": updated_apps,
348→                        "updated_count": updated_apps.len()
349→                    }))),
350→                    Ok(Err(e)) => Some(Response::err(id, error_codes::OPERATION_FAILED, e)),
351→                    Err(_) => Some(Response::err(id, error_codes::INTERNAL_ERROR, "RefreshPage command dropped")),
352→                }
353→            }
354→
355→            // Space/Page Management
356→            "create_space" => {
357→                let name = get_param(&params, "name")?;
358→                let template_path = get_param(&params, "template_path")?;
359→
360→                // Validate Slint files before creating
361→                let template_dir = PathBuf::from(&template_path);
362→                if template_dir.exists() {
363→                    if let Err(e) = renderer_slint::validate_slint_files(&template_dir).await {
364→                        return Some(Response::err(id, error_codes::OPERATION_FAILED, e));
365→                    }
366→                }
367→
368→                let ui_tx = self.ui_tx.read().await;
369→                let Some(tx) = ui_tx.as_ref() else {
370→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "UI automation not available"));
371→                };
372→                let (response_tx, response_rx) = oneshot::channel();
373→                if tx.send(UiCommand::CreateSpace { name, template_path, response_tx }).await.is_err() {
374→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "Failed to send create_space command"));
375→                }
376→                match response_rx.await {
377→                    Ok(Ok((space_id, space_name))) => Some(Response::ok(id, serde_json::json!({
378→                        "id": space_id,
379→                        "name": space_name,
380→                    }))),
381→                    Ok(Err(e)) => Some(Response::err(id, error_codes::OPERATION_FAILED, e)),
382→                    Err(_) => Some(Response::err(id, error_codes::INTERNAL_ERROR, "Create space command dropped")),
383→                }
384→            }
385→
386→            "import_page" => {
387→                let space_id = get_param(&params, "space_id")?;
388→                let page_dir = get_param(&params, "page_dir")?;
389→
390→                let butler = self.butler.read().await;
391→                let Some(b) = butler.as_ref() else {
392→                    return Some(Response::err(id, error_codes::NOT_AUTHENTICATED, "Butler not available"));
393→                };
394→
395→                let page_path = PathBuf::from(&page_dir);
396→                if !page_path.exists() {
397→                    return Some(Response::err(id, error_codes::OPERATION_FAILED, format!("Page directory not found: {}", page_dir)));
398→                }
399→
400→                // Validate Slint files before importing
401→                if let Err(e) = renderer_slint::validate_slint_files(&page_path).await {
402→                    return Some(Response::err(id, error_codes::OPERATION_FAILED, e));
403→                }
404→
405→                match b.apps().import_page(&space_id, &page_path).await {
406→                    Ok(page) => {
407→                        let apps = b.apps().list(&page.id).unwrap_or_default();
408→                        Some(Response::ok(id, serde_json::json!({
409→                            "page_id": page.id,
410→                            "page_name": page.name,
411→                            "apps": apps,
412→                        })))
413→                    }
414→                    Err(e) => Some(Response::err(id, error_codes::OPERATION_FAILED, format!("Failed to import page: {}", e))),
415→                }
416→            }
417→
418→            // Node/P2P Commands
419→            "add_node" => {
420→                let connection_string = get_param(&params, "connection_string")?;
421→                let ui_tx = self.ui_tx.read().await;
422→                let Some(tx) = ui_tx.as_ref() else {
423→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "UI automation not available"));
424→                };
425→                let (response_tx, response_rx) = oneshot::channel();
426→                if tx.send(UiCommand::AddNode { connection_string, response_tx }).await.is_err() {
427→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "Failed to send add_node command"));
428→                }
429→                match response_rx.await {
430→                    Ok(Ok(node_id)) => Some(Response::ok(id, serde_json::json!({
431→                        "success": true,
432→                        "node_id": node_id,
433→                        "triggered": true
434→                    }))),
435→                    Ok(Err(e)) => Some(Response::err(id, error_codes::OPERATION_FAILED, e)),
436→                    Err(_) => Some(Response::err(id, error_codes::INTERNAL_ERROR, "Add node command dropped")),
437→                }
438→            }
439→
440→            "add_website" => {
441→                let connection_string = get_param(&params, "connection_string")?;
442→                let ui_tx = self.ui_tx.read().await;
443→                let Some(tx) = ui_tx.as_ref() else {
444→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "UI automation not available"));
445→                };
446→                let (response_tx, response_rx) = oneshot::channel();
447→                if tx.send(UiCommand::AddWebsite { connection_string, response_tx }).await.is_err() {
448→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "Failed to send add_website command"));
449→                }
450→                match response_rx.await {
451→                    Ok(Ok(space_id)) => Some(Response::ok(id, serde_json::json!({
452→                        "success": true,
453→                        "space_id": space_id,
454→                        "triggered": true
455→                    }))),
456→                    Ok(Err(e)) => Some(Response::err(id, error_codes::OPERATION_FAILED, e)),
457→                    Err(_) => Some(Response::err(id, error_codes::INTERNAL_ERROR, "Add website command dropped")),
458→                }
459→            }
460→
461→            "publish_space" => {
462→                let space_id = get_param(&params, "space_id")?;
463→                let node_id = get_param(&params, "node_id")?;
464→
465→                let butler = self.butler.read().await;
466→                let Some(b) = butler.as_ref() else {
467→                    return Some(Response::err(id, error_codes::NOT_AUTHENTICATED, "Butler not available"));
468→                };
469→
470→                let node = match b.nodes().get(&node_id) {
471→                    Ok(Some(n)) => n,
472→                    Ok(None) => return Some(Response::err(id, error_codes::NOT_FOUND, format!("Node not found: {}", node_id))),
473→                    Err(e) => return Some(Response::err(id, error_codes::OPERATION_FAILED, format!("Failed to get node: {}", e))),
474→                };
475→
476→                let courier = self.courier_handle.read().await;
477→                let Some(courier_handle) = courier.as_ref() else {
478→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "P2P not connected"));
479→                };
480→
481→                match courier_handle.publish_space(&space_id, &node_id).await {
482→                    Ok(_) => {
483→                        let _ = b.publish().mark_space_published(&space_id, &node_id);
484→                        Some(Response::ok(id, serde_json::json!({
485→                            "success": true,
486→                            "space_id": space_id,
487→                            "node_id": node_id,
488→                            "node_name": node.name
489→                        })))
490→                    }
491→                    Err(e) => Some(Response::err(id, error_codes::OPERATION_FAILED, format!("Failed to publish space: {}", e))),
492→                }
493→            }
494→
495→            "get_shareable_link" => {
496→                let space_id = get_param(&params, "space_id")?;
497→                let node_id = get_param(&params, "node_id")?;
498→
499→                let courier = self.courier_handle.read().await;
500→                let Some(courier_handle) = courier.as_ref() else {
501→                    return Some(Response::err(id, error_codes::INTERNAL_ERROR, "P2P not connected"));
502→                };
503→
504→                match courier_handle.get_shareable_link(&space_id, &node_id).await {
505→                    Ok(connection_string) => Some(Response::ok(id, serde_json::json!({
506→                        "connection_string": connection_string,
507→                        "space_id": space_id,
508→                        "node_id": node_id
509→                    }))),
510→                    Err(e) => Some(Response::err(id, error_codes::OPERATION_FAILED, format!("Failed to get shareable link: {}", e))),
511→                }
512→            }
513→
514→            "p2p_status" => {
515→                let butler_ready = self.butler.read().await.is_some();
516→                let courier_ready = self.courier_handle.read().await.is_some();
517→                Some(Response::ok(id, serde_json::json!({
518→                    "butler_ready": butler_ready,
519→                    "courier_ready": courier_ready,
520→                    "p2p_ready": butler_ready && courier_ready
521→                })))
522→            }
523→
524→            _ => None,
525→        }
526→    }
527→
528→    async fn get_connection_string(&self) -> Option<String> {
