        let handler = Arc::new(ShellHandler::new(courier_handle));
        let inner = BaseControlServer::new(socket_path, instance_name, (*handler).clone());
        Self { inner, handler }
    }

    pub fn app_status(&self) -> Arc<RwLock<AppStatus>> {
        self.handler.app_status()
