409→/// Handle post-apply actions for remote updates
410→///
411→/// **Context**: Remote update was successfully applied
412→/// **We do**: Flush app layers immediately
413→/// **Note**: UI notification is handled by Loro observer (no duplicate emit here)
414→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
415→async fn handle_post_apply(
416→    state: &mut ScribeState,
417→    layer_name: &str,
418→    _from_peer: Option<(String, String)>,
419→) {
420→    // For app layers, flush immediately to storage so restart loads new code
421→    if layer_name.starts_with("app:") {
422→        if let Some(unit) = state.units.get_mut(layer_name) {
423→            let snapshot = unit.layer().export_snapshot();
424→            if let Err(e) = state.layer_storage.save_layer(layer_name, &snapshot) {
425→                error!(layer = %layer_name, error = %e, "Failed to save app layer immediately");
426→            } else {
427→                info!(layer = %layer_name, "Saved app layer immediately for restart");
428→                // Remove from dirty since we just saved it
429→                unit.clear_dirty();
430→            }
431→        }
432→    }
433→
434→    // Note: UI notification via emit_layer_changed_after_apply was removed
435→    // The Loro observer handles PageUpdate::LayerChanged for all changes (local and remote)
436→    // This prevents duplicate notifications
437→}
