  1→//! Handshake handlers for peer authentication
  2→//!
  3→//! Flow:
  4→//! 1. User sends Hello → Node
  5→//! 2. Node validates (via decision), sends Welcome → User
  6→//! 3. User validates Welcome (via decision), sends PermitGrant → Node
  7→//! 4. Node validates PermitGrant (via decision), sends Ack → User
  8→//! 5. Both sides authenticated
  9→//!
 10→//! ## Design (Capability-Based)
 11→//!
 12→//! The protocol is completely role-agnostic. All handshake decisions are based on
 13→//! capabilities derived directly from the permit structure:
 14→//!
 15→//! - `accept_publish: true` → Peer can publish spaces to this node
 16→//! - `first_connection: true` → First time connecting (needs OwnerInfo stored)
 17→//!
 18→//! Security model (capability-based decisions):
 19→//! - Node decides how to respond to Hello based on capabilities
 20→//! - User validates Welcome permit audience
 21→//! - Node validates PermitGrant permit from user
 22→
 23→use base64::{engine::general_purpose::STANDARD, Engine};
 24→use tracing::{debug, error, info, warn, instrument};
 25→
 26→use herald::Identity;
 27→use crate::handshake::{
 28→    HelloDecision, WelcomeDecision, PermitGrantDecision,
 29→    HelloContext, WelcomeContext, PermitGrantContext,
 30→    decide_hello_response, decide_welcome_response, decide_permit_grant_response,
 31→    can_publish,
 32→};
 33→
 34→use crate::message::*;
 35→use crate::state::{PeerState, PeerType};
 36→use butler::OwnerInfo;
 37→
 38→use transport::Connection;
 39→
 40→use super::guards::{require_node_mode, require_user_mode, parse_permit};
 41→use super::{PeerActor, PeerActorState};
 42→
 43→impl<C: Connection> PeerActor<C> {
 44→
 45→    /// Initiate handshake by sending Hello (User mode only)
 46→    ///
 47→    /// **Context**: User connects to Node and starts handshake
 48→    /// **We send**: Hello with our identity and permit
 49→    /// **Next**: Wait for Welcome
 50→    #[instrument(skip(self, state, permit))]
 51→    pub(super) async fn initiate_handshake(&self, permit: &str, state: &mut PeerActorState<C>) {
 52→        if require_user_mode(state.mode, "initiate_handshake").is_some() {
 53→            return;
 54→        }
 55→
 56→        if !matches!(state.state, PeerState::Connected) {
 57→            warn!("Cannot initiate handshake in state {}", state.state.name());
 58→            return;
 59→        }
 60→
 61→        // Parse the permit to extract capabilities
 62→        let parsed_permit = match parse_permit(permit) {
 63→            Ok(p) => p,
 64→            Err(e) => {
 65→                error!("Invalid permit for handshake: {}", e);
 66→                state.state = PeerState::fail("Invalid permit");
 67→                return;
 68→            }
 69→        };
 70→
 71→        // Extract capability from permit
 72→        let our_can_publish = can_publish(&parsed_permit);
 73→        debug!(can_publish = our_can_publish, "Extracted capabilities from permit");
 74→
 75→        // Get our identity from Butler
 76→        let user_info = match state.butler.user_info().await {
 77→            Ok(info) => info,
 78→            Err(e) => {
 79→                error!("Failed to get user info: {}", e);
 80→                state.state = PeerState::fail("No identity");
 81→                return;
 82→            }
 83→        };
 84→
 85→        // Get expected node verifying key from sovereign node record
 86→        // We compare against the verifying key (extracted from DID), not the device key
 87→        let node_id_str = self.node_id.to_string();
 88→        let expected_node_pubkey = match state.butler.nodes().get(&node_id_str) {
 89→            Ok(Some(sovereign_node)) => {
 90→                // Extract the 32-byte public key from DID format
 91→                // DID is "did:key:z6Mk..." - we need the raw bytes for comparison
 92→                match Identity::public_key_from_did(&sovereign_node.did) {
 93→                    Ok(bytes) => bytes.to_vec(),
 94→                    Err(e) => {
 95→                        error!("Failed to extract pubkey from node DID: {}", e);
 96→                        state.state = PeerState::fail("Invalid node public key");
 97→                        return;
 98→                    }
 99→                }
100→            }
101→            Ok(None) => {
102→                // Peer flow - might not have sovereign node record
103→                // Use empty vec, validation will be done differently
104→                warn!("No sovereign node record, proceeding without node pubkey validation");
105→                vec![]
106→            }
107→            Err(e) => {
108→                error!("Failed to get sovereign node: {}", e);
109→                state.state = PeerState::fail("Failed to get node info");
110→                return;
111→            }
112→        };
113→
114→        let timestamp = chrono::Utc::now().timestamp();
115→
116→        // TODO: Sign (did + timestamp) with signing key
117→        let signature = vec![];
118→
119→        // Convert public keys to [u8; 32] arrays
120→        let public_key: [u8; 32] = user_info.public_key.clone().try_into()
121→            .expect("public_key should be 32 bytes");
122→        let encryption_key: [u8; 32] = user_info.encryption_key.clone().try_into()
123→            .expect("encryption_key should be 32 bytes");
124→
125→        let hello = Message::Hello(HelloMsg {
126→            protocol_version: PROTOCOL_VERSION,
127→            did: user_info.did.clone(),
128→            username: user_info.username.clone(),
129→            public_key,
130→            encryption_key,
131→            signature,
132→            timestamp,
133→            permit: permit.to_string(),
134→        });
135→
136→        info!(can_publish = our_can_publish, "Sending Hello to {} as {}", self.node_id, user_info.username);
137→        self.send_message(&hello, state).await;
138→
139→        // Transition to AwaitingWelcome with capability tracking
140→        state.state = PeerState::AwaitingWelcome {
141→            our_did: user_info.did,
142→            our_username: user_info.username,
143→            sent_at: timestamp,
144→            can_publish: our_can_publish,
145→            expected_node_pubkey,
146→            our_permit: permit.to_string(),
147→        };
148→    }
149→
150→    /// Handle Hello message (Node mode receives this)
151→    ///
152→    /// **Context**: Peer connects to us (the Node)
153→    /// **Peer sends**: Hello with identity and permit
154→    /// **We call**: decide_hello_response() for decision
155→    /// **We execute**: Accept (store info, issue permit) or Reject
156→    /// **We send**: Welcome with permit_for_peer
157→    #[instrument(skip(self, state, public_key, encryption_key, permit), fields(peer_did = %did, peer_username = %username))]
158→    pub(super) async fn on_hello(
159→        &self,
160→        did: &str,
161→        username: &str,
162→        public_key: &[u8; 32],
163→        encryption_key: &[u8; 32],
164→        permit: &str,
165→        state: &mut PeerActorState<C>,
166→    ) {
167→        if require_node_mode(state.mode, "on_hello").is_some() {
168→            return;
169→        }
170→
171→        if !matches!(state.state, PeerState::Connected) {
172→            warn!("Unexpected Hello in state {}", state.state.name());
173→            return;
174→        }
175→
176→        // Store peer's encryption key for ECDH during SyncOffer
177→        state.peer_encryption_key = Some(*encryption_key);
178→
179→        info!("Received Hello from {} ({})", username, did);
180→
181→        // Parse and validate permit, cache for later use
182→        let parsed_permit = match parse_permit(permit) {
183→            Ok(p) => p,
184→            Err(e) => {
185→                self.reject(&e, state).await;
186→                return;
187→            }
188→        };
189→        state.cached_peer_permit = Some(parsed_permit.clone());
190→
191→        let peer_can_publish = can_publish(&parsed_permit);
192→        let is_first_connection = parsed_permit.is_first_connection();
193→        debug!(can_publish = peer_can_publish, is_first_connection, "Permit capabilities parsed");
194→
195→        // Check if we already have an owner
196→        let existing_owner = match state.butler.nodes().get_owner() {
197→            Ok(owner) => owner,
198→            Err(e) => {
199→                error!("Failed to check owner: {}", e);
200→                self.reject("Internal error", state).await;
201→                return;
202→            }
203→        };
204→
205→        // Build context for decision
206→        let ctx = HelloContext {
207→            incoming_permit: &parsed_permit,
208→            incoming_did: did,
209→            existing_owner_did: existing_owner.as_ref().map(|o| o.did.as_str()),
210→            existing_owner_permit: existing_owner.as_ref().and_then(|o| o.permit.as_deref()),
211→        };
212→
213→        // Get decision
214→        let decision = decide_hello_response(&ctx);
215→        debug!(?decision, "Hello decision");
216→
217→        // Execute decision
218→        match decision {
219→            HelloDecision::AcceptFirstConnection { can_publish } => {
220→                self.handle_first_connection(did, username, public_key, encryption_key, can_publish, state).await;
221→            }
222→            HelloDecision::AcceptReconnection { stored_permit, can_publish } => {
223→                self.handle_reconnection(did, username, &stored_permit, can_publish, state).await;
224→            }
225→            HelloDecision::AcceptPeer => {
226→                self.handle_peer_connection(did, username, public_key, encryption_key, state).await;
227→            }
228→            HelloDecision::RejectAlreadyHasOwner => {
229→                self.reject("Node already has an owner", state).await;
230→            }
231→            HelloDecision::RejectOwnerMismatch => {
232→                self.reject("Owner DID mismatch", state).await;
233→            }
234→            HelloDecision::RejectNoOwnerForReconnection => {
235→                self.reject("No owner registered for reconnection", state).await;
236→            }
237→        }
238→    }
239→
240→    /// Handle first connection from peer who can publish (Node mode)
241→    ///
242→    /// **Context**: New peer connecting for the first time with publish capability
243→    /// **We store**: OwnerInfo (if can_publish)
244→    /// **We issue**: peer_connection permit
245→    /// **We send**: Welcome
246→    #[instrument(skip_all, fields(peer_did = %did, peer_username = %username, can_publish = peer_can_publish))]
247→    async fn handle_first_connection(
248→        &self,
249→        did: &str,
250→        username: &str,

250→        username: &str,
251→        public_key: &[u8; 32],
252→        encryption_key: &[u8; 32],
253→        peer_can_publish: bool,
254→        state: &mut PeerActorState<C>,
255→    ) {
256→        // Store owner info if peer can publish
257→        if peer_can_publish {
258→            let encryption_key_base64 = STANDARD.encode(encryption_key);
259→            let owner_info = OwnerInfo::new(
260→                did.to_string(),
261→                encryption_key_base64,
262→                username.to_string(),
263→            );
264→
265→            if let Err(e) = state.butler.nodes().set_owner(&owner_info) {
266→                error!("Failed to store owner info: {}", e);
267→                self.reject("Failed to store owner", state).await;
268→                return;
269→            }
270→
271→            info!("Stored owner info for first connection");
272→        }
273→
274→        // Issue new permit for the peer
275→        // Relationship determines permit type - gurkha expects node_owner or node_viewer
276→        let relationship = if peer_can_publish { "node_owner" } else { "node_viewer" };
277→        let peer_pubkey = STANDARD.encode(public_key);
278→        let (permit_for_peer, _our_pubkey) = match state.butler.issue_peer_connection_permit(&peer_pubkey, relationship).await {
279→            Ok(result) => result,
280→            Err(e) => {
281→                error!("Failed to issue permit: {}", e);
282→                self.reject("Failed to issue permit", state).await;
283→                return;
284→            }
285→        };
286→
287→        // Store the permit we issued (for reconnection)
288→        if peer_can_publish {
289→            if let Err(e) = state.butler.nodes().set_owner_permit(permit_for_peer.clone()) {
290→                warn!("Failed to store owner permit: {}", e);
291→            }
292→        }
293→
294→        // Send Welcome
295→        self.send_welcome_message(&permit_for_peer, state).await;
296→
297→        // Transition to AwaitingPermitGrant
298→        state.state = PeerState::AwaitingPermitGrant {
299→            their_did: did.to_string(),
300→            their_username: username.to_string(),
301→            is_first_connection: true,
302→            can_publish: peer_can_publish,
303→        };
304→    }
305→
306→    /// Handle reconnection from known peer (Node mode)
307→    ///
308→    /// **Context**: Known peer reconnecting
309→    /// **We send**: Welcome with stored permit
310→    #[instrument(skip_all, fields(peer_did = %did, peer_username = %username, can_publish = peer_can_publish))]
311→    async fn handle_reconnection(
312→        &self,
313→        did: &str,
314→        username: &str,
315→        stored_permit: &str,
316→        peer_can_publish: bool,
317→        state: &mut PeerActorState<C>,
318→    ) {
319→        debug!(can_publish = peer_can_publish, "Reconnection from known peer");
320→        if peer_can_publish {
321→            let _ = state.butler.nodes().update_owner_last_connected();
322→        }
323→
324→        // Send Welcome with stored permit
325→        self.send_welcome_message(stored_permit, state).await;
326→
327→        // Transition to AwaitingPermitGrant (waiting for Ack)
328→        state.state = PeerState::AwaitingPermitGrant {
329→            their_did: did.to_string(),
330→            their_username: username.to_string(),
331→            is_first_connection: false,
332→            can_publish: peer_can_publish,
333→        };
334→    }
335→
336→    /// Handle peer connection (Node mode)
337→    ///
338→    /// **Context**: Peer connecting without publish capability
339→    /// **We store**: Contact record with peer's device (NodeId)
340→    /// **We issue**: peer_connection permit
341→    /// **We send**: Welcome
342→    #[instrument(skip_all, fields(peer_did = %did, peer_username = %username))]
343→    async fn handle_peer_connection(
344→        &self,
345→        did: &str,
346→        username: &str,
347→        public_key: &[u8; 32],
348→        encryption_key: &[u8; 32],
349→        state: &mut PeerActorState<C>,
350→    ) {
351→        info!("Accepting peer connection from {} ({})", username, did);
352→
353→        // Issue permit for peer - gurkha expects node_viewer for non-publishing peers
354→        let peer_pubkey = STANDARD.encode(public_key);
355→        let (permit_for_peer, _our_pubkey) = match state.butler.issue_peer_connection_permit(&peer_pubkey, "node_viewer").await {
356→            Ok(result) => result,
357→            Err(e) => {
358→                error!("Failed to issue peer permit: {}", e);
359→                self.reject("Failed to issue permit", state).await;
360→                return;
361→            }
362→        };
363→
364→        // Store peer as User contact with their device (NodeId)
365→        let encryption_key_base64 = STANDARD.encode(encryption_key);
366→        let mut contact = butler::ContactData::new(
367→            did.to_string(),
368→            encryption_key_base64,
369→            username.to_string(),
370→        );
371→        contact.add_device(self.node_id.to_string(), "default".to_string());
372→
373→        if let Err(e) = state.butler.contacts().upsert(&contact) {
374→            warn!("Failed to store peer contact: {}", e);
375→        } else {
376→            debug!(did = %did, device_id = %self.node_id, "Stored peer contact with device");
377→        }
378→
379→        // Send Welcome
380→        self.send_welcome_message(&permit_for_peer, state).await;
381→
382→        // Transition to AwaitingPermitGrant
383→        state.state = PeerState::AwaitingPermitGrant {
384→            their_did: did.to_string(),
385→            their_username: username.to_string(),
386→            is_first_connection: true,
387→            can_publish: false,
388→        };
389→    }
390→
391→    /// Send Welcome message with our identity and permit for peer
392→    #[instrument(skip_all, fields(node = %self.node_id))]
393→    async fn send_welcome_message(&self, permit_for_peer: &str, state: &mut PeerActorState<C>) {
394→        let our_identity = match state.butler.get_identity().await {
395→            Ok(identity) => identity,
396→            Err(e) => {
397→                error!("Failed to get identity for Welcome: {}", e);
398→                state.state = PeerState::fail("Internal error");
399→                return;
400→            }
401→        };
402→
403→        let node_public_key: [u8; 32] = our_identity.public_signing_key().try_into()
404→            .expect("public_signing_key should be 32 bytes");
405→        let node_encryption_key: [u8; 32] = our_identity.public_encryption_key().try_into()
406→            .expect("public_encryption_key should be 32 bytes");
407→
408→        let timestamp = chrono::Utc::now().timestamp();
409→        let signature = vec![]; // TODO: Sign
410→
411→        let welcome = Message::Welcome(WelcomeMsg {
412→            protocol_version: PROTOCOL_VERSION,
413→            node_id: self.node_id.to_string(),
414→            node_public_key,
415→            node_encryption_key,
416→            signature,
417→            timestamp,
418→            permit_for_peer: permit_for_peer.to_string(),
419→        });
420→
421→        info!("Sending Welcome");
422→        self.send_message(&welcome, state).await;
423→    }
424→
425→    /// Handle Welcome message (User mode receives this)
426→    ///
427→    /// **Context**: Node responded to our Hello
428→    /// **We call**: decide_welcome_response() for decision
429→    /// **We validate**: Node identity, permit audience
430→    /// **We issue**: Reciprocal permit
431→    /// **We send**: PermitGrant
432→    #[instrument(skip(self, myself, state, permit_for_us))]
433→    pub(super) async fn on_welcome(
434→        &self,
435→        myself: ractor::ActorRef<super::PeerMessage>,
436→        permit_for_us: &str,
437→        node_public_key: &[u8; 32],
438→        node_encryption_key: &[u8; 32],
439→        state: &mut PeerActorState<C>,
440→    ) {
441→        if require_user_mode(state.mode, "on_welcome").is_some() {
442→            return;
443→        }
444→
445→        // Extract state data
446→        let (our_did, our_username, _our_can_publish, expected_node_pubkey, our_permit) = match &state.state {
447→            PeerState::AwaitingWelcome { our_did, our_username, can_publish, expected_node_pubkey, our_permit, .. } => {
448→                (our_did.clone(), our_username.clone(), *can_publish, expected_node_pubkey.clone(), our_permit.clone())
449→            }
450→            _ => {
451→                warn!("Unexpected Welcome in state {}", state.state.name());
452→                return;
453→            }
454→        };
455→
456→        info!("Received Welcome from {}", self.node_id);
457→
458→        // Store peer's encryption key for ECDH
459→        state.peer_encryption_key = Some(*node_encryption_key);
460→
461→        // Parse the permit we received, cache for later use
462→        let parsed_permit = match parse_permit(permit_for_us) {
463→            Ok(p) => p,
464→            Err(e) => {
465→                warn!("Invalid permit in Welcome: {}", e);
466→                state.state = PeerState::fail("Invalid permit received");
467→                return;
468→            }
469→        };
470→        state.cached_peer_permit = Some(parsed_permit.clone());
471→
472→        // Parse our original permit for WelcomeContext
473→        let our_parsed_permit = match parse_permit(&our_permit) {
474→            Ok(p) => p,
475→            Err(e) => {
476→                error!("Failed to parse our stored permit: {}", e);
477→                state.state = PeerState::fail("Internal error");
478→                return;
479→            }
480→        };
481→
482→        // Get our public key for audience validation
483→        // Permits use base64-encoded pubkey as audience, not DID
484→        let our_pubkey_b64 = match state.butler.user_info().await {
485→            Ok(info) => STANDARD.encode(&info.public_key),
486→            Err(e) => {
487→                error!("Failed to get user info for audience validation: {}", e);
488→                state.state = PeerState::fail("Internal error");
489→                return;
490→            }
491→        };
492→
493→        // Build context for decision
494→        let ctx = WelcomeContext {
495→            our_permit: &our_parsed_permit,
496→            our_did: &our_did,
497→            our_pubkey_b64: &our_pubkey_b64,
498→            expected_node_pubkey: &expected_node_pubkey,
499→            received_node_pubkey: node_public_key,
500→            received_permit: &parsed_permit,
501→        };
502→
503→        // Get decision
504→        let decision = decide_welcome_response(&ctx);
505→        debug!(?decision, "Welcome decision");
506→
507→        // Execute decision
508→        match decision {
509→            WelcomeDecision::Accept { can_publish } => {
510→                self.complete_welcome_flow(
511→                    myself,
512→                    permit_for_us,
513→                    &our_did,
514→                    &our_username,
515→                    can_publish,
516→                    node_public_key,
517→                    state,
518→                ).await;
519→            }
520→            WelcomeDecision::RejectNodeMismatch => {
521→                warn!("Node public key mismatch - possible MITM attack");
522→                state.state = PeerState::fail("Node identity mismatch");
523→            }
524→            WelcomeDecision::RejectAudienceMismatch => {
525→                warn!("Permit audience mismatch");
526→                state.state = PeerState::fail("Permit audience mismatch");
527→            }
528→        }
529→    }
530→
531→    /// Complete Welcome flow after successful validation
532→    ///
533→    /// **Context**: Decision approved the Welcome
534→    /// **We store**: Node's permit
535→    /// **We issue**: Reciprocal permit
536→    /// **We send**: PermitGrant
537→    /// **On reconnection**: Also subscribe to active Scribes for live sync
538→    #[instrument(skip_all, fields(node = %self.node_id, can_publish = our_can_publish))]
539→    async fn complete_welcome_flow(
540→        &self,
541→        myself: ractor::ActorRef<super::PeerMessage>,
542→        permit_for_us: &str,
543→        _our_did: &str,
544→        _our_username: &str,
545→        our_can_publish: bool,
546→        node_public_key: &[u8],
547→        state: &mut PeerActorState<C>,
548→    ) {
549→        let node_id_str = self.node_id.to_string();
550→
551→        // Derive node's DID from their public signing key
552→        // This is used for consistent identity tracking (e.g., state vector storage)
553→        let node_public_key_32: [u8; 32] = match node_public_key.try_into() {
554→            Ok(key) => key,
555→            Err(_) => {
556→                error!("Invalid node public key length: expected 32 bytes");
557→                state.state = PeerState::fail("Invalid node public key");
558→                return;
559→            }
560→        };
561→        let node_did = Identity::did_from_public_key(&node_public_key_32);
562→
563→        // Check if this is a reconnection
564→        let stored_permit = state.butler
565→            .nodes().get(&node_id_str)
566→            .ok()
567→            .flatten()
568→            .and_then(|n| n.permit);
569→
570→        if let Some(existing_permit) = stored_permit {
571→            // Reconnection: Verify the permit matches
572→            if permit_for_us == existing_permit {
573→                info!("Reconnection: Node returned our stored permit, sending Ack");
574→                self.send_message(&Message::Ack, state).await;
575→
576→                // Transition directly to Authenticated
577→                let peer_type = PeerType::MyNode;
578→
579→                state.state = PeerState::Authenticated {
580→                    peer_type,
581→                    did: node_did.clone(),
582→                    username: "node".to_string(),
583→                };
584→
585→                self.notify_authenticated(state, peer_type, &node_did, "node");
586→                info!(can_publish = our_can_publish, "Reconnection handshake complete with node {}", self.node_id);
587→
588→                // Subscribe peer to our active Scribes for live sync
589→                self.subscribe_to_active_scribes(myself, state).await;
590→                return;
591→            } else {
592→                warn!("Reconnection: Permit mismatch - falling through to first connection flow");
593→            }
594→        }
595→
596→        // First connection flow
597→        debug!(can_publish = our_can_publish, "First connection: issuing permit for node");
598→
599→        // Store the permit from node
600→        if let Err(e) = state.butler.nodes().set_permit(&node_id_str, permit_for_us.to_string()) {
601→            warn!("Failed to store permit: {}", e);
602→        }
603→
604→        // Issue reciprocal permit for the node using its base64-encoded public key as audience
605→        // Relationship based on our capability - gurkha expects owner_node or viewer_node
606→        let relationship = if our_can_publish { "owner_node" } else { "viewer_node" };
607→        let node_pubkey_b64 = STANDARD.encode(node_public_key);
608→        let (permit_for_node, _our_pubkey) = match state.butler.issue_peer_connection_permit(&node_pubkey_b64, relationship).await {
609→            Ok(result) => result,
610→            Err(e) => {
611→                error!("Failed to issue permit for node: {}", e);
612→                state.state = PeerState::fail("Failed to issue permit");
613→                return;
614→            }
615→        };
616→
617→        // Send PermitGrant
618→        let permit_grant = Message::PermitGrant(PermitGrantMsg {
619→            permit_for_node: permit_for_node.clone(),
620→        });
621→
622→        info!(can_publish = our_can_publish, "Sending PermitGrant to {}", self.node_id);
623→        self.send_message(&permit_grant, state).await;
624→
625→        // Transition to AwaitingPermitGrant (waiting for Ack)
626→        // Use the derived DID for consistent identity tracking
627→        state.state = PeerState::AwaitingPermitGrant {
628→            their_did: node_did,
629→            their_username: "node".to_string(),
630→            is_first_connection: true,
631→            can_publish: our_can_publish,
632→        };
633→    }
634→
635→    /// Handle PermitGrant message (Node mode receives this)
636→    ///
637→    /// **Context**: User sent us their permit after Welcome
638→    /// **We call**: decide_permit_grant_response() for decision
639→    /// **We store**: The permit they gave us
640→    /// **We send**: Ack
641→    /// **Result**: Both sides authenticated
642→    /// **Note**: Subscription happens later via refresh_subscriptions_after_page_data
643→    #[instrument(skip(self, _myself, state, permit_for_node))]
644→    pub(super) async fn on_permit_grant(
645→        &self,
646→        _myself: ractor::ActorRef<super::PeerMessage>,
647→        permit_for_node: &str,
648→        state: &mut PeerActorState<C>,
649→    ) {

650→        if require_node_mode(state.mode, "on_permit_grant").is_some() {
651→            return;
652→        }
653→
654→        // Extract state data
655→        let (their_did, their_username, peer_can_publish) = match &state.state {
656→            PeerState::AwaitingPermitGrant { their_did, their_username, can_publish, .. } => {
657→                (their_did.clone(), their_username.clone(), *can_publish)
658→            }
659→            _ => {
660→                warn!("Unexpected PermitGrant in state {}", state.state.name());
661→                return;
662→            }
663→        };
664→
665→        info!("Received PermitGrant from {}", their_username);
666→
667→        // Parse the permit, cache for later use
668→        let parsed_permit = match parse_permit(permit_for_node) {
669→            Ok(p) => p,
670→            Err(e) => {
671→                warn!("Invalid permit in PermitGrant: {}", e);
672→                self.reject("Invalid permit", state).await;
673→                return;
674→            }
675→        };
676→        state.cached_peer_permit = Some(parsed_permit.clone());
677→
678→        // Get our pubkey for validation (base64-encoded)
679→        let our_pubkey_b64 = match state.butler.get_identity().await {
680→            Ok(identity) => STANDARD.encode(identity.public_signing_key()),
681→            Err(e) => {
682→                error!("Failed to get identity: {}", e);
683→                self.reject("Internal error", state).await;
684→                return;
685→            }
686→        };
687→
688→        // Build context for decision
689→        let ctx = PermitGrantContext {
690→            peer_can_publish,
691→            our_pubkey_b64: &our_pubkey_b64,
692→            their_did: &their_did,
693→            received_permit: &parsed_permit,
694→        };
695→
696→        // Get decision
697→        let decision = decide_permit_grant_response(&ctx);
698→        debug!(?decision, "PermitGrant decision");
699→
700→        // Execute decision
701→        match decision {
702→            PermitGrantDecision::Accept { can_publish } => {
703→                // Store connection permit for non-owner peers (viewers)
704→                // This allows node to reconnect to them later if needed
705→                if can_publish {
706→                    debug!("Owner handshake complete - received reciprocal permit");
707→                } else {
708→                    if let Err(e) = state.butler.store().put_connection_permit(&their_did, permit_for_node) {
709→                        warn!("Failed to store connection permit: {}", e);
710→                    } else {
711→                        debug!(their_did = %their_did, "Stored viewer connection permit");
712→                    }
713→                }
714→
715→                // Transition to Authenticated
716→                let peer_type = PeerType::from_can_publish(can_publish);
717→                state.state = PeerState::Authenticated {
718→                    peer_type,
719→                    did: their_did.clone(),
720→                    username: their_username.clone(),
721→                };
722→
723→                // Notify coordinator
724→                self.notify_authenticated(state, peer_type, &their_did, &their_username);
725→
726→                // Send Ack
727→                self.send_message(&Message::Ack, state).await;
728→
729→                info!(can_publish = can_publish, "Handshake complete with {} ({})", their_username, self.node_id);
730→
731→                // NOTE: Don't subscribe here for first connections - viewer has no pages yet.
732→                // Subscription happens in refresh_subscriptions_after_page_data after PageData is sent.
733→            }
734→            PermitGrantDecision::RejectAudienceMismatch => {
735→                warn!("PermitGrant audience mismatch");
736→                self.reject("Permit audience mismatch", state).await;
737→            }
738→            PermitGrantDecision::RejectIssuerMismatch => {
739→                warn!("PermitGrant issuer mismatch");
740→                self.reject("Permit issuer mismatch", state).await;
741→            }
742→        }
743→    }
744→
745→    /// Handle Ack message
746→    ///
747→    /// **User mode**: Ack after PermitGrant completes first connection handshake
748→    /// **Node mode (reconnection)**: Ack after Welcome completes reconnection handshake
749→    /// **Post-auth**: Subscribe peer to our active Scribes for live sync
750→    #[instrument(skip(self, myself, state))]
751→    pub(super) async fn on_ack(
752→        &self,
753→        myself: ractor::ActorRef<super::PeerMessage>,
754→        state: &mut PeerActorState<C>,
755→    ) {
756→        // Extract state data
757→        let (their_did, their_username, is_first_connection, peer_can_publish) = match &state.state {
758→            PeerState::AwaitingPermitGrant { their_did, their_username, is_first_connection, can_publish } => {
759→                (their_did.clone(), their_username.clone(), *is_first_connection, *can_publish)
760→            }
761→            _ => {
762→                warn!("Unexpected Ack in state {}", state.state.name());
763→                return;
764→            }
765→        };
766→
767→        if is_first_connection {
768→            // User mode: First connection complete after PermitGrant
769→            let peer_type = PeerType::MyNode;
770→            state.state = PeerState::Authenticated {
771→                peer_type,
772→                did: their_did.clone(),
773→                username: their_username.clone(),
774→            };
775→            self.notify_authenticated(state, peer_type, &their_did, &their_username);
776→            info!(can_publish = peer_can_publish, "First connection handshake complete with node {}", self.node_id);
777→        } else {
778→            // Node mode: Reconnection complete - peer verified our stored permit
779→            let peer_type = PeerType::from_can_publish(peer_can_publish);
780→            state.state = PeerState::Authenticated {
781→                peer_type,
782→                did: their_did.clone(),
783→                username: their_username.clone(),
784→            };
785→            self.notify_authenticated(state, peer_type, &their_did, &their_username);
786→            info!(can_publish = peer_can_publish, "Reconnection handshake complete with {}", their_username);
787→
788→            // Subscribe peer to our active Scribes for live sync (reconnection only)
789→            // For reconnection, viewer already has pages and permits stored.
790→            self.subscribe_to_active_scribes(myself, state).await;
791→        }
792→
793→        // NOTE: For first connection, subscription happens after PageData is sent
794→        // via refresh_subscriptions_after_page_data when viewer's permit is stored.
795→
796→        // Drain pending space request queued before handshake completed
797→        // (viewer sent SpaceRequest before Ack arrived)
798→        if let Some((space_id, viewer_permit)) = state.pending_space_request.take() {
799→            info!("Draining queued SpaceRequest for {} after handshake", space_id);
800→            self.initiate_request_space_as_viewer(&space_id, &viewer_permit, state).await;
801→        }
802→    }
803→}
