 79→/// Emit PeerSubscribed to local app subscribers
 80→pub fn emit_peer_subscribed(state: &ScribeState, user_did: &str) {
 81→    let sent = emit_to_page_subscribers(state, PageUpdate::PeerSubscribed {
 82→        did: user_did.to_string(),
 83→        username: None,
 84→    });
 85→    if sent > 0 {
 86→        info!(user_did = %user_did, "Emitted PeerSubscribed to {} subscribers", sent);
 87→    }
 88→}
