 90→/// Emit PeerUnsubscribed to local app subscribers
 91→pub fn emit_peer_unsubscribed(state: &ScribeState, user_did: &str) {
 92→    let sent = emit_to_page_subscribers(state, PageUpdate::PeerUnsubscribed {
 93→        did: user_did.to_string(),
 94→    });
 95→    if sent > 0 {
