100→/// Emit raw ephemeral to local app subscribers
101→pub fn emit_raw_ephemeral(state: &ScribeState, user_did: &str, device_id: &str, payload: &[u8]) {
102→    emit_to_page_subscribers(state, PageUpdate::Ephemeral {
103→        user_did: user_did.to_string(),
104→        device_id: device_id.to_string(),
105→        payload: payload.to_vec(),
106→    });
107→}
