109→/// Emit structured ephemeral to local app subscribers
110→///
111→/// **Context**: Called when a structured ephemeral is sent (locally or received from peer)
112→/// **Note**: Only emits to PageUpdate subscribers, not to PeerActor ephemeral channels
113→pub fn emit_structured_ephemeral(
114→    state: &ScribeState,
115→    from_did: &str,
116→    func: &str,
117→    args: &serde_json::Value,
118→) {
119→    let sent = emit_to_page_subscribers(state, PageUpdate::StructuredEphemeral {
120→        from_did: from_did.to_string(),
121→        func: func.to_string(),
122→        args: args.clone(),
123→    });
124→    debug!(
125→        page_id = %state.page_id,
126→        from_did = %from_did,
127→        func = %func,
128→        subscribers = sent,
129→        "emit_structured_ephemeral: sent to app subscribers"
130→    );
131→}
