133→// Peer Broadcast via Ephemeral Channels
134→
135→/// Broadcast ephemeral data to all subscribed PeerActors (via their ephemeral channels)
136→///
137→/// **Context**: Called for:
138→/// - SendEphemeral from Lua (local user action) - no exclusion
139→/// - RemoteEphemeral (relay to other peers) - exclude sender
140→///
141→/// **exclude_key**: (user_did, device_id) to skip (the sender for relay)
142→#[instrument(skip(state, payload), fields(page_id = %state.page_id, payload_len = payload.len()))]
143→pub fn broadcast_ephemeral_to_subscribers(
144→    state: &ScribeState,
145→    payload: &[u8],
146→    exclude_key: Option<(&str, &str)>,
147→) {
148→    if let Ok(subscribers) = state.subscribers.read() {
149→        let total_subs = subscribers.len();
150→        let mut sent_count = 0;
151→        let mut skipped_no_channel = 0;
152→        let mut skipped_excluded = 0;
153→
154→        for ((did, device), info) in subscribers.iter() {
155→            // Skip sender (for relay - don't echo back)
156→            if let Some((ex_did, ex_device)) = exclude_key {
157→                if did == ex_did && device == ex_device {
158→                    skipped_excluded += 1;
159→                    continue;
160→                }
161→            }
162→            // Send via ephemeral channel if available
163→            if let Some(ref tx) = info.ephemeral_tx {
164→                match tx.try_send(EphemeralOutbound {
165→                    page_id: state.page_id.clone(),
166→                    payload: payload.to_vec(),
167→                }) {
168→                    Ok(()) => sent_count += 1,
169→                    Err(e) => {
170→                        debug!(
171→                            page_id = %state.page_id,
172→                            did = %did,
173→                            error = %e,
174→                            "Failed to send ephemeral to subscriber"
175→                        );
176→                    }
177→                }
178→            } else {
179→                skipped_no_channel += 1;
180→            }
181→        }
182→
183→        debug!(
184→            page_id = %state.page_id,
185→            total_subscribers = total_subs,
186→            sent = sent_count,
187→            skipped_no_channel = skipped_no_channel,
188→            skipped_excluded = skipped_excluded,
189→            payload_len = payload.len(),
190→            "Ephemeral broadcast to PeerActors complete"
191→        );
192→    } else {
193→        warn!(page_id = %state.page_id, "Failed to acquire subscribers lock for ephemeral broadcast");
194→    }
195→}
