  1→//! Permit parsing and permission checking for Scribe actor
  2→//!
  3→//! Handles:
  4→//! - Layer access control (read/write permissions)
  5→//! - Sync policy extraction and enforcement
  6→//! - Pattern-based permission rules
  7→//! - Static layer extraction for pre-creation
  8→//!
  9→//! ## Thin Wrapper Pattern
 10→//!
 11→//! The `PermitContext` struct is a thin wrapper around `gurkha::Permit` that adds
 12→//! page_id and our_did context for method calls. All actual logic delegates to gurkha.
 13→
 14→use tracing::{debug, instrument, trace};
 15→
 16→use crate::{ScribeError, Result};
 17→use crate::state::ScribeState;
 18→
 19→// PermitContext - Thin Wrapper around gurkha::Permit
 20→
 21→/// Thin wrapper around gurkha::Permit with page/DID context
 22→///
 23→/// **Context**: Provides convenient access to permit methods with pre-bound page_id and our_did.
 24→/// **Design**: Stores gurkha::Permit directly, delegates all logic to it.
 25→///
 26→/// **Usage**:
 27→/// ```ignore
 28→/// let ctx = PermitContext::from_token(permit, page_id, our_did)?;
 29→/// if ctx.can_write_layer("orders") { ... }
 30→/// if ctx.should_sync_layer("messages") { ... }
 31→/// ```
 32→#[derive(Debug, Clone)]
 33→pub struct PermitContext {
 34→    /// The parsed permit - source of truth for all access checks
 35→    permit: gurkha::Permit,
 36→    /// Page ID (for pattern expansion)
 37→    page_id: String,
 38→    /// Our DID (for pattern expansion with {aud})
 39→    our_did: String,
 40→}
 41→
 42→impl PermitContext {
 43→    /// Parse permit and create context with page/DID binding
 44→    #[instrument(skip(token))]
 45→    pub fn from_token(token: &str, page_id: &str, our_did: &str) -> Result<Self> {
 46→        let permit = gurkha::Permit::from_token(token)
 47→            .map_err(|e| ScribeError::PermitError(format!("Failed to parse permit: {:?}", e)))?;
 48→
 49→        debug!(
 50→            role = ?permit.relationship(),
 51→            is_owner = permit.is_owner(),
 52→            is_host = permit.is_host(),
 53→            layers = permit.layers().len(),
 54→            patterns = permit.layer_patterns().len(),
 55→            "PermitContext created (thin wrapper)"
 56→        );
 57→
 58→        Ok(Self {
 59→            permit,
 60→            page_id: page_id.to_string(),
 61→            our_did: our_did.to_string(),
 62→        })
 63→    }
 64→
 65→    /// Check if layer can be written to
 66→    /// Delegates to gurkha::Permit::can_write_layer()
 67→    pub fn can_write_layer(&self, layer_name: &str) -> bool {
 68→        self.permit.can_write_layer(layer_name, &self.page_id, &self.our_did)
 69→    }
 70→
 71→    /// Check if layer can be read/synced
 72→    /// Delegates to gurkha::Permit::can_read_layer()
 73→    pub fn can_read_layer(&self, layer_name: &str) -> bool {
 74→        self.permit.can_read_layer(layer_name, &self.page_id, &self.our_did)
 75→    }
 76→
 77→    /// Check if layer should sync (not local-only)
 78→    /// Delegates to gurkha::Permit::should_sync_layer()
 79→    pub fn should_sync_layer(&self, layer_name: &str) -> bool {
 80→        self.permit.should_sync_layer(layer_name, &self.page_id, &self.our_did)
 81→    }
 82→
 83→    /// Check if layer should send full snapshot instead of incremental
 84→    pub fn should_send_full_snapshot(&self, layer_name: &str) -> bool {
 85→        self.permit.sync_facts().send_full_snapshot.contains(&layer_name.to_string())
 86→    }
 87→
 88→    /// Check if layer is local-only (never synced)
 89→    pub fn is_layer_local_only(&self, layer_name: &str) -> bool {
 90→        self.permit.sync_facts().local_only.contains(&layer_name.to_string())
 91→    }
 92→
 93→    /// Get the raw permit token
 94→    pub fn raw_token(&self) -> &str {
 95→        self.permit.raw_token()
 96→    }
 97→
 98→    /// Get page ID
 99→    pub fn page_id(&self) -> &str {
100→        &self.page_id
101→    }
102→
103→    /// Get our DID
104→    pub fn our_did(&self) -> &str {
105→        &self.our_did
106→    }
107→
108→    /// Get the underlying permit for direct access
109→    pub fn permit(&self) -> &gurkha::Permit {
110→        &self.permit
111→    }
112→
113→    /// Check if this is an owner permit
114→    pub fn is_owner(&self) -> bool {
115→        self.permit.is_owner()
116→    }
117→
118→    /// Check if this is a host/node permit
119→    pub fn is_host(&self) -> bool {
120→        self.permit.is_host()
121→    }
122→
123→    /// Get static layers (fully expanded, no wildcards) for pre-creation
124→    pub fn static_layers(&self) -> Vec<String> {
125→        self.permit.static_layers(&self.page_id, &self.our_did)
126→    }
127→}
128→
129→/// Simple glob pattern matching for layer names
130→///
131→/// **Supported patterns:**
132→/// - `*` at end: prefix match (e.g., "*:order" matches anything ending with ":order")
133→/// - `*` at start: suffix match (e.g., "did:*" matches anything starting with "did:")
134→/// - Exact match otherwise
135→pub fn glob_match(pattern: &str, name: &str) -> bool {
136→    if pattern == "*" {
137→        true
138→    } else if pattern.starts_with('*') {
139→        // Suffix match: "*:order" matches "did:key:abc:order"
140→        name.ends_with(&pattern[1..])
141→    } else if pattern.ends_with('*') {
142→        // Prefix match: "app:*" matches "app:shop"
143→        name.starts_with(&pattern[..pattern.len() - 1])
144→    } else {
145→        // Exact match
146→        pattern == name
147→    }
148→}
149→
150→// Permission Checking
151→
152→/// Scribe permission checking methods
153→pub struct Permissions;
154→
155→impl Permissions {
156→    /// Check if layer is local_only (never synced)
157→    pub fn is_local_only(layer_name: &str) -> bool {
158→        // Check all subscribers' policies - if ANY marks it local_only, treat as such
159→        // Actually, local_only is typically a page-level setting, not per-peer
160→        // For simplicity, we'll check the layer name
161→        layer_name == "user_content_doc"
162→    }
163→
164→    /// Check if peer can write to layer
165→    ///
166→    /// **Context**: Remote peer is trying to write to this layer
167→    /// **We check**:
168→    /// 1. Peer is a subscriber with write permission via permit.can_write_layer()
169→    /// 2. OR peer is our sync_target (owner/viewer mode - trust sync source)
170→    /// 3. OR peer has a stored permit with write access (node mode - permit-based sync auth)
171→    ///
172→    /// **Security**: For pattern-based layers, gurkha::Permit validates that:
173→    /// - The layer name matches the expanded pattern
174→    /// - Patterns with {aud} expand to the peer's actual DID (namespace enforcement)
175→    pub fn can_write(state: &ScribeState, peer: &(String, String), layer_name: &str) -> bool {
176→        let peer_did = &peer.0;
177→
178→        // 1. Check if peer is a subscriber with write permission
179→        if let Ok(subs) = state.subscribers.read() {
180→            if let Some(info) = subs.get(peer) {
181→                // Use permit's can_write_layer which handles both fixed and pattern-based
182→                if info.can_write_layer(layer_name, &state.page_id) {
183→                    trace!(
184→                        user_did = %peer_did,
185→                        layer = %layer_name,
186→                        "Write allowed via subscriber permit"
187→                    );
188→                    return true;
189→                }
190→            }
191→        }
192→
193→        // 2. Owner/Viewer mode: trust data from our sync_target (the node we sync with)
194→        // This allows receiving sync updates from the node without explicit subscription
195→        if let Some(ref config) = state.sync_config {
196→            if let Some(ref sync_target) = config.sync_target {
197→                if peer_did == sync_target {
198→                    debug!(user_did = %peer_did, layer = %layer_name, "Write allowed from sync_target");
199→                    return true;
200→                }
201→            }
202→        }
203→
204→        // 3. Node mode: check stored permit for write access (permit-based auth)
205→        if let Some(ref resolver) = state.peer_resolver {
206→            if let Some(permit_token) = resolver.load_user_permit(peer_did) {
207→                // Parse permit and check write permissions
208→                if let Ok(permit) = gurkha::Permit::from_token(&permit_token) {
209→                    if permit.can_write_layer(layer_name, &state.page_id, peer_did) {
210→                        debug!(user_did = %peer_did, layer = %layer_name, "Write allowed via stored permit");
211→                        return true;
212→                    }
213→                }
214→            }
215→        }
216→
217→        false
218→    }
219→
220→    /// Check if we (local user) can write to a layer
221→    ///
222→    /// **Context**: Local Lua/UI is trying to modify a layer
223→    /// **We check**: Delegates to ScribeState::can_write_layer()
224→    ///
225→    /// **Security**: Ensures local writes respect our permit constraints
226→    /// (e.g., viewer can only write to their namespaced layers)
227→    pub fn can_local_write(state: &ScribeState, layer_name: &str) -> bool {
228→        state.can_write_layer(layer_name)
229→    }
230→}
