232→// Tests
233→
234→#[cfg(test)]
235→mod tests {
236→    /// Helper to test pattern matching with expansion
237→    fn matches_with_expansion(layer_name: &str, pattern: &str, page_id: &str, did: &str) -> bool {
238→        let expanded = gurkha::expand_pattern(pattern, page_id, did);
239→        gurkha::matches_wildcard(layer_name, &expanded)
240→    }
241→
242→    #[test]
243→    fn test_wildcard_pattern_matching() {
244→        // Exact segments with single wildcard
245→        assert!(gurkha::matches_wildcard("shop123/orders/did:key:customer_a", "shop123/*/did:key:customer_a"));
246→        assert!(gurkha::matches_wildcard("shop123/cart/did:key:customer_a", "shop123/*/did:key:customer_a"));
247→
248→        // Double wildcard (owner/admin pattern)
249→        assert!(gurkha::matches_wildcard("shop123/orders/did:key:customer_a", "shop123/*/*"));
250→        assert!(gurkha::matches_wildcard("shop123/anything/anything_else", "shop123/*/*"));
251→
252→        // Wrong segment count
253→        assert!(!gurkha::matches_wildcard("shop123/orders", "shop123/*/did:key:customer_a"));
254→        assert!(!gurkha::matches_wildcard("shop123/orders/sub/did:key:customer_a", "shop123/*/did:key:customer_a"));
255→
256→        // Wrong DID
257→        assert!(!gurkha::matches_wildcard("shop123/orders/did:key:customer_b", "shop123/*/did:key:customer_a"));
258→    }
259→
260→    #[test]
261→    fn test_pattern_expansion_and_privacy() {
262→        let pattern = "{page_id}/*/{aud}";
263→
264→        // Expansion matches own DID
265→        assert!(matches_with_expansion("shop123/orders/did:key:customer_a", pattern, "shop123", "did:key:customer_a"));
266→        // Expansion rejects other DID
267→        assert!(!matches_with_expansion("shop123/orders/did:key:customer_b", pattern, "shop123", "did:key:customer_a"));
268→
269→        // Owner wildcard pattern matches all
270→        let owner_pattern = "{page_id}/*/*";
271→        assert!(matches_with_expansion("shop123/orders/did:key:customer_a", owner_pattern, "shop123", "did:key:owner"));
272→        assert!(matches_with_expansion("shop123/orders/did:key:customer_b", owner_pattern, "shop123", "did:key:owner"));
273→    }
274→
275→    #[test]
276→    fn test_privacy_isolation() {
277→        let pattern = "{page_id}/*/{aud}";
278→        let layer_a = "shop123/orders/did:key:customer_a";
279→        let layer_b = "shop123/orders/did:key:customer_b";
280→
281→        // Customer A can access their own layer
282→        assert!(matches_with_expansion(layer_a, pattern, "shop123", "did:key:customer_a"));
283→        // Customer A cannot access Customer B's layer
284→        assert!(!matches_with_expansion(layer_b, pattern, "shop123", "did:key:customer_a"));
285→
286→        // Customer B can access their own layer
287→        assert!(matches_with_expansion(layer_b, pattern, "shop123", "did:key:customer_b"));
288→        // Customer B cannot access Customer A's layer
289→        assert!(!matches_with_expansion(layer_a, pattern, "shop123", "did:key:customer_b"));
290→    }
291→}
