439→/// Update sender's peer vector after receiving their update
440→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
441→fn update_sender_vector(state: &mut ScribeState, peer: &(String, String), layer_name: &str) {
442→    if let Some(unit) = state.units.get(layer_name) {
443→        if let Ok(mut subs) = state.subscribers.write() {
444→            if let Some(info) = subs.get_mut(peer) {
445→                let current_vector = unit.layer().version_vector();
446→                info.vectors.insert(layer_name.to_string(), current_vector);
447→                debug!(user_did = %peer.0, "Updated sender's peer vector");
448→            }
449→        }
450→    }
451→}
