453→/// Detect if a newly created layer matches a dynamic schema and emit permits
454→///
455→/// **Context**: Node receives a new layer from peer. If it matches a dynamic schema,
456→/// prepare layer permits for all connected peers and emit SyncEvent::NewDynamicLayer.
457→/// **Coordinator** distributes the permits to PeerActors → peers.
458→#[instrument(skip(state), fields(page_id = %state.page_id, layer = %layer_name))]
459→async fn emit_dynamic_layer_permits(
460→    state: &ScribeState,
461→    layer_name: &str,
462→    from_peer: &(String, String),
463→) {
464→    // Only nodes issue permits (require permit_issuer + our_permit + sync_event_tx)
465→    let Some(ref permit_issuer) = state.permit_issuer else { return; };
466→    let Some(ref our_permit) = state.our_permit else { return; };
467→    let Some(ref sync_event_tx) = state.sync_event_tx else { return; };
468→
469→    // Check if layer matches a dynamic schema
470→    let Some((schema_key, schema, creator_did)) =
471→        find_matching_dynamic_schema(our_permit, layer_name, &state.page_id) else { return; };
472→
473→    // Validate creator namespace: sender's DID must match DID in path
474→    if from_peer.0 != creator_did {
475→        warn!(
476→            layer = %layer_name,
477→            sender = %from_peer.0,
478→            creator = %creator_did,
479→            "Creator namespace mismatch — sender DID doesn't match path DID"
480→        );
481→        return;
482→    }
483→
484→    // Mark the layer as dynamic
485→    if let Some(unit) = state.units.get(layer_name) {
486→        // Note: is_dynamic is pub so we'd need get_mut, but we can't mutate here.
487→        // The flag is informational; permit issuance is the critical path.
488→        let _ = unit;
489→    }
490→
491→    // Store dynamic layer metadata (for subscription-time permit issuance)
492→    if schema.grant == gurkha::GrantType::Explicit {
493→        if let Some(ref permit_issuer) = state.permit_issuer {
494→            let initial_participants = vec![creator_did.clone()];
495→            let full_name = format!("{}/{}", state.page_id, layer_name);
496→            if let Err(e) = permit_issuer.store_layer_participants(&full_name, &initial_participants) {
497→                warn!(error = %e, "Failed to store initial participants");
498→            } else {
499→                info!(layer = %layer_name, creator = %creator_did, "Stored initial explicit layer metadata");
500→            }
501→        }
502→    }
503→
504→    // Collect connected peers with their roles
505→    let connected_peers = collect_connected_peers_with_roles(state);
506→
507→    // Prepare layer permits
508→    let full_layer_name = format!("{}/{}", state.page_id, layer_name);
509→    match prepare_layer_permits(
510→        permit_issuer.as_ref(),
511→        &state.page_id,
512→        &full_layer_name,
513→        schema,
514→        &creator_did,
515→        &connected_peers,
516→    ) {
517→        Ok(permits) if !permits.is_empty() => {
518→            info!(
519→                layer = %layer_name,
520→                schema = %schema_key,
521→                creator = %creator_did,
522→                permit_count = permits.len(),
523→                "Prepared dynamic layer permits, emitting NewDynamicLayer"
524→            );
525→
526→            // Authorize recipient DIDs on the LayerUnit for broadcast
527→            if let Some(unit) = state.units.get(layer_name) {
528→                for (recipient_did, _token) in &permits {
529→                    unit.authorize_did(recipient_did);
530→                    state.emit_layer_auth_capture(layer_name, recipient_did, "authorized_dynamic_permit");
531→                    debug!(
532→                        recipient = %recipient_did,
533→                        layer = %layer_name,
534→                        "Authorized subscriber for dynamic layer"
535→                    );
536→                }
537→            }
538→
539→            let event = SyncEvent::NewDynamicLayer {
540→                page_id: state.page_id.clone(),
541→                layer_name: full_layer_name,
542→                permits,
543→            };
544→
545→            state.emit_sync_event_capture(&event);
546→            if let Err(e) = sync_event_tx.send(event).await {
547→                error!(error = %e, "Failed to emit NewDynamicLayer event");
548→            }
549→        }
550→        Ok(_) => {
551→            debug!(layer = %layer_name, "No permits needed for dynamic layer");
552→        }
553→        Err(e) => {
554→            error!(layer = %layer_name, error = %e, "Failed to prepare dynamic layer permits");
555→        }
556→    }
557→}
558→
559→/// Collect connected peers with their roles from subscriber info
560→///
561→/// **Context**: Node needs (did, role) pairs for prepare_layer_permits
562→fn collect_connected_peers_with_roles(state: &ScribeState) -> Vec<(String, String)> {
563→    let mut peers = Vec::new();
564→
565→    if let Ok(subs) = state.subscribers.read() {
566→        for ((did, _device_id), info) in subs.iter() {
567→            let role = info.permit.relationship().unwrap_or("peer").to_string();
568→            // Avoid duplicates (same DID, different devices)
569→            if !peers.iter().any(|(d, _): &(String, String)| d == did) {
570→                peers.push((did.clone(), role));
571→            }
572→        }
573→    }
574→
575→    peers
576→}
577→
578→/// Get role for a peer from their stored permit
579→///
580→/// **Context**: Determining role for Lua validation
581→/// **Checks**:
582→/// 1. Sync target (owner/viewer mode) -> our role's counterpart
583→/// 2. Stored permit (node mode) -> extract role from permit
584→/// 3. Default -> "peer"
585→#[instrument(skip(state), fields(page_id = %state.page_id))]
586→fn get_peer_role(state: &ScribeState, peer_did: &str) -> String {
587→    // If peer is our sync target, they are the "node" from our perspective
588→    if let Some(ref config) = state.sync_config {
589→        if let Some(ref sync_target) = config.sync_target {
590→            if sync_target == peer_did {
591→                return "node".to_string();
592→            }
593→        }
594→    }
595→
596→    // Node mode: look up peer's stored permit and extract role via PermitContext
597→    if let Some(ref resolver) = state.peer_resolver {
598→        if let Some(permit_token) = resolver.load_user_permit(peer_did) {
599→            let role = PermitContext::from_token(&permit_token, &state.page_id, peer_did)
600→                .map(|ctx| ctx.permit().relationship().unwrap_or("peer").to_string())
601→                .unwrap_or_else(|_| "peer".to_string());
602→            debug!(peer_did = %peer_did, role = %role, "Got peer role from stored permit via PermitContext");
603→            return role;
604→        }
605→    }
606→
607→    // Default role
608→    "peer".to_string()
609→}
