  1→//! Subscription handling for Scribe actor
  2→//!
  3→//! Handles peer subscription, unsubscription, and initial state delivery.
  4→
  5→use std::collections::HashMap;
  6→
  7→use tokio::sync::mpsc;
  8→use tracing::{debug, info, warn, instrument};
  9→
 10→use crate::message::{BroadcastPayload, EphemeralOutbound, SyncEvent};
 11→use crate::state::{ScribeState, SubscriberInfo, normalize_layer_name};
 12→use crate::ephemeral::{emit_peer_subscribed, emit_peer_unsubscribed};
 13→use crate::layer_unit::find_matching_dynamic_schema;
 14→
 15→// Helper Functions
 16→
 17→/// Extract permit holder's DID from the permit's audience field
 18→///
 19→/// **Context**: The permit holder is the one who can create layers matching their patterns
 20→/// **Note**: The UCAN audience may be stored as base64-encoded public key or DID format.
 21→/// Layer names use DID format (did:key:...), so we normalize to DID for pattern matching.
 22→fn extract_permit_holder_did(permit: &str, fallback_did: &str) -> String {
 23→    match gurkha::Permit::from_token(permit) {
 24→        Ok(parsed) => {
 25→            let raw_aud = parsed.parsed().audience().to_string();
 26→            // If already a DID, use as-is; otherwise convert from base64
 27→            if raw_aud.starts_with("did:key:") {
 28→                raw_aud
 29→            } else {
 30→                // Assume base64-encoded public key, convert to DID
 31→                match herald::Identity::did_from_base64_pubkey(&raw_aud) {
 32→                    Ok(did) => did,
 33→                    Err(e) => {
 34→                        warn!(error = %e, raw_aud = %raw_aud, "Failed to convert audience to DID, using raw value");
 35→                        raw_aud
 36→                    }
 37→                }
 38→            }
 39→        }
 40→        Err(e) => {
 41→            warn!(error = %e, "Failed to extract audience from permit, falling back to provided DID");
 42→            fallback_did.to_string()
 43→        }
 44→    }
 45→}
 46→
 47→// Subscription Handlers
 48→
 49→/// Handle peer subscription
 50→///
 51→/// **Context**: PeerActor subscribes to receive updates for this page
 52→/// **We do**: Parse permit once with gurkha::Permit, store it directly
 53→///
 54→/// **Pattern expansion**: For patterns like `{page_id}/orders/{aud}`, we use the permit's
 55→/// audience field (the permit holder's DID) for expansion, not the subscriber's DID.
 56→/// This ensures layers created by the permit holder match correctly.
 57→#[instrument(skip(state, broadcast_tx, ephemeral_tx, permit_token), fields(page_id = %state.page_id))]
 58→pub async fn handle_subscribe(
 59→    state: &mut ScribeState,
 60→    user_did: String,
 61→    device_id: String,
 62→    broadcast_tx: mpsc::Sender<BroadcastPayload>,
 63→    ephemeral_tx: Option<mpsc::Sender<EphemeralOutbound>>,
 64→    permit_token: String,
 65→) {
 66→    info!(user_did = %user_did, device_id = %device_id, permit_len = permit_token.len(), "Peer subscribing");
 67→
 68→    // Parse permit once - store directly, no extraction needed
 69→    let permit = match gurkha::Permit::from_token(&permit_token) {
 70→        Ok(p) => p,
 71→        Err(e) => {
 72→            warn!(error = ?e, "Failed to parse permit, rejecting subscription");
 73→            return;
 74→        }
 75→    };
 76→
 77→    // Extract permit holder's DID for pattern expansion
 78→    // The UCAN audience may be base64-encoded public key or DID format
 79→    let permit_holder_did = extract_permit_holder_did(&permit_token, &user_did);
 80→
 81→    // Load stored state vectors for this peer, normalizing keys to bare names
 82→    let vectors = match state.vector_storage.load_vectors(&user_did, &device_id) {
 83→        Ok(Some(v)) => v.into_iter()
 84→            .map(|(k, v)| (normalize_layer_name(&k, &state.page_id), v))
 85→            .collect(),
 86→        Ok(None) => HashMap::new(),
 87→        Err(e) => {
 88→            warn!(error = %e, "Failed to load peer vectors");
 89→            HashMap::new()
 90→        }
 91→    };
 92→
 93→    // Extract presence info from permit
 94→    let is_visible = permit.is_visible();
 95→    let can_see_others = permit.can_see_others();
 96→    let display_name = permit.display_name().map(String::from);
 97→
 98→    info!(
 99→        user_did = %user_did,
100→        permit_holder_did = %permit_holder_did,
101→        is_visible = is_visible,
102→        display_name = ?display_name,
103→        layers = ?permit.layers().keys().collect::<Vec<_>>(),
104→        patterns = ?permit.layer_patterns().keys().collect::<Vec<_>>(),
105→        "Subscription with permit stored directly"
106→    );
107→
108→    if let Ok(mut subs) = state.subscribers.write() {
109→        subs.insert(
110→            (user_did.clone(), device_id.clone()),
111→            SubscriberInfo {
112→                permit: permit.clone(),
113→                subscriber_did: permit_holder_did.clone(),
114→                is_visible,
115→                can_see_others,
116→                display_name: display_name.clone(),
117→                broadcast_tx: broadcast_tx.clone(),
118→                ephemeral_tx,
119→                vectors,
120→            },
121→        );
122→        debug!(subscriber_count = subs.len(), "Subscriber added");
123→    }
124→
125→    // Populate authorized_dids on existing LayerUnits for this subscriber
126→    authorize_subscriber_for_layers(state, &user_did, &permit, &permit_holder_did, can_see_others);
127→
128→    // Notify app subscribers about peer joining (lifecycle event)
129→    emit_peer_subscribed(state, &user_did);
130→
131→    // Send initial state to new subscriber for layers they have access to
132→    send_initial_state_to_subscriber(
133→        state,
134→        &user_did,
135→        &device_id,
136→        &broadcast_tx,
137→    ).await;
138→
139→    // Issue pending layer permits for explicit dynamic layers (node mode only)
140→    issue_pending_layer_permits(state, &user_did, &device_id).await;
141→}
142→
143→/// Populate authorized_dids on all existing LayerUnits for a newly subscribed peer
144→///
145→/// **Context**: Peer just subscribed with a page permit. Check each layer
146→/// against their permit and authorize accordingly.
147→fn authorize_subscriber_for_layers(
148→    state: &ScribeState,
149→    user_did: &str,
150→    permit: &gurkha::Permit,
151→    permit_holder_did: &str,
152→    can_see_others: bool,
153→) {
154→    for (layer_name, unit) in &state.units {
155→        if unit.is_local_only() { continue; }
156→
157→        // Presence layer: only if can_see_others
158→        if (layer_name == "presence" || layer_name.ends_with("/presence")) && !can_see_others {
159→            continue;
160→        }
161→
162→        // no_incoming_updates check
163→        if permit.sync_facts().no_incoming_updates.contains(&layer_name.to_string()) {
164→            continue;
165→        }
166→
167→        // Check if page permit covers this layer
168→        if permit.can_read_layer(layer_name, &state.page_id, permit_holder_did) {
169→            unit.authorize_did(user_did);
170→            state.emit_layer_auth_capture(layer_name, user_did, "authorized_page_permit");
171→        }
172→    }
173→}
174→
175→/// Handle peer unsubscription
176→#[instrument(skip(state), fields(page_id = %state.page_id))]
177→pub async fn handle_unsubscribe(
178→    state: &mut ScribeState,
179→    user_did: &str,
180→    device_id: &str,
181→) {
182→    info!(user_did = %user_did, device_id = %device_id, "Peer unsubscribing");
183→
184→    if let Ok(mut subs) = state.subscribers.write() {
185→        // Save their vectors before removing
186→        if let Some(info) = subs.get(&(user_did.to_string(), device_id.to_string())) {
187→            if let Err(e) = state.vector_storage.save_vectors(user_did, device_id, &info.vectors) {
188→                warn!(error = %e, "Failed to save peer vectors on unsubscribe");
189→            }
190→        }
191→
192→        subs.remove(&(user_did.to_string(), device_id.to_string()));
193→        debug!(subscriber_count = subs.len(), "Subscriber removed");
194→    }
195→
196→    // Remove DID from all LayerUnits' authorized_dids
197→    for (_, unit) in &state.units {
198→        unit.revoke_did(user_did);
199→    }
200→
201→    // Notify app subscribers about peer leaving (lifecycle event)
202→    emit_peer_unsubscribed(state, user_did);
203→}
204→
205→// Initial State Delivery
206→
207→/// Send initial state to a newly subscribed peer
208→///
209→/// **Context**: Peer just subscribed, may have missed previous updates
210→/// **We do**: Send current snapshot for each layer they have permission for
211→/// **Checks**: Uses LayerUnit.is_authorized() (populated by authorize_subscriber_for_layers)
212→#[instrument(skip_all, fields(page_id = %state.page_id, user_did = %user_did))]
213→async fn send_initial_state_to_subscriber(
214→    state: &ScribeState,
215→    user_did: &str,
216→    device_id: &str,
217→    broadcast_tx: &mpsc::Sender<BroadcastPayload>,
218→) {
219→    // Get peer's stored vectors (if any), normalizing keys to bare names
220→    let peer_vectors = match state.vector_storage.load_vectors(user_did, device_id) {
221→        Ok(Some(v)) => v.into_iter()
222→            .map(|(k, v)| (normalize_layer_name(&k, &state.page_id), v))
223→            .collect(),
224→        Ok(None) => HashMap::new(),
225→        Err(_) => HashMap::new(),
226→    };
227→
228→    for (layer_name, unit) in &state.units {
229→        let layer = unit.layer();
230→
231→        // Check if they're authorized for this layer (populated at subscribe time)
232→        if !unit.is_authorized(user_did) {
233→            continue;
234→        }
235→
236→        // Determine what to send: incremental or full snapshot
237→        let data = if let Some(their_vector) = peer_vectors.get(layer_name) {
238→            if their_vector.is_empty() {
239→                layer.export_snapshot()
240→            } else {
241→                match layer.export_updates(their_vector) {
242→                    Ok(updates) if updates.is_empty() => {
243→                        // No new updates since their last sync
244→                        debug!(user_did = %user_did, layer = %layer_name, "No new updates for subscriber");
245→                        continue;
246→                    }
247→                    Ok(updates) => updates,
248→                    Err(e) => {
249→                        warn!(error = %e, layer = %layer_name, "Failed to export incremental, using snapshot");
250→                        layer.export_snapshot()
251→                    }
252→                }
253→            }
254→        } else {
255→            // No stored vector - send full snapshot
256→            layer.export_snapshot()
257→        };
258→
259→        // Get our current state vector for 3-step sync protocol
260→        let state_vector = layer.version_vector();
261→
262→        // Skip empty data or empty state vectors (no operations)
263→        // Empty LoroDoc has state_vector [0] (single byte indicating 0 entries)
264→        if data.is_empty() || state_vector.len() <= 1 {
265→            debug!(user_did = %user_did, layer = %layer_name, "Skipping empty layer in initial state");
266→            continue;
267→        }
268→
269→        let payload = BroadcastPayload {
270→            page_id: state.page_id.clone(),
271→            layer_name: layer_name.clone(),
272→            layer_type: domains::LayerType::from_layer_name(layer_name),
273→            update: data,
274→            state_vector,
275→        };
276→
277→        if let Err(e) = broadcast_tx.try_send(payload) {
278→            warn!(user_did = %user_did, layer = %layer_name, error = %e, "Failed to send initial state");
279→        } else {
280→            debug!(user_did = %user_did, layer = %layer_name, "Sent initial state to subscriber");
281→        }
282→    }
283→}
284→
285→/// Issue pending layer permits for a newly subscribed peer (node mode only)
286→///
287→/// **Context**: Peer just subscribed. Check if they're a participant in any explicit
288→/// dynamic layers and issue fresh permits.
289→#[instrument(skip_all, fields(page_id = %state.page_id, user_did = %user_did))]
290→async fn issue_pending_layer_permits(
291→    state: &ScribeState,
292→    user_did: &str,
293→    _device_id: &str,
294→) {
295→    let Some(ref issuer) = state.permit_issuer else { return; };
296→    let Some(ref our_permit) = state.our_permit else { return; };
297→    let Some(ref sync_event_tx) = state.sync_event_tx else { return; };
298→
299→    // Load all explicit dynamic layers and their participants
300→    let explicit_layers = match issuer.list_explicit_dynamic_layers() {
301→        Ok(layers) => layers,
302→        Err(e) => { warn!(error = %e, "Failed to list explicit dynamic layers"); return; }
303→    };
304→
305→    let mut all_permits = Vec::new();
306→    for (layer_name, participants) in &explicit_layers {
307→        if !participants.contains(&user_did.to_string()) { continue; }
308→
309→        // Find schema for permissions
310→        if let Some((_key, schema, _creator)) =
311→            find_matching_dynamic_schema(our_permit, layer_name, &state.page_id)
312→        {
313→            let config = schema.permissions.clone().unwrap_or(
314→                gurkha::LayerConfig { sync: true, write: true, layer_type: None }
315→            );
316→            match issuer.issue_layer_permit(user_did, layer_name, config) {
317→                Ok((token, _cid)) => {
318→                    // Authorize subscriber for this layer
319→                    let bare_name = normalize_layer_name(layer_name, &state.page_id);
320→                    if let Some(unit) = state.units.get(&bare_name) {
321→                        unit.authorize_did(user_did);
322→                        state.emit_layer_auth_capture(&bare_name, user_did, "authorized_layer_permit");
323→                    }
324→                    all_permits.push((user_did.to_string(), token));
325→                }
326→                Err(e) => warn!(error = %e, layer = %layer_name, "Failed to issue pending layer permit"),
327→            }
328→        }
329→    }
330→
331→    // Emit permits for distribution via Coordinator
332→    if !all_permits.is_empty() {
333→        let event = SyncEvent::NewDynamicLayer {
334→            page_id: state.page_id.clone(),
335→            layer_name: "pending-layer-permits".to_string(),
336→            permits: all_permits,
337→        };
338→        state.emit_sync_event_capture(&event);
339→        if let Err(e) = sync_event_tx.send(event).await {
340→            warn!(error = %e, "Failed to emit pending layer permits");
341→        }
342→    }
343→}
