  1→//! Loro CRDT observer and delta handling
  2→//!
  3→//! Handles subscription to Loro changes, delta conversion, and reactive notifications.
  4→//!
  5→//! **Architecture**: Loro's `import()` triggers `subscribe_root` observers automatically.
  6→//! We set up observers for all layers at startup so that both UI notifications and
  7→//! peer broadcasts are handled through the observer pattern (no manual callbacks needed).
  8→
  9→use loro::event::{Diff, DiffEvent, ListDiffItem};
 10→use loro::{LoroValue, ValueOrContainer};
 11→use tokio::sync::mpsc;
 12→use tracing::{debug, info, instrument, warn};
 13→use base64::Engine;
 14→
 15→use crate::message::{BroadcastPayload, LoroDelta, ListOp, PageUpdate};
 16→use crate::permit::Permissions;
 17→use crate::state::ScribeState;
 18→use domains::JsonOp;
 19→
 20→/// Data sent through observer channel (delta + ops for reactive bindings)
 21→struct ObserverSignal {
 22→    delta: Option<LoroDelta>,
 23→    ops: Vec<JsonOp>,
 24→    /// Source of the change: None = local, Some = remote peer (user_did, device_id)
 25→    /// Used for sender exclusion in broadcasts
 26→    from_peer: Option<(String, String)>,
 27→}
 28→
 29→// Delta Conversion Helpers
 30→
 31→/// Convert DiffEvent to structured JsonOps for reactive bindings
 32→///
 33→/// **Context**: Observer receives DiffEvent on Loro changes
 34→/// **We do**: Extract structured ops (insert/update/delete) with keys/values
 35→/// **Used by**: Lua's on_loro_change(layer, ops, full_data) for surgical UI updates
 36→pub fn diff_event_to_ops(diff_event: &DiffEvent) -> Vec<JsonOp> {
 37→    let mut ops = Vec::new();
 38→
 39→    for container_diff in &diff_event.events {
 40→        let path = container_diff.target.to_string();
 41→
 42→        match &container_diff.diff {
 43→            Diff::List(items) => {
 44→                // Track position for list operations
 45→                let mut pos = 0usize;
 46→                for item in items.iter() {
 47→                    match item {
 48→                        ListDiffItem::Insert { insert, .. } => {
 49→                            for (i, value) in insert.iter().enumerate() {
 50→                                let json_value = value_or_container_to_json(value);
 51→                                ops.push(JsonOp {
 52→                                    op: "insert".to_string(),
 53→                                    path: path.clone(),
 54→                                    key: None,
 55→                                    index: Some(pos + i),
 56→                                    value: Some(json_value),
 57→                                    old_value: None,
 58→                                });
 59→                            }
 60→                            pos += insert.len();
 61→                        }
 62→                        ListDiffItem::Delete { delete } => {
 63→                            // Each delete is a single op
 64→                            for _ in 0..*delete {
 65→                                ops.push(JsonOp {
 66→                                    op: "delete".to_string(),
 67→                                    path: path.clone(),
 68→                                    key: None,
 69→                                    index: Some(pos),
 70→                                    value: None,
 71→                                    old_value: None,
 72→                                });
 73→                            }
 74→                            // Position doesn't advance for deletes
 75→                        }
 76→                        ListDiffItem::Retain { retain } => {
 77→                            // Retain just moves position, no op
 78→                            pos += retain;
 79→                        }
 80→                    }
 81→                }
 82→            }
 83→
 84→            Diff::Map(map_delta) => {
 85→                for (key, value) in map_delta.updated.iter() {
 86→                    let json_value = value.as_ref()
 87→                        .map(|v| value_or_container_to_json(v));
 88→
 89→                    if let Some(val) = json_value {
 90→                        // Could be insert or update - we use "set" for both
 91→                        ops.push(JsonOp {
 92→                            op: "set".to_string(),
 93→                            path: path.clone(),
 94→                            key: Some(key.to_string()),
 95→                            index: None,
 96→                            value: Some(val),
 97→                            old_value: None,  // TODO: Could track old values if needed
 98→                        });
 99→                    } else {
100→                        // Value is None = deletion
101→                        ops.push(JsonOp {
102→                            op: "delete".to_string(),
103→                            path: path.clone(),
104→                            key: Some(key.to_string()),
105→                            index: None,
106→                            value: None,
107→                            old_value: None,
108→                        });
109→                    }
110→                }
111→            }
112→
113→            Diff::Text(_text_delta) => {
114→                // Text deltas not yet supported for ops
115→                debug!("Text ops not yet implemented");
116→            }
117→
118→            _ => {
119→                debug!("Unsupported diff type for ops: {:?}", container_diff.diff);
120→            }
121→        }
122→    }
123→
124→    ops
125→}
126→
127→/// Convert Loro's Diff to our LoroDelta format
128→///
129→/// **Context**: Loro observer provides Diff on changes, we convert to JSON-serializable format
130→/// **Returns**: LoroDelta for List/Map/Text containers, None for unsupported types
131→pub fn convert_loro_diff_to_delta(diff: &Diff) -> Option<LoroDelta> {
132→    match diff {
133→        Diff::List(items) => {
134→            let ops = items.iter().map(|item| {
135→                match item {
136→                    ListDiffItem::Insert { insert, .. } => {
137→                        // Convert ValueOrContainer to JSON values
138→                        let values = insert.iter()
139→                            .map(|v| value_or_container_to_json(v))
140→                            .collect();
141→                        ListOp::Insert { values }
142→                    }
143→                    ListDiffItem::Delete { delete } => {
144→                        ListOp::Delete { count: *delete }
145→                    }
146→                    ListDiffItem::Retain { retain } => {
147→                        ListOp::Retain { count: *retain }
148→                    }
149→                }
150→            }).collect();
151→
152→            Some(LoroDelta::List { ops })
153→        }
154→
155→        Diff::Map(map_delta) => {
156→            let updated = map_delta.updated.iter()
157→                .map(|(k, v)| {
158→                    let value = v.as_ref()
159→                        .map(|v| value_or_container_to_json(v));
160→                    (k.to_string(), value)
161→                })
162→                .collect();
163→
164→            Some(LoroDelta::Map { updated })
165→        }
166→
167→        Diff::Text(_text_delta) => {
168→            // TODO: Implement text delta conversion when needed
169→            // For now, return None and fall back to full data
170→            debug!("Text delta conversion not yet implemented");
171→            None
172→        }
173→
174→        _ => {
175→            debug!("Unsupported diff type: {:?}", diff);
176→            None
177→        }
178→    }
179→}
180→
181→/// Convert Loro ValueOrContainer to serde_json::Value
182→///
183→/// **Context**: Loro stores values as LoroValue or nested Containers
184→/// **We do**: Extract deep value and convert to JSON
185→fn value_or_container_to_json(value: &ValueOrContainer) -> serde_json::Value {
186→    // Use ValueOrContainer::get_deep_value() to resolve containers
187→    let deep_value = value.get_deep_value();
188→    loro_value_to_json(&deep_value)
189→}
190→
191→/// Convert LoroValue to serde_json::Value
192→///
193→/// **Context**: Loro's native value type → JSON for Lua consumption
194→pub fn loro_value_to_json(value: &LoroValue) -> serde_json::Value {
195→    match value {
196→        LoroValue::Null => serde_json::Value::Null,
197→        LoroValue::Bool(b) => serde_json::Value::Bool(*b),
198→        LoroValue::I64(i) => serde_json::json!(*i),
199→        LoroValue::Double(f) => serde_json::json!(*f),
200→        LoroValue::String(s) => serde_json::Value::String(s.to_string()),
201→        LoroValue::List(arr) => {
202→            serde_json::Value::Array(
203→                arr.iter().map(loro_value_to_json).collect()
204→            )
205→        }
206→        LoroValue::Map(map) => {
207→            serde_json::Value::Object(
208→                map.iter()
209→                    .map(|(k, v)| (k.to_string(), loro_value_to_json(v)))
210→                    .collect()
211→            )
212→        }
213→        LoroValue::Binary(bytes) => {
214→            // Encode binary as base64 string
215→            serde_json::Value::String(base64::engine::general_purpose::STANDARD.encode(&**bytes))
216→        }
217→        LoroValue::Container(_) => {
218→            // Containers are resolved by get_deep_value, shouldn't appear in deltas
219→            debug!("Container in delta value (unexpected), converting to null");
220→            serde_json::Value::Null
221→        }
222→    }
223→}
224→
225→// Loro Layer Handler
226→
227→/// Handle layer modified by Lua via direct FFI access
228→///
229→/// **Context**: Lua called push/set/etc on a LoroList/LoroMap
230→/// **We do**: Check permission, commit transaction, let Loro observer handle notifications
231→///
232→/// **Note**: By the time this is called, the change is already in the Loro doc (via FFI).
233→/// We can't reject it here, but we log a warning if permission would be denied.
234→/// Future: Lua bindings should check can_local_write() before allowing the operation.
235→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
236→pub async fn handle_layer_modified_by_lua(state: &mut ScribeState, layer_name: String) {
237→    debug!(layer_name = %layer_name, "Layer modified by Lua, committing transaction");
238→
239→    // Check if we have permission to write to this layer
240→    // Note: Changes are already made via FFI, this is defense-in-depth logging
241→    if !Permissions::can_local_write(state, &layer_name) {
242→        warn!(
243→            layer = %layer_name,
244→            our_did = %state.our_did,
245→            "Local write to layer without permission (changes already applied via FFI)"
246→        );
247→        // TODO: In future, Lua bindings should check permission before allowing write
248→        // For now, we still commit to avoid leaving Loro in inconsistent state
249→    }
250→
251→    // Commit the Loro transaction to trigger native observer
252→    // This makes the observer fire immediately with delta information
253→    if let Some(unit) = state.units.get(&layer_name) {
254→        unit.layer().commit();
255→    }
256→
257→    // Mark layer as dirty for periodic flush (every 10s)
258→    if let Some(unit) = state.units.get_mut(&layer_name) {
259→        unit.mark_dirty();
260→    }
261→
262→    // NOTE: We don't manually notify observers here!
263→    // The commit() above triggers Loro's native observer (setup in handle_subscribe_loro_changes)
264→    // which will automatically:
265→    // - Send LoroChangeEvent with delta to UI
266→    // - Notify query subscribers
267→    // - Broadcast to peers
268→    //
269→    // Dirty layer will be flushed to storage by periodic timer (every 10s)
270→}
271→
272→// Startup Observer Setup
273→
274→/// Set up Loro observers for all layers at Scribe startup
275→///
276→/// **Context**: Called from `pre_start` to ensure observers are ready before any updates
277→/// **Why**: Loro's `import()` triggers observers automatically, so we need them set up
278→/// **Handles**: Peer broadcasts (to subscribers) + UI notifications (to loro_observers)
279→///
280→/// This ensures both local changes (via commit) and remote changes (via import)
281→/// go through the same observer-based notification path.
282→#[instrument(skip_all, fields(page_id = %state.page_id))]
283→pub fn setup_observers_for_all_layers(state: &mut ScribeState) {
284→    let layer_names: Vec<String> = state.units.keys().cloned().collect();
285→
286→    for layer_name in layer_names {
287→        setup_layer_observer(state, &layer_name);
288→    }
289→
290→    let observer_count = state.units.values().filter(|u| u.has_observer()).count();
291→    info!(
292→        page_id = %state.page_id,
293→        layer_count = observer_count,
294→        "Set up Loro observers for all layers"
295→    );
296→}
297→
298→/// Set up Loro observer for a single layer
299→///
300→/// **Context**: Sets up the observer infrastructure for peer broadcasts and UI notifications
301→/// **Observer fires**: On commit() AND import() - both trigger subscribe_root
302→///
303→/// **Public**: Called from mod.rs when new layers are dynamically created
304→#[instrument(skip(state), fields(page_id = %state.page_id))]
305→pub fn setup_layer_observer(state: &mut ScribeState, layer_name: &str) {
306→    // Skip if already set up
307→    match state.units.get(layer_name) {
308→        Some(u) if u.has_observer() => return,
309→        Some(_) => {}
310→        None => {
311→            warn!(layer_name = %layer_name, "Layer not found for observer setup");
312→            return;
313→        }
314→    };
315→
316→    // We need to get the layer clone and is_local_only before borrowing state mutably
317→    let (layer_clone, is_local_only) = {
318→        let unit = state.units.get(layer_name).unwrap();
319→        (unit.layer().clone(), unit.is_local_only())
320→    };
321→
322→    // Create internal channel for observer signals (includes ops for reactive bindings)
323→    let (signal_tx, mut signal_rx) = tokio::sync::mpsc::unbounded_channel::<ObserverSignal>();
324→
325→    // Clone for the async task
326→    let layer_for_task = layer_clone.clone();
327→    let layer_name_for_task = layer_name.to_string();
328→    let subscribers_for_task = state.subscribers.clone();
329→    let page_id_for_task = state.page_id.clone();
330→    let page_update_subscribers_for_task = state.page_update_subscribers.clone();
331→    // Capture authorized_dids Arc for broadcast filtering
332→    let authorized_dids_for_task = state.units.get(layer_name).unwrap().authorized_dids().clone();
333→    // Clone capture_tx for the observer task
334→    let capture_tx_for_task = state.capture_tx.clone();
335→
336→    // Clone pending_update_source for the synchronous callback
337→    let pending_update_source = state.pending_update_source.clone();
338→
339→    // Spawn async task to handle observer signals
340→    // Note: Derivation is handled in handle_apply_update using ops, not here
341→    tokio::spawn(async move {
342→        while let Some(signal) = signal_rx.recv().await {
343→            let state_vector = layer_for_task.version_vector();
344→
345→            // Prepare ops for reactive bindings (Some if non-empty, None otherwise)
346→            let ops = if signal.ops.is_empty() { None } else { Some(signal.ops) };
347→
348→            // Skip expensive get_content() only for List deltas (surgical conversion always works).
349→            // For Map/Text deltas, always provide full_data so non-keyed Map bindings can
350→            // fall back to Replace when delta conversion returns empty.
351→            let full_data = if matches!(&signal.delta, Some(LoroDelta::List { .. })) {
352→                None
353→            } else {
354→                Some(layer_for_task.get_content(&layer_name_for_task))
355→            };
356→
357→            let page_update = PageUpdate::LayerChanged {
358→                layer: layer_name_for_task.clone(),
359→                from_peer: None,  // Local change
360→                ops,
361→                delta: signal.delta,
362→                state_vector,
363→                full_data,
364→                created: false,
365→            };
366→            // Emit to capture channel (pre-serialized JSON line)
367→            if let Some(ref capture_tx) = capture_tx_for_task {
368→                let ts = std::time::SystemTime::now()
369→                    .duration_since(std::time::UNIX_EPOCH)
370→                    .map(|d| d.as_millis())
371→                    .unwrap_or(0);
372→                if let Ok(json) = serde_json::to_string(&serde_json::json!({
373→                    "type": "page_update",
374→                    "ts": ts,
375→                    "page_id": &page_id_for_task,
376→                    "data": &page_update,
377→                })) {
378→                    let _ = capture_tx.send(json);
379→                }
380→            }
381→            if let Ok(subs) = page_update_subscribers_for_task.read() {
382→                for tx in subs.iter() {
383→                    let _ = tx.try_send(page_update.clone());
384→                }
385→                if !subs.is_empty() {
386→                    debug!(
387→                        layer_name = %layer_name_for_task,
388→                        subscriber_count = subs.len(),
389→                        "Sent PageUpdate::LayerChanged"
390→                    );
391→                }
392→            }
393→
394→            // Check if layer is local-only (sync: false in permit)
395→            // Captured as bool at observer setup time — static per layer
396→            if is_local_only {
397→                debug!(
398→                    layer_name = %layer_name_for_task,
399→                    "Skipping peer broadcast for local-only layer (sync: false)"
400→                );
401→                continue;
402→            }
403→
404→            // Skip peer broadcast for remote updates (sender exclusion)
405→            // Remote updates are forwarded via broadcast_update() in apply.rs which has proper sender exclusion
406→            // Broadcasting here would send the update back to the original sender, causing a sync storm
407→            if signal.from_peer.is_some() {
408→                debug!(
409→                    layer_name = %layer_name_for_task,
410→                    "Skipping observer peer broadcast for remote update (handled by broadcast_update)"
411→                );
412→                continue;
413→            }
414→
415→            // Broadcast incremental updates to peer subscribers
416→            // Uses per-subscriber export_updates(their_vector) instead of full snapshot
417→            let current_vector = layer_for_task.version_vector();
418→
419→            if let Ok(subs) = subscribers_for_task.read() {
420→                debug!(
421→                    page_id = %page_id_for_task,
422→                    layer_name = %layer_name_for_task,
423→                    subscriber_count = subs.len(),
424→                    "Observer broadcasting to subscribers"
425→                );
426→                let authorized = authorized_dids_for_task.read().unwrap_or_else(|e| e.into_inner());
427→                for ((user_did, device_id), info) in subs.iter() {
428→                    if !authorized.contains(user_did) {
429→                        continue;
430→                    }
431→
432→                    // Incremental export: use subscriber's last known vector
433→                    // Falls back to full snapshot for first sync (no vector cached)
434→                    let update = if let Some(their_vector) = info.vectors.get(&*layer_name_for_task) {
435→                        layer_for_task.export_updates(their_vector)
436→                            .unwrap_or_else(|_| layer_for_task.export_snapshot())
437→                    } else {
438→                        layer_for_task.export_snapshot()
439→                    };
440→
441→                    let update_size = update.len();
442→                    let payload = BroadcastPayload {
443→                        page_id: page_id_for_task.clone(),
444→                        layer_name: layer_name_for_task.clone(),
445→                        layer_type: domains::LayerType::from_layer_name(&layer_name_for_task),
446→                        update,
447→                        state_vector: current_vector.clone(),
448→                    };
449→
450→                    match info.broadcast_tx.try_send(payload) {
451→                        Ok(()) => {
452→                            debug!(
453→                                user_did = %user_did,
454→                                layer_name = %layer_name_for_task,
455→                                update_size = update_size,
456→                                "Sent incremental broadcast to subscriber"
457→                            );
458→                        }
459→                        Err(mpsc::error::TrySendError::Full(_)) => {
460→                            warn!(user_did = %user_did, device_id = %device_id, "Peer broadcast channel full");
461→                        }
462→                        Err(mpsc::error::TrySendError::Closed(_)) => {
463→                            debug!(user_did = %user_did, "Peer broadcast channel closed");
464→                        }
465→                    }
466→                }
467→            }
468→        }
469→        debug!(layer_name = %layer_name_for_task, "Observer task ended");
470→    });
471→
472→    // Subscribe to Loro changes - extract ops and delta for reactive bindings
473→    let subscription = layer_clone.subscribe_root(move |diff_event: loro::event::DiffEvent| {
474→        // Extract structured ops for reactive Lua bindings (surgical UI updates)
475→        let ops = diff_event_to_ops(&diff_event);
476→
477→        // Extract delta for legacy VecModel operations
478→        let delta = diff_event.events.first()
479→            .and_then(|container_diff| convert_loro_diff_to_delta(&container_diff.diff));
480→
481→        // Read pending_update_source to determine if this is a remote update
482→        // Remote updates should not trigger peer broadcast (handled by broadcast_update with sender exclusion)
483→        let from_peer = pending_update_source.lock().ok().and_then(|g| g.clone());
484→
485→        let _ = signal_tx.send(ObserverSignal { delta, ops, from_peer });
486→    });
487→
488→    // Store subscription in the LayerUnit
489→    if let Some(unit) = state.units.get_mut(layer_name) {
490→        unit.set_observer(subscription);
491→    }
492→    debug!(layer_name = %layer_name, "Set up Loro observer for layer");
493→}
494→
495→// Pending Update Source Helpers
496→
497→/// Set pending update source before import()
498→///
499→/// **Context**: Called in handle_apply_update before import()
500→/// **Usage**: Observer reads this to populate `from_peer` in PageEvent
501→pub fn set_pending_update_source(state: &ScribeState, from_peer: Option<(String, String)>) {
502→    if let Ok(mut guard) = state.pending_update_source.lock() {
503→        *guard = from_peer;
504→    }
505→}
506→
507→/// Clear pending update source after import()
508→///
509→/// **Context**: Called in handle_apply_update after import()
510→/// **Important**: Must be called to reset for next local operation
511→pub fn clear_pending_update_source(state: &ScribeState) {
512→    if let Ok(mut guard) = state.pending_update_source.lock() {
513→        *guard = None;
514→    }
515→}
516→

  1→//! Sync Consent
  2→//!
  3→//! Handles viewer issuing consent permits to node, and node receiving/storing them.
  4→//! Consent permits authorize the node to send sync updates to the viewer.
  5→
  6→use tracing::{error, info, warn, instrument};
  7→
  8→use crate::message::*;
  9→use transport::Connection;
 10→
 11→use super::guards::{require_user_mode, require_auth, parse_permit};
 12→use super::{PeerActor, PeerActorState};
 13→
 14→// Used for automatic consent issuance when viewer receives space/pages.
 15→// In production, these could be configurable.
 16→
 17→/// Default space consent template - viewer consents to receive space sync + new pages
 18→pub(in crate::peer_actor) const DEFAULT_SPACE_CONSENT_TEMPLATE: &str = r#"{
 19→  "consent_template": {
 20→    "token_type": "sync_space_consent",
 21→    "operations": { "receive_pages": "allow", "receive_updates": "allow" },
 22→    "auth_capabilities": { "accept_sync": true, "accept_new_pages": true },
 23→    "relationship": "sync_consent"
 24→  }
 25→}"#;
 26→
 27→/// Default page consent template - viewer consents to receive page layer updates
 28→pub(in crate::peer_actor) const DEFAULT_PAGE_CONSENT_TEMPLATE: &str = r#"{
 29→  "consent_template": {
 30→    "token_type": "sync_page_consent",
 31→    "operations": { "receive_layer_updates": "allow" },
 32→    "auth_capabilities": { "accept_sync": true },
 33→    "presence": { "visible": true },
 34→    "relationship": "sync_consent"
 35→  }
 36→}"#;
 37→
 38→/// Default layer consent template - viewer consents to receive a specific dynamic layer
 39→pub(in crate::peer_actor) const DEFAULT_LAYER_CONSENT_TEMPLATE: &str = r#"{
 40→  "consent_template": {
 41→    "token_type": "sync_layer_consent",
 42→    "operations": { "receive_layer_updates": "allow" },
 43→    "auth_capabilities": { "accept_sync": true },
 44→    "relationship": "sync_consent"
 45→  }
 46→}"#;
 47→
 48→impl<C: Connection> PeerActor<C> {
 49→
 50→    /// Issue sync consent permits and send to node (User/Viewer mode)
 51→    ///
 52→    /// **Context**: Viewer received space + pages, now issues consent permits
 53→    /// **We do**: Issue consent permits via gurkha, send SyncConsentGrant to node
 54→    /// **Node stores**: These permits to attach to future SyncOffer messages
 55→    #[instrument(skip(self, state, space_template, page_template), fields(space_id = %space_id))]
 56→    pub(in crate::peer_actor) async fn issue_sync_consent(
 57→        &self,
 58→        space_id: &str,
 59→        space_template: &str,
 60→        page_template: &str,
 61→        state: &mut PeerActorState<C>,
 62→    ) {
 63→        if require_user_mode(state.mode, "issue_sync_consent").is_some() {
 64→            return;
 65→        }
 66→
 67→        // Get node's public key from authenticated state (this is who we're issuing permits to)
 68→        let node_pubkey = match require_auth(&state.state) {
 69→            Ok((did, _)) => did.to_string(),
 70→            Err(_) => {
 71→                warn!("Cannot issue sync consent: not authenticated with node");
 72→                return;
 73→            }
 74→        };
 75→
 76→        // Get viewer's signing key
 77→        let signing_key = match state.butler.signing_key().await {
 78→            Ok(key) => key,
 79→            Err(e) => {
 80→                error!("Failed to get signing key for consent permits: {}", e);
 81→                return;
 82→            }
 83→        };
 84→
 85→        // Get space data with permit (node's viewer permit for space)
 86→        let space_data = match state.butler.spaces().get_data(space_id) {
 87→            Ok(Some(space)) => space,
 88→            Ok(None) => {
 89→                error!("Space {} not found for consent issuance", space_id);
 90→                return;
 91→            }
 92→            Err(e) => {
 93→                error!("Failed to get space {}: {}", space_id, e);
 94→                return;
 95→            }
 96→        };
 97→
 98→        let node_space_permit = match space_data.get_permit() {
 99→            Some(permit) => permit.clone(),
100→            None => {
101→                error!("No permit found for space {} - cannot issue consent", space_id);
102→                return;
103→            }
104→        };
105→
106→        // Issue space consent permit
107→        let (space_consent_permit, _cid) = match gurkha::issue_sync_space_consent(
108→            &signing_key,
109→            &node_pubkey,
110→            space_id,
111→            &node_space_permit,
112→            space_template,
113→        ).await {
114→            Ok(result) => result,
115→            Err(e) => {
116→                error!("Failed to issue space consent permit: {}", e);
117→                return;
118→            }
119→        };
120→
121→        info!("Issued space consent permit for space {}", space_id);
122→
123→        // Get all pages in space and issue page consent permits
124→        let pages = match state.butler.pages().list(space_id) {
125→            Ok(pages) => pages,
126→            Err(e) => {
127→                error!("Failed to list pages in space {}: {}", space_id, e);
128→                return;
129→            }
130→        };
131→
132→        let mut page_consent_permits: Vec<(String, String)> = Vec::with_capacity(pages.len());
133→
134→        for page in pages {
135→            // Get page data with permit
136→            let page_data = match state.butler.pages().get(&page.id) {
137→                Ok(Some(data)) => data,
138→                Ok(None) => {
139→                    warn!("Page {} not found - skipping consent", page.id);
140→                    continue;
141→                }
142→                Err(e) => {
143→                    warn!("Failed to get page {}: {} - skipping consent", page.id, e);
144→                    continue;
145→                }
146→            };
147→
148→            let node_page_permit = match page_data.get_permit() {
149→                Some(permit) => permit.clone(),
150→                None => {
151→                    warn!("No permit found for page {} - skipping consent", page.id);
152→                    continue;
153→                }
154→            };
155→
156→            // Issue page consent permit
157→            let (page_consent_permit, _cid) = match gurkha::issue_sync_page_consent(
158→                &signing_key,
159→                &node_pubkey,
160→                &page.id,
161→                &node_page_permit,
162→                page_template,
163→            ).await {
164→                Ok(result) => result,
165→                Err(e) => {
166→                    warn!("Failed to issue page consent permit for {}: {}", page.id, e);
167→                    continue;
168→                }
169→            };
170→
171→            page_consent_permits.push((page.id.clone(), page_consent_permit));
172→        }
173→
174→        info!(
175→            "Issued {} page consent permits for space {}",
176→            page_consent_permits.len(),
177→            space_id
178→        );
179→
180→        // Send SyncConsentGrant to node
181→        let request_id = uuid::Uuid::new_v4().to_string();
182→        let msg = Message::SyncConsentGrant(SyncConsentGrantMsg {
183→            request_id,
184→            space_id: space_id.to_string(),
185→            space_consent_permit,
186→            page_consent_permits,
187→        });
188→
189→        self.send_message(&msg, state).await;
190→        info!("Sent SyncConsentGrant for space {} to node", space_id);
191→    }
192→
193→    /// Issue space consent permit only (when space is received)
194→    ///
195→    /// **Context**: Viewer received space, issues consent immediately
196→    /// **We do**: Issue space consent permit via gurkha, send SyncConsentGrant
197→    #[instrument(skip(self, state, node_space_permit, space_template), fields(space_id = %space_id))]
198→    pub(in crate::peer_actor) async fn issue_space_consent(
199→        &self,
200→        space_id: &str,
201→        node_space_permit: &str,
202→        space_template: &str,
203→        state: &mut PeerActorState<C>,
204→    ) {
205→        if require_user_mode(state.mode, "issue_space_consent").is_some() {
206→            return;
207→        }
208→
209→        // Extract node's DID from the permit (iss field)
210→        // This works for both handshake and SpaceRequest flows
211→        let node_pubkey = match parse_permit(node_space_permit) {
212→            Ok(permit) => permit.parsed().issuer().to_string(),
213→            Err(e) => {
214→                error!("Cannot issue space consent: failed to parse permit: {}", e);
215→                return;
216→            }
217→        };
218→
219→        let signing_key = match state.butler.signing_key().await {
220→            Ok(key) => key,
221→            Err(e) => {
222→                error!("Failed to get signing key for space consent: {}", e);
223→                return;
224→            }
225→        };
226→
227→        let (space_consent_permit, _cid) = match gurkha::issue_sync_space_consent(
228→            &signing_key,
229→            &node_pubkey,
230→            space_id,
231→            node_space_permit,
232→            space_template,
233→        ).await {
234→            Ok(result) => result,
235→            Err(e) => {
236→                error!("Failed to issue space consent permit: {}", e);
237→                return;
238→            }
239→        };
240→
241→        info!("Issued space consent permit for space {}", space_id);
242→
243→        // Send SyncConsentGrant with only space consent (no page consents yet)
244→        let request_id = uuid::Uuid::new_v4().to_string();
245→        let msg = Message::SyncConsentGrant(SyncConsentGrantMsg {
246→            request_id,
247→            space_id: space_id.to_string(),
248→            space_consent_permit,
249→            page_consent_permits: vec![],
250→        });
251→
252→        self.send_message(&msg, state).await;
253→        info!("Sent space consent for space {} to node", space_id);
254→    }
255→
256→    /// Issue page consent permit (when each page is received)
257→    ///
258→    /// **Context**: Viewer received a page, issues consent for that page
259→    /// **We do**: Issue page consent permit via gurkha, send SyncConsentGrant
260→    #[instrument(skip(self, state, node_page_permit, page_template), fields(page_id = %page_id))]
261→    pub(in crate::peer_actor) async fn issue_page_consent(
262→        &self,
263→        page_id: &str,
264→        node_page_permit: &str,
265→        page_template: &str,
266→        state: &mut PeerActorState<C>,
267→    ) {
268→        if require_user_mode(state.mode, "issue_page_consent").is_some() {
269→            return;
270→        }
271→
272→        // Extract node's DID from the permit (iss field)
273→        // This works for both handshake and SpaceRequest flows
274→        let node_pubkey = match parse_permit(node_page_permit) {
275→            Ok(permit) => permit.parsed().issuer().to_string(),
276→            Err(e) => {
277→                error!("Cannot issue page consent: failed to parse permit: {}", e);
278→                return;
279→            }
280→        };
281→
282→        let signing_key = match state.butler.signing_key().await {
283→            Ok(key) => key,
284→            Err(e) => {
285→                error!("Failed to get signing key for page consent: {}", e);
286→                return;
287→            }
288→        };
289→
290→        // Get space_id from page for the message
291→        let space_id = match state.butler.pages().get(page_id) {
292→            Ok(Some(page_data)) => page_data.meta.space_id,
293→            Ok(None) => {
294→                error!("Page {} not found - cannot issue consent", page_id);
295→                return;
296→            }
297→            Err(e) => {
298→                error!("Failed to get page {}: {}", page_id, e);
299→                return;
300→            }
301→        };
302→
303→        let (page_consent_permit, _cid) = match gurkha::issue_sync_page_consent(
304→            &signing_key,
305→            &node_pubkey,
306→            page_id,
307→            node_page_permit,
308→            page_template,
309→        ).await {
310→            Ok(result) => result,
311→            Err(e) => {
312→                error!("Failed to issue page consent permit for {}: {}", page_id, e);
313→                return;
314→            }
315→        };
316→
317→        info!("Issued page consent permit for page {}", page_id);
318→
319→        // Send SyncConsentGrant with only this page consent (empty space consent)
320→        let request_id = uuid::Uuid::new_v4().to_string();
321→        let msg = Message::SyncConsentGrant(SyncConsentGrantMsg {
322→            request_id,
323→            space_id,
324→            space_consent_permit: String::new(), // Empty for page-only consent
325→            page_consent_permits: vec![(page_id.to_string(), page_consent_permit)],
326→        });
327→
328→        self.send_message(&msg, state).await;
329→        info!("Sent page consent for page {} to node", page_id);
330→    }
331→
332→    /// Handle incoming SyncConsentGrant from viewer (Node mode)
333→    ///
334→    /// **Context**: Viewer issued consent permits after receiving space content
335→    /// **We store**: Viewer's consent permits keyed by (viewer_did, space_id/page_id)
336→    /// **We send**: SyncConsentAck to confirm receipt
337→    #[instrument(skip(self, state, space_consent_permit, page_consent_permits), fields(space_id = %space_id))]
338→    pub(in crate::peer_actor) async fn on_sync_consent_grant(
339→        &self,
340→        request_id: &str,
341→        space_id: &str,
342→        space_consent_permit: &str,
343→        page_consent_permits: &[(String, String)],
344→        state: &mut PeerActorState<C>,
345→    ) {
346→        // Extract viewer's DID from the consent permit (iss field)
347→        // The viewer issues consent permits, so `iss` contains viewer's DID
348→        // This works for SpaceRequest flow where viewer isn't handshake-authenticated
349→        let viewer_did = if !space_consent_permit.is_empty() {
350→            match parse_permit(space_consent_permit) {
351→                Ok(permit) => permit.parsed().issuer().to_string(),
352→                Err(e) => {
353→                    error!("Cannot process SyncConsentGrant: failed to parse space consent permit: {}", e);
354→                    return;
355→                }
356→            }
357→        } else if let Some((_, permit)) = page_consent_permits.first() {
358→            match parse_permit(permit) {
359→                Ok(permit) => permit.parsed().issuer().to_string(),
360→                Err(e) => {
361→                    error!("Cannot process SyncConsentGrant: failed to parse page consent permit: {}", e);
362→                    return;
363→                }
364→            }
365→        } else {
366→            error!("SyncConsentGrant has no permits to extract viewer DID from");
367→            return;
368→        };
369→
370→        info!(
371→            "SyncConsentGrant: space={} from viewer={} ({} page consents)",
372→            space_id, viewer_did, page_consent_permits.len()
373→        );
374→
375→        // Store viewer consent permits via Butler
376→        if let Err(e) = state.butler.contacts().store_viewer_consent(
377→            &viewer_did,
378→            space_id,
379→            space_consent_permit,
380→            page_consent_permits,
381→        ).await {
382→            error!("Failed to store viewer consent permits: {}", e);
383→            return;
384→        }
385→
386→        info!("Stored viewer consent permits for {} space={}", viewer_did, space_id);
387→
388→        // Send acknowledgment
389→        let msg = Message::SyncConsentAck(SyncConsentAckMsg {
390→            request_id: request_id.to_string(),
391→            space_id: space_id.to_string(),
392→        });
393→        self.send_message(&msg, state).await;
394→    }
395→
396→    /// Handle incoming SyncConsentAck from node (Viewer-side handler)
397→    ///
398→    /// **Context**: Node has acknowledged our consent permits
399→    /// **Node sends**: SyncConsentAck confirming storage
400→    /// **We know**: Node can now send us sync updates with our consent permits attached
401→    #[instrument(skip(self, state), fields(space_id = %space_id))]
402→    pub(in crate::peer_actor) async fn on_sync_consent_ack(
403→        &self,
404→        request_id: &str,
405→        space_id: &str,
406→        state: &mut PeerActorState<C>,
407→    ) {
408→        let (node_did, _) = match require_auth(&state.state) {
409→            Ok(info) => (info.0.to_string(), info.1.to_string()),
410→            Err(_) => {
411→                warn!("SyncConsentAck from unauthenticated peer: {}", self.node_id);
412→                return;
413→            }
414→        };
415→
416→        info!(
417→            "SyncConsentAck: space={} from node={} request={}",
418→            space_id, node_did, request_id
419→        );
420→
421→        info!("Sync consent complete for space {}", space_id);
422→    }
423→
424→    // --- Layer Permit + Consent ---
425→
426→    /// Send a LayerPermit to this peer (Node mode)
427→    ///
428→    /// **Context**: Coordinator received NewDynamicLayer, forwards to PeerActor
429→    /// **We do**: Send LayerPermitMsg on the wire
430→    #[instrument(skip(self, state, permit), fields(page_id = %page_id, layer = %layer_name))]
431→    pub(in crate::peer_actor) async fn send_layer_permit(
432→        &self,
433→        page_id: &str,
434→        layer_name: &str,
435→        permit: &str,
436→        state: &mut PeerActorState<C>,
437→    ) {
438→        let request_id = uuid::Uuid::new_v4().to_string();
439→        let msg = Message::LayerPermit(LayerPermitMsg {
440→            request_id,
441→            page_id: page_id.to_string(),
442→            layer_name: layer_name.to_string(),
443→            permit: permit.to_string(),
444→        });
445→
446→        self.send_message(&msg, state).await;
447→        info!("Sent LayerPermit for page={} layer={}", page_id, layer_name);
448→    }
449→
450→    /// Send a PermitUpdate to this peer (Node mode)
451→    ///
452→    /// **Context**: Page permit reissued with new app layers
453→    /// **We do**: Send PermitUpdate message on the wire
454→    #[instrument(skip(self, state, permit), fields(page_id = %page_id))]
455→    pub(in crate::peer_actor) async fn send_page_permit_update(
456→        &self,
457→        page_id: &str,
458→        permit: &str,
459→        state: &mut PeerActorState<C>,
460→    ) {
461→        let msg = Message::PermitUpdate(PermitUpdateMsg {
462→            permit: permit.to_string(),
463→            scope: PermitScope::Page { page_id: page_id.to_string() },
464→        });
465→
466→        self.send_message(&msg, state).await;
467→        info!("Sent PermitUpdate for page={}", page_id);
468→    }
469→
470→    /// Handle incoming LayerPermit from node (Viewer-side handler)
471→    ///
472→    /// **Context**: Node detected a new dynamic layer and issued a layer permit to us
473→    /// **We store**: Layer permit alongside page permit in butler
474→    /// **We do**: Auto-issue layer consent back to node
475→    #[instrument(skip(self, state, permit), fields(page_id = %page_id, layer = %layer_name))]
476→    pub(in crate::peer_actor) async fn on_layer_permit(
477→        &self,
478→        request_id: &str,
479→        page_id: &str,
480→        layer_name: &str,
481→        permit: &str,
482→        state: &mut PeerActorState<C>,
483→    ) {
484→        if require_user_mode(state.mode, "on_layer_permit").is_some() {
485→            return;
486→        }
487→
488→        let (node_did, _) = match require_auth(&state.state) {
489→            Ok(info) => (info.0.to_string(), info.1.to_string()),
490→            Err(_) => {
491→                warn!("LayerPermit from unauthenticated peer: {}", self.node_id);
492→                return;
493→            }
494→        };
495→
496→        info!(
497→            "LayerPermit: page={} layer={} from node={}",
498→            page_id, layer_name, node_did
499→        );
500→
501→        // Get our DID for storage
502→        let our_did = match state.butler.get_identity().await {
503→            Ok(identity) => identity.did().to_string(),
504→            Err(e) => {
505→                error!("Failed to get our identity: {}", e);
506→                return;
507→            }
508→        };
509→
510→        // Store layer permit in butler
511→        if let Err(e) = state.butler.permits().store_layer_permit(
512→            page_id,
513→            &our_did,
514→            layer_name,
515→            permit,
516→        ) {
517→            error!("Failed to store layer permit: {}", e);
518→            return;
519→        }
520→
521→        info!("Stored layer permit for page={} layer={}", page_id, layer_name);
522→
523→        // Authorize this layer on local Scribe so observer can broadcast to the node
524→        // The node is a subscriber on our (viewer's) local Scribe
525→        if let Some(subscription) = state.page_subscriptions.get(page_id) {
526→            let bare_name = layer_name.strip_prefix(&format!("{}/", page_id))
527→                .unwrap_or(layer_name);
528→            subscription.scribe.cast(butler::ScribeMessage::AuthorizeLayerSubscriber {
529→                layer_name: bare_name.to_string(),
530→                subscriber_did: node_did.clone(),
531→            }).ok();
532→            info!("Sent AuthorizeLayerSubscriber to local Scribe for layer={}", bare_name);
533→        }
534→
535→        // Auto-issue layer consent back to node
536→        self.issue_layer_consent(page_id, layer_name, permit, state).await;
537→    }
538→
539→    /// Issue layer consent permit and send to node (Viewer mode)
540→    ///
541→    /// **Context**: Viewer received LayerPermit, now consents to sync for that layer
542→    /// **We do**: Issue consent permit via gurkha, send LayerConsentGrant to node
543→    /// **Node stores**: Layer consent to authorize future sync for this layer
544→    #[instrument(skip(self, state, layer_permit_token), fields(page_id = %page_id, layer = %layer_name))]
545→    pub(in crate::peer_actor) async fn issue_layer_consent(
546→        &self,
547→        page_id: &str,
548→        layer_name: &str,
549→        layer_permit_token: &str,
550→        state: &mut PeerActorState<C>,
551→    ) {
552→        if require_user_mode(state.mode, "issue_layer_consent").is_some() {
553→            return;
554→        }
555→
556→        // Extract node's DID from the layer permit (iss field)
557→        let node_pubkey = match parse_permit(layer_permit_token) {
558→            Ok(permit) => permit.parsed().issuer().to_string(),
559→            Err(e) => {
560→                error!("Cannot issue layer consent: failed to parse permit: {}", e);
561→                return;
562→            }
563→        };
564→
565→        let signing_key = match state.butler.signing_key().await {
566→            Ok(key) => key,
567→            Err(e) => {
568→                error!("Failed to get signing key for layer consent: {}", e);
569→                return;
570→            }
571→        };
572→
573→        let (consent_permit, _cid) = match gurkha::issue_sync_layer_consent(
574→            &signing_key,
575→            &node_pubkey,
576→            page_id,
577→            layer_name,
578→            layer_permit_token,
579→            DEFAULT_LAYER_CONSENT_TEMPLATE,
580→        ).await {
581→            Ok(result) => result,
582→            Err(e) => {
583→                error!("Failed to issue layer consent permit: {}", e);
584→                return;
585→            }
586→        };
587→
588→        info!("Issued layer consent for page={} layer={}", page_id, layer_name);
589→
590→        // Send LayerConsentGrant to node
591→        let request_id = uuid::Uuid::new_v4().to_string();
592→        let msg = Message::LayerConsentGrant(LayerConsentGrantMsg {
593→            request_id,
594→            page_id: page_id.to_string(),
595→            layer_name: layer_name.to_string(),
596→            consent_permit,
597→        });
598→
599→        self.send_message(&msg, state).await;
600→    }
601→
602→    /// Handle incoming LayerConsentGrant from viewer (Node-side handler)
603→    ///
604→    /// **Context**: Viewer consented to receive sync for a dynamic layer
605→    /// **We store**: Layer consent in butler
606→    /// **We send**: LayerConsentAck to confirm
607→    #[instrument(skip(self, state, consent_permit), fields(page_id = %page_id, layer = %layer_name))]
608→    pub(in crate::peer_actor) async fn on_layer_consent_grant(
609→        &self,
610→        request_id: &str,
611→        page_id: &str,
612→        layer_name: &str,
613→        consent_permit: &str,
614→        state: &mut PeerActorState<C>,
615→    ) {
616→        // Extract viewer's DID from consent permit (iss field)
617→        let viewer_did = match parse_permit(consent_permit) {
618→            Ok(permit) => permit.parsed().issuer().to_string(),
619→            Err(e) => {
620→                error!("Cannot process LayerConsentGrant: failed to parse permit: {}", e);
621→                return;
622→            }
623→        };
624→
625→        info!(
626→            "LayerConsentGrant: page={} layer={} from viewer={}",
627→            page_id, layer_name, viewer_did
628→        );
629→
630→        // Store layer consent in butler
631→        if let Err(e) = state.butler.permits().store_viewer_layer_consent(
632→            &viewer_did,
633→            page_id,
634→            layer_name,
635→            consent_permit,
636→        ) {
637→            error!("Failed to store viewer layer consent: {}", e);
638→            return;
639→        }
640→
641→        info!("Stored viewer layer consent for page={} layer={} viewer={}", page_id, layer_name, viewer_did);
642→
643→        // Send acknowledgment
644→        let msg = Message::LayerConsentAck(LayerConsentAckMsg {
645→            request_id: request_id.to_string(),
646→            page_id: page_id.to_string(),
647→            layer_name: layer_name.to_string(),
648→        });
649→        self.send_message(&msg, state).await;
650→    }
651→
652→    /// Handle incoming LayerConsentAck from node (Viewer-side handler)
653→    ///
654→    /// **Context**: Node acknowledged our layer consent
655→    /// **We know**: Node can now sync this dynamic layer to us
656→    #[instrument(skip(self, state), fields(page_id = %page_id, layer = %layer_name))]
657→    pub(in crate::peer_actor) async fn on_layer_consent_ack(
658→        &self,
659→        request_id: &str,
660→        page_id: &str,
661→        layer_name: &str,
662→        state: &mut PeerActorState<C>,
663→    ) {
664→        let (node_did, _) = match require_auth(&state.state) {
665→            Ok(info) => (info.0.to_string(), info.1.to_string()),
666→            Err(_) => {
667→                warn!("LayerConsentAck from unauthenticated peer: {}", self.node_id);
668→                return;
669→            }
670→        };
671→
672→        info!(
673→            "LayerConsentAck: page={} layer={} from node={} request={}",
674→            page_id, layer_name, node_did, request_id
675→        );
676→
677→        info!("Layer consent complete for page={} layer={}", page_id, layer_name);
678→    }
679→}
