  1→//! Scribe - Document actor for reactive CRDT synchronization
  2→//!
  3→//! **Context**: Each open page gets its own Scribe that owns LoroDoc layers
  4→//! and handles bidirectional sync with permission-aware merge logic.
  5→//!
  6→//! **Key responsibilities:**
  7→//! - Own LoroDoc layers for a page
  8→//! - Handle permission checks (viewer/submitter/collaborator)
  9→//! - Apply sync policies (local_only, no_incoming_updates, send_full_snapshot)
 10→//! - Broadcast updates to subscribed PeerActors
 11→//! - Notify UI subscribers of changes
 12→
 13→use std::collections::HashMap;
 14→use std::sync::{Arc, Mutex};
 15→
 16→use ractor::{Actor, ActorProcessingErr, ActorRef};
 17→use tokio::time::{interval, Duration};
 18→use tracing::{debug, error, info, instrument, trace, warn};
 19→
 20→use domains::Layer;
 21→
 22→use crate::layer_unit::LayerUnit;
 23→use crate::message;
 24→use crate::state::{ScribeArgs, ScribeState, SyncMode, normalize_layer_name};
 25→use crate::permit::glob_match;
 26→use crate::ephemeral::{
 27→    route_remote_ephemeral, emit_raw_ephemeral, emit_structured_ephemeral,
 28→    broadcast_ephemeral_to_subscribers,
 29→};
 30→use crate::{
 31→    ScribeMessage, ScribeError, Result,
 32→    sync, query, operations, loro_observer,
 33→};
 34→
 35→// Scribe Actor
 36→
 37→/// Scribe - Document sync actor
 38→///
 39→/// One Scribe per open page. Owns layers, handles sync, broadcasts to peers.
 40→pub struct Scribe;
 41→
 42→impl Scribe {
 43→    pub fn new() -> Self {
 44→        Self
 45→    }
 46→}
 47→
 48→impl Default for Scribe {
 49→    fn default() -> Self {
 50→        Self::new()
 51→    }
 52→}
 53→
 54→impl Actor for Scribe {
 55→    type Msg = ScribeMessage;
 56→    type State = ScribeState;
 57→    type Arguments = ScribeArgs;
 58→
 59→    #[instrument(skip_all, fields(page_id = %args.page_id))]
 60→    async fn pre_start(
 61→        &self,
 62→        myself: ActorRef<Self::Msg>,
 63→        args: Self::Arguments,
 64→    ) -> std::result::Result<Self::State, ActorProcessingErr> {
 65→        let mode_info = args
 66→            .sync_config
 67→            .as_ref()
 68→            .map(|c| format!("mode={:?}, target={:?}", c.mode, c.sync_target))
 69→            .unwrap_or_else(|| "no sync config".to_string());
 70→        info!(page_id = %args.page_id, %mode_info, "Scribe started");
 71→
 72→        // Note: Validation is now handled by kunki/ValidationService via ValidationHandle
 73→        // Derivation is handled by kunki/LuaRuntime
 74→        info!(
 75→            page_id = %args.page_id,
 76→            is_node = args.is_node,
 77→            has_validation_handle = args.validation_handle.is_some(),
 78→            "Scribe initialized (validation delegated to kunki)"
 79→        );
 80→
 81→        // Parse our permit using gurkha::Permit directly
 82→        let (our_permit, static_layers) = if let Some(ref permit_token) = args.our_permit {
 83→            match gurkha::Permit::from_token(permit_token) {
 84→                Ok(permit) => {
 85→                    let static_layers = permit.static_layers(&args.page_id, &args.our_did);
 86→                    info!(
 87→                        page_id = %args.page_id,
 88→                        role = %permit.relationship().unwrap_or("peer"),
 89→                        static_layer_count = static_layers.len(),
 90→                        "Parsed our permit via gurkha::Permit"
 91→                    );
 92→                    (Some(permit), static_layers)
 93→                }
 94→                Err(e) => {
 95→                    warn!(page_id = %args.page_id, error = ?e, "Failed to parse our permit");
 96→                    (None, Vec::new())
 97→                }
 98→            }
 99→        } else {
100→            debug!(page_id = %args.page_id, "No our_permit, defaulting to full access");
101→            (None, Vec::new())
102→        };
103→
104→        // Spawn periodic flush timer - saves dirty layers every 10 seconds
105→        // This prevents blocking the actor on every single operation
106→        let myself_clone = myself.clone();
107→        tokio::spawn(async move {
108→            let mut flush_interval = interval(Duration::from_secs(10));
109→            loop {
110→                flush_interval.tick().await;
111→                let _ = myself_clone.cast(ScribeMessage::Flush);
112→            }
113→        });
114→
115→        // Spawn periodic reconciliation timer - catches missed syncs every 30 seconds
116→        // Only for Node mode (Broadcast) - User mode (ToSource) relies on Node to initiate sync
117→        // This prevents bilateral reconciliation attempts that can cause sync storms
118→        let is_user_mode = args.sync_config.as_ref().map(|c| c.mode) == Some(SyncMode::ToSource);
119→        if !is_user_mode {
120→            let myself_reconcile = myself.clone();
121→            tokio::spawn(async move {
122→                let mut reconcile_interval = interval(Duration::from_secs(30));
123→                loop {
124→                    reconcile_interval.tick().await;
125→                    let _ = myself_reconcile.cast(ScribeMessage::ReconcileWithPeers);
126→                }
127→            });
128→        }
129→
130→        // Convert args.layers → LayerUnit instances
131→        let mut units: HashMap<String, LayerUnit> = args.layers
132→            .into_iter()
133→            .map(|(name, layer)| (name, LayerUnit::new(layer)))
134→            .collect();
135→
136→        let mut state = ScribeState {
137→            page_id: args.page_id,
138→            units: HashMap::new(), // Populated below
139→            subscribers: Arc::new(std::sync::RwLock::new(HashMap::new())),
140→            query_subscribers: HashMap::new(),
141→            // Storage traits
142→            layer_storage: args.layer_storage,
143→            vector_storage: args.vector_storage,
144→            peer_resolver: args.peer_resolver,
145→            permit_issuer: args.permit_issuer,
146→            // Sync configuration
147→            sync_config: args.sync_config,
148→            sync_event_tx: args.sync_event_tx,
149→            capture_tx: args.capture_tx,
150→            page_update_subscribers: Arc::new(std::sync::RwLock::new(Vec::new())),
151→            pending_update_source: Arc::new(Mutex::new(None)),
152→            validation_handle: args.validation_handle,
153→            our_permit,
154→            our_did: args.our_did.clone(),
155→            node_script_shutdown: None,
156→            pending_layer_authorizations: HashMap::new(),
157→        };
158→
159→        // Pre-create static layers from permit (already extracted via PermitContext)
160→        // Static layers are fully known after expanding {page_id} and {aud}
161→        // Dynamic layers (with wildcards) are created on-demand during sync
162→        for layer_name in static_layers {
163→            if !units.contains_key(&layer_name) {
164→                info!(
165→                    page_id = %state.page_id,
166→                    layer = %layer_name,
167→                    "Pre-creating static layer from permit"
168→                );
169→                units.insert(layer_name, LayerUnit::new_empty());
170→            }
171→        }
172→
173→        // Set is_local_only on each unit based on permit
174→        for (name, unit) in units.iter_mut() {
175→            unit.set_local_only(!state.should_sync_layer(name));
176→        }
177→
178→        // Move units into state
179→        state.units = units;
180→
181→        // Set up Loro observers for all layers (including pre-created ones)
182→        // This ensures import() triggers broadcasts via observer pattern
183→        loro_observer::setup_observers_for_all_layers(&mut state);
184→
185→        // Emit EnsureSync on page open to trigger remote subscription
186→        // Flow: EnsureSync → Coordinator → (connect if needed) → RefreshSubscriptions → remote subscribes
187→        // Works for both ToSource mode (single sync_target) and Broadcast mode (all authorized users)
188→        if let Some(ref tx) = state.sync_event_tx {
189→            let sync_targets = sync::reconcile::get_sync_targets(&state);
190→            if sync_targets.is_empty() {
191→                debug!(page_id = %state.page_id, "No sync targets on page open");
192→            } else {
193→                info!(page_id = %state.page_id, targets = ?sync_targets, "Emitting EnsureSync for {} targets on page open", sync_targets.len());
194→                for user_did in sync_targets {
195→                    let event = message::SyncEvent::EnsureSync {
196→                        user_did: user_did.clone(),
197→                    };
198→                    state.emit_sync_event_capture(&event);
199→                    match tx.try_send(event) {
200→                        Ok(()) => info!(user_did = %user_did, page_id = %state.page_id, "Emitted EnsureSync on page open"),
201→                        Err(e) => warn!(user_did = %user_did, error = %e, "Failed to emit EnsureSync on page open"),
202→                    }
203→                }
204→            }
205→        }
206→
207→        // Note: Node script spawning is handled by the caller (e.g., kunki's NodeRuntimeManager)
208→        // This keeps the Scribe actor storage-agnostic and focused on CRDT sync
209→
210→        Ok(state)
211→    }
