871→impl Scribe {
872→    /// Handle JSON update from UI (CEL commit())
873→    ///
874→    /// **Broadcast**: Handled automatically by Loro observer after commit()
875→    #[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
876→    async fn handle_update_from_json(
877→        &self,
878→        state: &mut ScribeState,
879→        layer_name: &str,
880→        path: &str,
881→        value: serde_json::Value,
882→    ) -> Result<()> {
883→        info!(layer = %layer_name, path = %path, "Updating layer from JSON");
884→
885→        // Get or create the layer unit
886→        let unit = state
887→            .units
888→            .entry(layer_name.to_string())
889→            .or_insert_with(LayerUnit::new_empty);
890→
891→        // Convert JSON to Loro and update
892→        unit.layer()
893→            .set_from_json(path, &value)
894→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
895→
896→        // Commit to trigger Loro observer (which broadcasts to peers + notifies UI)
897→        unit.layer().commit();
898→
899→        // Mark as dirty for persistence
900→        unit.mark_dirty();
901→
902→        debug!("Layer update from JSON complete, observer will broadcast");
903→        Ok(())
904→    }
