  8→// ID Shortening Utilities
  9→
 10→/// Wrapper for shortening long IDs in logs
 11→///
 12→/// Turns `00c02ee56d990e0a0a1ce0f12f963df121efb6efc51096ae324f5b9bf4bfa4c9`
 13→/// into `00c02e..a4c9` for cleaner log output.
 14→///
 15→/// # Example
 16→/// ```rust
 17→/// use tracing::info;
 18→/// use logging_utils::Short;
 19→///
 20→/// let node_id = "00c02ee56d990e0a0a1ce0f12f963df121efb6efc51096ae324f5b9bf4bfa4c9";
 21→/// info!(node = %Short(node_id), "Connected");
 22→/// // Output: node=00c02e..a4c9 Connected
 23→/// ```
 24→pub struct Short<'a>(pub &'a str);
 25→
 26→impl Display for Short<'_> {
 27→    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
 28→        let s = self.0;
 29→        if s.len() > 16 {
 30→            // Show first 6 and last 4 characters
 31→            write!(f, "{}..{}", &s[..6], &s[s.len()-4..])
 32→        } else {
 33→            write!(f, "{}", s)
 34→        }
 35→    }
 36→}
 37→
 38→/// Shorten a DID for logging
 39→///
 40→/// Turns `did:key:REDACTED`
 41→/// into `did:..vwU` for cleaner log output.
 42→///
 43→/// # Example
 44→/// ```rust
 45→/// use tracing::info;
 46→/// use logging_utils::ShortDid;
 47→///
 48→/// let did = "did:key:REDACTED";
 49→/// info!(peer = %ShortDid(did), "Peer connected");
 50→/// // Output: peer=did:..vwU Peer connected
 51→/// ```
 52→pub struct ShortDid<'a>(pub &'a str);
 53→
 54→impl Display for ShortDid<'_> {
 55→    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
 56→        let s = self.0;
 57→        if s.starts_with("did:") && s.len() > 12 {
 58→            // Show "did:.." + last 4 characters
 59→            write!(f, "did:..{}", &s[s.len()-4..])
 60→        } else if s.len() > 16 {
 61→            write!(f, "{}..{}", &s[..6], &s[s.len()-4..])
 62→        } else {
 63→            write!(f, "{}", s)
 64→        }
 65→    }
 66→}
 67→
 68→/// Shorten a layer name for logging
 69→///
 70→/// Turns `abc123/orders/did:key:REDACTED`
 71→/// into `abc123/orders/did:..vwU` for cleaner log output.
 72→pub struct ShortLayer<'a>(pub &'a str);
 73→
 74→impl Display for ShortLayer<'_> {
 75→    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
 76→        let s = self.0;
 77→        // If layer contains a DID segment, shorten it
 78→        if let Some(did_pos) = s.find("did:") {
 79→            let prefix = &s[..did_pos];
 80→            let did_part = &s[did_pos..];
 81→            if did_part.len() > 12 {
 82→                write!(f, "{}did:..{}", prefix, &did_part[did_part.len()-4..])
 83→            } else {
 84→                write!(f, "{}", s)
 85→            }
 86→        } else if s.len() > 24 {
 87→            // Just truncate long layer names
 88→            write!(f, "{}..{}", &s[..12], &s[s.len()-8..])
 89→        } else {
 90→            write!(f, "{}", s)
 91→        }
 92→    }
 93→}
