 95→/// Shorten any Display-able value for logging
 96→///
 97→/// Convenience function for use in tracing macros.
 98→///
 99→/// # Example
100→/// ```rust
101→/// use tracing::info;
102→/// use logging_utils::short;
103→///
104→/// let node_id = some_node_id; // implements Display
105→/// info!(node = %short(&node_id), "Connected");
106→/// ```
107→pub fn short<T: Display>(value: &T) -> String {
108→    let s = value.to_string();
109→    if s.len() > 16 {
110→        format!("{}..{}", &s[..6], &s[s.len()-4..])
111→    } else {
112→        s
113→    }
114→}
