116→/// Shorten a DID string
117→pub fn short_did(did: &str) -> String {
118→    if did.starts_with("did:") && did.len() > 12 {
119→        format!("did:..{}", &did[did.len()-4..])
120→    } else if did.len() > 16 {
121→        format!("{}..{}", &did[..6], &did[did.len()-4..])
122→    } else {
123→        did.to_string()
124→    }
125→}
