  1→//! 3-Step Sync Protocol
  2→//!
  3→//! Handles the SyncOffer → SyncAccept → SyncAck protocol for CRDT synchronization.
  4→//! Also includes asset sync triggering after layer sync completes.
  5→//!
  6→//! ## Bounded Resync Protocol
  7→//!
  8→//! When vectors diverge after SyncOffer/SyncAccept, we resync. But to prevent
  9→//! infinite loops, we track resync attempts:
 10→//!
 11→//! 1. `resync_attempts < MAX_RESYNC_ATTEMPTS`: Send another SyncOffer
 12→//! 2. `resync_attempts >= MAX_RESYNC_ATTEMPTS`: Send SyncReset (request full snapshot)
 13→//! 3. Node responds with SyncSnapshot (authoritative full state)
 14→//! 4. User replaces local layer entirely
 15→//!
 16→//! **Invariant**: Node is source of truth for divergence resolution.
 17→
 18→use tracing::{debug, error, info, trace, warn, instrument};
 19→
 20→use crate::message::*;
 21→use transport::Connection;
 22→
 23→use super::super::guards::require_auth;
 24→use super::super::{PeerActor, PeerActorState, MAX_RESYNC_ATTEMPTS};
 25→
 26→impl<C: Connection> PeerActor<C> {
 27→
 28→    /// Handle incoming SyncOffer from peer (Step 1)
 29→    ///
 30→    /// **Context**: Peer has a layer update with their state vector
 31→    /// **Peer sends**: SyncOffer with page_id, layer_name, encrypted data, state_vector
 32→    /// **We decrypt**: ECDH with ephemeral_public + our encryption key
 33→    /// **We apply**: Via Scribe.ApplyUpdateWithResult (handles merge)
 34→    /// **We respond**: SyncAccept with our state vector after applying (only if successful)
 35→    #[instrument(skip(self, myself, state, data, their_state_vector, ephemeral_public), fields(page_id = %page_id, layer_name = %layer_name))]
 36→    pub(in crate::peer_actor) async fn on_sync_offer(
 37→        &self,
 38→        myself: ractor::ActorRef<super::super::PeerMessage>,
 39→        page_id: &str,
 40→        layer_name: &str,
 41→        data: &[u8],
 42→        their_state_vector: &[u8],
 43→        ephemeral_public: &[u8; 32],
 44→        state: &mut PeerActorState<C>,
 45→    ) {
 46→        let (peer_did, _) = match require_auth(&state.state) {
 47→            Ok(info) => (info.0.to_string(), info.1.to_string()),
 48→            Err(_) => {
 49→                warn!("SyncOffer from unauthenticated peer: {}", self.node_id);
 50→                return;
 51→            }
 52→        };
 53→
 54→        let peer_device_id = self.node_id.to_string();
 55→
 56→        debug!(
 57→            "SyncOffer: page={} layer={} ({} bytes, vector {} bytes) from {}",
 58→            page_id, layer_name, data.len(), their_state_vector.len(), peer_did
 59→        );
 60→
 61→        // Decrypt transit-encrypted update using ECDH
 62→        let our_secret = match state.butler.encryption_key().await {
 63→            Ok(key) => key,
 64→            Err(e) => {
 65→                error!("Failed to get encryption key for SyncOffer decryption: {}", e);
 66→                return;
 67→            }
 68→        };
 69→        let decrypted_data = match herald::decrypt_from_transfer(&our_secret, ephemeral_public, data) {
 70→            Ok(data) => data,
 71→            Err(e) => {
 72→                error!("Failed to decrypt SyncOffer from {}: {}", peer_did, e);
 73→                return;
 74→            }
 75→        };
 76→
 77→        // Auto-subscribe peer if not already subscribed (both Node and User modes)
 78→        // For Node mode: Ensures can_write() can check viewer's write permissions
 79→        // For User mode: Ensures node gets subscribed to viewer's scribe for bidirectional sync
 80→        if !state.page_subscriptions.contains_key(page_id) {
 81→            info!("Auto-subscribing peer {} to page {} from SyncOffer", peer_did, page_id);
 82→            self.subscribe_to_page(myself.clone(), page_id, "", state).await;
 83→        }
 84→
 85→        // Get Scribe via Butler and apply update
 86→        let scribe = match state.butler.open_page(page_id).await {
 87→            Ok(s) => s,
 88→            Err(e) => {
 89→                error!("Failed to open page {}: {}", page_id, e);
 90→                return;
 91→            }
 92→        };
 93→
 94→        // Apply the update with result feedback
 95→        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
 96→        if let Err(e) = scribe.cast(butler::ScribeMessage::ApplyUpdateWithResult {
 97→            layer_name: layer_name.to_string(),
 98→            update: decrypted_data,
 99→            from_peer: Some((peer_did.clone(), peer_device_id.clone())),
100→            permit: None,
101→            reply: reply_tx,
102→        }) {
103→            error!("Failed to send ApplyUpdateWithResult to Scribe: {}", e);
104→            return;
105→        }
106→
107→        // Wait for apply result - only send SyncAccept if successful
108→        match reply_rx.await {
109→            Ok(Ok(())) => {
110→                debug!("ApplyUpdate succeeded for page={} layer={}", page_id, layer_name);
111→            }
112→            Ok(Err(e)) => {
113→                warn!("ApplyUpdate rejected for page={} layer={}: {}", page_id, layer_name, e);
114→                // DO NOT send SyncAccept - this stops the infinite retry loop
115→                return;
116→            }
117→            Err(_) => {
118→                error!("ApplyUpdate reply channel closed for page={} layer={}", page_id, layer_name);
119→                return;
120→            }
121→        }
122→
123→        // Get our state vector after applying
124→        let (tx, rx) = tokio::sync::oneshot::channel();
125→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
126→            layer_name: layer_name.to_string(),
127→            reply: tx.into(),
128→        }) {
129→            error!("Failed to request state vector from Scribe: {}", e);
130→            return;
131→        }
132→
133→        let our_state_vector = match rx.await {
134→            Ok(Ok(vector)) => vector,
135→            Ok(Err(e)) => {
136→                error!("Scribe returned error getting state vector: {}", e);
137→                return;
138→            }
139→            Err(_) => {
140→                error!("Scribe dropped state vector reply channel");
141→                return;
142→            }
143→        };
144→
145→        // Send SyncAccept with our state vector
146→        let msg = Message::SyncAccept(SyncAcceptMsg {
147→            page_id: page_id.to_string(),
148→            layer_name: layer_name.to_string(),
149→            state_vector: our_state_vector.clone(),
150→        });
151→
152→        self.send_message(&msg, state).await;
153→        debug!(
154→            "Sent SyncAccept for page={} layer={} to {} (our vector {} bytes)",
155→            page_id, layer_name, peer_did, our_state_vector.len()
156→        );
157→    }
158→
159→    /// Handle incoming SyncAccept from peer (Step 2)
160→    ///
161→    /// **Context**: Peer applied our update and reports their state vector
162→    /// **Peer sends**: SyncAccept with their state vector after applying
163→    /// **We compare**: Their vector with our current vector
164→    /// **If match**: Send SyncAck (sync complete)
165→    /// **If diverged**: Send new SyncOffer with full diff from their vector (resync)
166→    #[instrument(skip(self, state, their_state_vector), fields(page_id = %page_id, layer_name = %layer_name))]
167→    pub(in crate::peer_actor) async fn on_sync_accept(
168→        &self,
169→        page_id: &str,
170→        layer_name: &str,
171→        their_state_vector: &[u8],
172→        state: &mut PeerActorState<C>,
173→    ) {
174→        let (peer_did, _) = match require_auth(&state.state) {
175→            Ok(info) => (info.0.to_string(), info.1.to_string()),
176→            Err(_) => {
177→                warn!("SyncAccept from unauthenticated peer: {}", self.node_id);
178→                return;
179→            }
180→        };
181→
182→        debug!(
183→            "SyncAccept: page={} layer={} from {} (their vector {} bytes)",
184→            page_id, layer_name, peer_did, their_state_vector.len()
185→        );
186→
187→        // Get pending sync context (may not exist for fire-and-forget broadcasts)
188→        let key = (page_id.to_string(), layer_name.to_string());
189→        let pending = state.pending_sync_offers.remove(&key);
190→
191→        // Get our current state vector from Scribe
192→        let scribe = match state.butler.open_page(page_id).await {
193→            Ok(s) => s,
194→            Err(e) => {
195→                error!("Failed to open page {}: {}", page_id, e);
196→                return;
197→            }
198→        };
199→
200→        let (tx, rx) = tokio::sync::oneshot::channel();
201→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
202→            layer_name: layer_name.to_string(),
203→            reply: tx.into(),
204→        }) {
205→            error!("Failed to request state vector from Scribe: {}", e);
206→            return;
207→        }
208→
209→        let our_current_vector = match rx.await {
210→            Ok(Ok(vector)) => vector,
211→            Ok(Err(e)) => {
212→                error!("Scribe returned error getting state vector: {}", e);
213→                return;
214→            }
215→            Err(_) => {
216→                error!("Scribe dropped state vector reply channel");
217→                return;
218→            }
219→        };
220→
221→        // Handle based on whether we have a pending offer
222→        match pending {
223→            None => {
224→                // Fire-and-forget broadcast: No pending offer tracked.
225→                // Just update peer vector cache and send SyncAck. Trust CRDT to converge.
226→                debug!(
227→                    "SyncAccept: no pending offer (fire-and-forget) for page={} layer={} - sending SyncAck",
228→                    page_id, layer_name
229→                );
230→
231→                let msg = Message::SyncAck(SyncAckMsg {
232→                    page_id: page_id.to_string(),
233→                    layer_name: layer_name.to_string(),
234→                    state_vector: our_current_vector,
235→                });
236→                self.send_message(&msg, state).await;
237→
238→                // Update Scribe's in-memory vector cache (persistence via periodic flush)
239→                let peer_device_id = self.node_id.to_string();
240→                if let Some(subscription) = state.page_subscriptions.get(page_id) {
241→                    let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
242→                        user_did: peer_did,
243→                        device_id: peer_device_id,
244→                        layer_name: layer_name.to_string(),
245→                        state_vector: their_state_vector.to_vec(),
246→                    });
247→                }
248→            }
249→            Some(offer) => {
250→                // Tracked sync (initial sync / reconciliation): Compare vectors
251→                trace!(
252→                    "SyncAccept comparison: their_vector={} bytes, offered_vector={} bytes, current_vector={} bytes",
253→                    their_state_vector.len(),
254→                    offer.our_state_vector.len(),
255→                    our_current_vector.len()
256→                );
257→
258→                if their_state_vector == offer.our_state_vector.as_slice() {
259→                    // In sync! Send SyncAck
260→                    trace!(
261→                        "SyncAccept: vectors match for page={} layer={} - sending SyncAck",
262→                        page_id, layer_name
263→                    );
264→
265→                    let msg = Message::SyncAck(SyncAckMsg {
266→                        page_id: page_id.to_string(),
267→                        layer_name: layer_name.to_string(),
268→                        state_vector: our_current_vector,
269→                    });
270→                    self.send_message(&msg, state).await;
271→
272→                    // Update Scribe's in-memory vector cache (persistence via periodic flush)
273→                    let peer_device_id = self.node_id.to_string();
274→                    if let Some(subscription) = state.page_subscriptions.get(page_id) {
275→                        let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
276→                            user_did: peer_did,
277→                            device_id: peer_device_id,
278→                            layer_name: layer_name.to_string(),
279→                            state_vector: their_state_vector.to_vec(),
280→                        });
281→                    }
282→                } else {
283→                    // Diverged! Check if we should resync or fall back to SyncReset
284→                    let new_attempts = offer.resync_attempts + 1;
285→
286→                    if new_attempts > MAX_RESYNC_ATTEMPTS {
287→                        // Max resyncs exceeded - fall back to SyncReset (request full snapshot)
288→                        warn!(
289→                            "SyncAccept: max resyncs ({}) exceeded for page={} layer={} - sending SyncReset",
290→                            MAX_RESYNC_ATTEMPTS, page_id, layer_name
291→                        );
292→
293→                        let msg = Message::SyncReset(SyncResetMsg {
294→                            page_id: page_id.to_string(),
295→                            layer_name: layer_name.to_string(),
296→                        });
297→                        self.send_message(&msg, state).await;
298→                        return;
299→                    }
300→
301→                    // Still have retries - send resync SyncOffer with full diff from their vector
302→                    info!(
303→                        "SyncAccept: vectors DIVERGED for page={} layer={} - sending resync SyncOffer (attempt {}/{})",
304→                        page_id, layer_name, new_attempts, MAX_RESYNC_ATTEMPTS
305→                    );
306→
307→                    // Get diff from their state vector
308→                    let (tx, rx) = tokio::sync::oneshot::channel();
309→                    if let Err(e) = scribe.cast(butler::ScribeMessage::GetUpdatesSince {
310→                        layer_name: layer_name.to_string(),
311→                        state_vector: their_state_vector.to_vec(),
312→                        reply: tx,
313→                    }) {
314→                        error!("Failed to request updates from Scribe: {}", e);
315→                        return;
316→                    }
317→
318→                    let diff = match rx.await {
319→                        Ok(Ok(d)) => d,
320→                        Ok(Err(e)) => {
321→                            error!("Scribe returned error getting updates: {}", e);
322→                            return;
323→                        }
324→                        Err(_) => {
325→                            error!("Scribe dropped updates reply channel");
326→                            return;
327→                        }
328→                    };
329→
330→                    // Encrypt and send new SyncOffer
331→                    let peer_encryption_key = match state.peer_encryption_key {
332→                        Some(key) => key,
333→                        None => {
334→                            warn!("Cannot send resync SyncOffer: peer encryption key not set");
335→                            return;
336→                        }
337→                    };
338→
339→                    let (ephemeral_public, encrypted_data) = match herald::encrypt_for_transfer(
340→                        &peer_encryption_key,
341→                        &diff,
342→                    ) {
343→                        Ok(result) => result,
344→                        Err(e) => {
345→                            error!("Failed to encrypt resync data: {}", e);
346→                            return;
347→                        }
348→                    };
349→
350→                    // Track this new pending sync with incremented attempt counter
351→                    state.pending_sync_offers.insert(
352→                        key,
353→                        super::super::PendingSyncOffer {
354→                            our_state_vector: our_current_vector.clone(),
355→                            permit: String::new(),
356→                            resync_attempts: new_attempts,
357→                        },
358→                    );
359→
360→                    let layer_name_owned = layer_name.to_string();
361→                    let msg = Message::SyncOffer(SyncOfferMsg {
362→                        page_id: page_id.to_string(),
363→                        layer_type: LayerType::from_layer_name(&layer_name_owned),
364→                        layer_name: layer_name_owned,
365→                        data: encrypted_data,
366→                        state_vector: our_current_vector,
367→                        ephemeral_public,
368→                    });
369→                    self.send_message(&msg, state).await;
370→                }
371→            }
372→        }
373→    }
374→
375→    /// Handle incoming SyncAck from peer (Step 3)
376→    ///
377→    /// **Context**: Peer confirms sync complete after comparing vectors
378→    /// **Peer sends**: SyncAck with their final state vector
379→    /// **We do**: Update cached peer vector, log sync complete
380→    #[instrument(skip(self, state, their_state_vector), fields(page_id = %page_id, layer_name = %layer_name))]
381→    pub(in crate::peer_actor) async fn on_sync_ack(
382→        &self,
383→        page_id: &str,
384→        layer_name: &str,
385→        their_state_vector: &[u8],
386→        state: &mut PeerActorState<C>,
387→    ) {
388→        let (peer_did, _) = match require_auth(&state.state) {
389→            Ok(info) => (info.0.to_string(), info.1.to_string()),
390→            Err(_) => {
391→                warn!("SyncAck from unauthenticated peer: {}", self.node_id);
392→                return;
393→            }
394→        };
395→
396→        debug!(
397→            "SyncAck: page={} layer={} from {} - sync complete",
398→            page_id, layer_name, peer_did
399→        );
400→
401→        // Update Scribe's in-memory vector cache (persistence via periodic flush)
402→        let peer_device_id = self.node_id.to_string();
403→        if let Some(subscription) = state.page_subscriptions.get(page_id) {
404→            let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
405→                user_did: peer_did.clone(),
406→                device_id: peer_device_id.clone(),
407→                layer_name: layer_name.to_string(),
408→                state_vector: their_state_vector.to_vec(),
409→            });
410→        }
411→
412→        // Clean up any pending sync for this page/layer (shouldn't exist but be safe)
413→        let key = (page_id.to_string(), layer_name.to_string());
414→        state.pending_sync_offers.remove(&key);
415→
416→        // Check if this is an assets layer sync - trigger asset fetch for missing blobs
417→        if layer_name == "assets" || layer_name.ends_with("/assets") {
418→            self.trigger_asset_sync_after_layer_sync(page_id, layer_name, state).await;
419→        }
420→    }
