422→    /// Handle incoming SyncReset from peer (fallback after max resyncs)
423→    ///
424→    /// **Context**: User mode peer exceeded MAX_RESYNC_ATTEMPTS and requests full snapshot
425→    /// **Node mode only**: Responds with authoritative SyncSnapshot
426→    /// **User mode**: Should not receive this - log warning
427→    #[instrument(skip(self, state), fields(page_id = %page_id, layer_name = %layer_name))]
428→    pub(in crate::peer_actor) async fn on_sync_reset(
429→        &self,
430→        page_id: &str,
431→        layer_name: &str,
432→        state: &mut PeerActorState<C>,
433→    ) {
434→        let peer_did = match require_auth(&state.state) {
435→            Ok((did, _)) => did.to_string(),
436→            Err(_) => {
437→                warn!("SyncReset from unauthenticated peer: {}", self.node_id);
438→                return;
439→            }
440→        };
441→
442→        // Only Node mode should handle SyncReset
443→        if state.mode != crate::CourierMode::Node {
444→            warn!("SyncReset received in User mode - ignoring (only Node should respond)");
445→            return;
446→        }
447→
448→        info!(
449→            "SyncReset: page={} layer={} from {} - sending full snapshot",
450→            page_id, layer_name, peer_did
451→        );
452→
453→        // Get Scribe and export full snapshot
454→        let scribe = match state.butler.open_page(page_id).await {
455→            Ok(s) => s,
456→            Err(e) => {
457→                error!("Failed to open page {} for SyncReset: {}", page_id, e);
458→                return;
459→            }
460→        };
461→
462→        // Get full snapshot
463→        let (snapshot_tx, snapshot_rx) = tokio::sync::oneshot::channel();
464→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetSnapshot {
465→            layer_name: layer_name.to_string(),
466→            reply: snapshot_tx,
467→        }) {
468→            error!("Failed to request snapshot from Scribe: {}", e);
469→            return;
470→        }
471→
472→        let snapshot = match snapshot_rx.await {
473→            Ok(Some(data)) => data,
474→            Ok(None) => {
475→                warn!("Layer {} not found in Scribe for SyncReset", layer_name);
476→                return;
477→            }
478→            Err(_) => {
479→                error!("Scribe dropped snapshot reply channel");
480→                return;
481→            }
482→        };
483→
484→        // Get state vector
485→        let (vector_tx, vector_rx) = tokio::sync::oneshot::channel();
486→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
487→            layer_name: layer_name.to_string(),
488→            reply: vector_tx.into(),
489→        }) {
490→            error!("Failed to request state vector from Scribe: {}", e);
491→            return;
492→        }
493→
494→        let state_vector = match vector_rx.await {
495→            Ok(Ok(v)) => v,
496→            Ok(Err(e)) => {
497→                error!("Scribe returned error getting state vector: {}", e);
498→                return;
499→            }
500→            Err(_) => {
501→                error!("Scribe dropped state vector reply channel");
502→                return;
503→            }
504→        };
505→
506→        // Encrypt snapshot for transfer
507→        let peer_encryption_key = match state.peer_encryption_key {
508→            Some(key) => key,
509→            None => {
510→                warn!("Cannot send SyncSnapshot: peer encryption key not set");
511→                return;
512→            }
513→        };
514→
515→        let (ephemeral_public, encrypted_snapshot) = match herald::encrypt_for_transfer(
516→            &peer_encryption_key,
517→            &snapshot,
518→        ) {
519→            Ok(result) => result,
520→            Err(e) => {
521→                error!("Failed to encrypt snapshot: {}", e);
522→                return;
523→            }
524→        };
525→
526→        // Send SyncSnapshot
527→        let layer_name_owned = layer_name.to_string();
528→        let msg = Message::SyncSnapshot(SyncSnapshotMsg {
529→            page_id: page_id.to_string(),
530→            layer_type: LayerType::from_layer_name(&layer_name_owned),
531→            layer_name: layer_name_owned,
532→            snapshot: encrypted_snapshot,
533→            state_vector,
534→            ephemeral_public,
535→        });
536→        self.send_message(&msg, state).await;
537→
538→        info!(
539→            "Sent SyncSnapshot for page={} layer={} to {} ({} bytes)",
540→            page_id, layer_name, peer_did, snapshot.len()
541→        );
542→    }
543→
544→    /// Handle incoming SyncSnapshot from peer (response to SyncReset)
545→    ///
546→    /// **Context**: Node responded to our SyncReset with authoritative snapshot
547→    /// **User mode only**: Replace local layer entirely with node's state
548→    /// **Node mode**: Should not receive this - log warning
549→    #[instrument(skip(self, state, snapshot, their_state_vector, ephemeral_public), fields(page_id = %page_id, layer_name = %layer_name))]
550→    pub(in crate::peer_actor) async fn on_sync_snapshot(
551→        &self,
552→        page_id: &str,
553→        layer_name: &str,
554→        snapshot: &[u8],
555→        their_state_vector: &[u8],
556→        ephemeral_public: &[u8; 32],
557→        state: &mut PeerActorState<C>,
558→    ) {
559→        let peer_did = match require_auth(&state.state) {
560→            Ok((did, _)) => did.to_string(),
561→            Err(_) => {
562→                warn!("SyncSnapshot from unauthenticated peer: {}", self.node_id);
563→                return;
564→            }
565→        };
566→
567→        // Only User mode should receive SyncSnapshot
568→        if state.mode != crate::CourierMode::User {
569→            warn!("SyncSnapshot received in Node mode - ignoring (only User should apply)");
570→            return;
571→        }
572→
573→        info!(
574→            "SyncSnapshot: page={} layer={} from {} ({} bytes) - replacing local state",
575→            page_id, layer_name, peer_did, snapshot.len()
576→        );
577→
578→        // Decrypt snapshot
579→        let our_secret = match state.butler.encryption_key().await {
580→            Ok(key) => key,
581→            Err(e) => {
582→                error!("Failed to get encryption key for SyncSnapshot decryption: {}", e);
583→                return;
584→            }
585→        };
586→
587→        let decrypted_snapshot = match herald::decrypt_from_transfer(&our_secret, ephemeral_public, snapshot) {
588→            Ok(data) => data,
589→            Err(e) => {
590→                error!("Failed to decrypt SyncSnapshot from {}: {}", peer_did, e);
591→                return;
592→            }
593→        };
594→
595→        // Get Scribe and replace layer
596→        let scribe = match state.butler.open_page(page_id).await {
597→            Ok(s) => s,
598→            Err(e) => {
599→                error!("Failed to open page {} for SyncSnapshot: {}", page_id, e);
600→                return;
601→            }
602→        };
603→
604→        // Replace layer with snapshot
605→        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
606→        if let Err(e) = scribe.cast(butler::ScribeMessage::ReplaceLayer {
607→            layer_name: layer_name.to_string(),
608→            snapshot: decrypted_snapshot,
609→            reply: reply_tx,
610→        }) {
611→            error!("Failed to send ReplaceLayer to Scribe: {}", e);
612→            return;
613→        }
614→
615→        match reply_rx.await {
616→            Ok(Ok(())) => {
617→                info!(
618→                    "SyncSnapshot applied: page={} layer={} - sync recovery complete",
619→                    page_id, layer_name
620→                );
621→            }
622→            Ok(Err(e)) => {
623→                error!("ReplaceLayer failed for page={} layer={}: {}", page_id, layer_name, e);
624→                return;
625→            }
626→            Err(_) => {
627→                error!("Scribe dropped ReplaceLayer reply channel");
628→                return;
629→            }
630→        }
631→
632→        // Update Scribe's in-memory vector cache (persistence via periodic flush)
633→        let peer_device_id = self.node_id.to_string();
634→        if let Some(subscription) = state.page_subscriptions.get(page_id) {
635→            let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
636→                user_did: peer_did.clone(),
637→                device_id: peer_device_id,
638→                layer_name: layer_name.to_string(),
639→                state_vector: their_state_vector.to_vec(),
640→            });
641→        }
642→
643→        // Clean up any pending sync
644→        let key = (page_id.to_string(), layer_name.to_string());
645→        state.pending_sync_offers.remove(&key);
646→    }
647→}
