  1→//! PeerState - Explicit state machine for handshake protocol
  2→//!
  3→//! ```text
  4→//! Connected → HelloReceived → AwaitingPermitGrant → Authenticated
  5→//!     │                                                   │
  6→//!     └──────────────────────────────────────────────────→ Failed
  7→//! ```
  8→//!
  9→//! ## Design (Capability-Based)
 10→//!
 11→//! The protocol is completely role-agnostic. State tracks capabilities
 12→//! derived directly from the permit structure:
 13→//!
 14→//! - `can_publish: true` → Peer can publish spaces to this node
 15→
 16→/// Type of peer connection
 17→#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 18→pub enum PeerType {
 19→    /// Peer can publish spaces (has accept_publish capability)
 20→    Owner,
 21→    /// Peer is our node (we connected to this Node)
 22→    MyNode,
 23→    /// Peer cannot publish, sync only
 24→    Viewer,
 25→}
 26→
 27→impl PeerType {
 28→    /// Derive PeerType from capability
 29→    pub fn from_can_publish(can_publish: bool) -> Self {
 30→        if can_publish {
 31→            PeerType::Owner
 32→        } else {
 33→            PeerType::Viewer
 34→        }
 35→    }
 36→}
 37→
 38→/// Peer connection state machine
 39→///
 40→/// Tracks the handshake progress for a single peer connection.
 41→/// Each PeerActor owns one PeerState instance.
 42→#[derive(Debug, Clone)]
 43→pub enum PeerState {
 44→    /// Initial state after connection established
 45→    Connected,
 46→
 47→    /// Received Hello from peer (Node mode)
 48→    /// Next: We send Welcome, transition to AwaitingPermitGrant
 49→    HelloReceived {
 50→        their_did: String,
 51→        their_username: String,
 52→        their_public_key: Vec<u8>,
 53→        their_permit: String,
 54→        is_first_connection: bool,
 55→    },
 56→
 57→    /// Sent Hello, waiting for Welcome (User mode)
 58→    /// Next: Receive Welcome, send PermitGrant, transition to Authenticated
 59→    AwaitingWelcome {
 60→        our_did: String,
 61→        our_username: String,
 62→        sent_at: i64,
 63→        /// Whether we can publish spaces to this node (from our permit)
 64→        can_publish: bool,
 65→        /// Expected node public key from connection string (for validation)
 66→        expected_node_pubkey: Vec<u8>,
 67→        /// Our original permit (for capability extraction in WelcomeContext)
 68→        our_permit: String,
 69→    },
 70→
 71→    /// Sent Welcome, waiting for PermitGrant (Node mode)
 72→    /// Or: Received Welcome, sent PermitGrant, waiting for Ack (User mode)
 73→    AwaitingPermitGrant {
 74→        their_did: String,
 75→        their_username: String,
 76→        is_first_connection: bool,
 77→        /// Whether peer can publish spaces (determined from their permit)
 78→        can_publish: bool,
 79→    },
 80→
 81→    /// Handshake complete, ready for sync operations
 82→    Authenticated {
 83→        peer_type: PeerType,
 84→        did: String,
 85→        username: String,
 86→    },
 87→
 88→    /// Connection failed - terminal state
 89→    Failed { reason: String },
 90→}
 91→
 92→impl PeerState {
 93→    /// Check if peer is authenticated and ready for sync
 94→    pub fn is_authenticated(&self) -> bool {
 95→        matches!(self, PeerState::Authenticated { .. })
 96→    }
 97→
 98→    /// Check if connection has failed
 99→    pub fn is_failed(&self) -> bool {
100→        matches!(self, PeerState::Failed { .. })
101→    }
102→
103→    /// Check if we received Hello
104→    pub fn is_hello_received(&self) -> bool {
105→        matches!(self, PeerState::HelloReceived { .. })
106→    }
107→
108→    /// Get peer DID if authenticated
109→    pub fn did(&self) -> Option<&str> {
110→        match self {
111→            PeerState::Authenticated { did, .. } => Some(did),
112→            _ => None,
113→        }
114→    }
115→
116→    /// Get peer type if authenticated
117→    pub fn peer_type(&self) -> Option<PeerType> {
118→        match self {
119→            PeerState::Authenticated { peer_type, .. } => Some(*peer_type),
120→            _ => None,
121→        }
122→    }
123→
124→    /// Transition to failed state
125→    pub fn fail(reason: impl Into<String>) -> Self {
126→        PeerState::Failed {
127→            reason: reason.into(),
128→        }
129→    }
130→
131→    /// Get state name for logging
132→    pub fn name(&self) -> &'static str {
133→        match self {
134→            PeerState::Connected => "Connected",
135→            PeerState::HelloReceived { .. } => "HelloReceived",
136→            PeerState::AwaitingWelcome { .. } => "AwaitingWelcome",
137→            PeerState::AwaitingPermitGrant { .. } => "AwaitingPermitGrant",
138→            PeerState::Authenticated { .. } => "Authenticated",
139→            PeerState::Failed { .. } => "Failed",
140→        }
141→    }
142→}
143→
144→#[cfg(test)]
145→mod tests {
146→    use super::*;
147→
148→    fn make_auth(peer_type: PeerType) -> PeerState {
149→        PeerState::Authenticated {
150→            peer_type,
151→            did: "did:key:test".to_string(),
152→            username: "alice".to_string(),
153→        }
154→    }
155→
156→    #[test]
157→    fn test_is_authenticated() {
158→        assert!(make_auth(PeerType::Owner).is_authenticated());
159→        assert!(!PeerState::Connected.is_authenticated());
160→        assert!(!PeerState::fail("reason").is_authenticated());
161→    }
162→
163→    #[test]
164→    fn test_is_failed() {
165→        assert!(PeerState::fail("reason").is_failed());
166→        assert!(!PeerState::Connected.is_failed());
167→        assert!(!make_auth(PeerType::Owner).is_failed());
168→    }
169→
170→    #[test]
171→    fn test_did_extraction() {
172→        assert_eq!(make_auth(PeerType::Owner).did(), Some("did:key:test"));
173→        assert_eq!(PeerState::Connected.did(), None);
174→        assert_eq!(PeerState::fail("reason").did(), None);
175→    }
176→
177→    #[test]
178→    fn test_peer_type_extraction() {
179→        assert_eq!(make_auth(PeerType::Owner).peer_type(), Some(PeerType::Owner));
180→        assert_eq!(make_auth(PeerType::Viewer).peer_type(), Some(PeerType::Viewer));
181→        assert_eq!(PeerState::Connected.peer_type(), None);
182→        assert_eq!(PeerState::fail("reason").peer_type(), None);
183→    }
184→
185→    #[test]
186→    fn test_state_names_are_distinct() {
187→        let states = [
188→            PeerState::Connected,
189→            PeerState::HelloReceived {
190→                their_did: "did".to_string(),
191→                their_username: "user".to_string(),
192→                their_public_key: vec![],
193→                their_permit: "permit".to_string(),
194→                is_first_connection: false,
195→            },
196→            PeerState::AwaitingWelcome {
197→                our_did: "did".to_string(),
198→                our_username: "user".to_string(),
199→                sent_at: 0,
200→                can_publish: false,
201→                expected_node_pubkey: vec![],
202→                our_permit: "permit".to_string(),
203→            },
204→            PeerState::AwaitingPermitGrant {
205→                their_did: "did".to_string(),
206→                their_username: "user".to_string(),
207→                is_first_connection: false,
208→                can_publish: false,
209→            },
210→            PeerState::Authenticated {
211→                peer_type: PeerType::Owner,
212→                did: "did".to_string(),
213→                username: "user".to_string(),
214→            },
215→            PeerState::fail("reason"),
216→        ];
217→
218→        let names: Vec<&str> = states.iter().map(|s| s.name()).collect();
219→
220→        // Verify all names are unique
221→        for (i, name) in names.iter().enumerate() {
222→            for (j, other) in names.iter().enumerate() {
223→                if i != j {
224→                    assert_ne!(name, other, "State names should be unique");
225→                }
226→            }
227→        }
228→    }
229→}
