/// Build the common fields map for capture events
fn capture_common(&self) -> serde_json::Map<String, serde_json::Value> {
    let ts = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_millis())
        .unwrap_or(0);
    let seq = self.next_seq();
    let mut map = serde_json::Map::new();
    map.insert("ts".into(), serde_json::json!(ts));
    map.insert("seq".into(), serde_json::json!(seq));
    map.insert("page_id".into(), serde_json::json!(&self.page_id));
    map
}
```

