1. Add `pub fn emit_permission_check_capture(&self, layer: &str, peer_did: &str, operation: &str, result: bool, path: &str)` to `ScribeState` in `scribe/src/state.rs`.

```rust
pub fn emit_permission_check_capture(
    &self, layer: &str, peer_did: &str, operation: &str, result: bool, path: &str
) {
    if let Some(ref tx) = self.capture_tx {
        let mut map = self.capture_common();
        map.insert("type".into(), "permission_check".into());
        map.insert("layer".into(), layer.into());
        map.insert("peer_did".into(), peer_did.into());
        map.insert("short_did".into(), logging_utils::short_did(peer_did).into());
        map.insert("layer_short".into(), logging_utils::layer_short(layer).into());
        map.insert("operation".into(), operation.into());
        map.insert("result".into(), if result { "allowed" } else { "denied" }.into());
        map.insert("path".into(), path.into());
        if let Ok(json) = serde_json::to_string(&serde_json::Value::Object(map)) {
            let _ = tx.send(json);
        }
    }
}
```

2. Refactor `Permissions::can_write()` in `scribe/src/permit.rs` to track which path succeeded/failed, then call emit at the end:

```rust
pub fn can_write(state: &ScribeState, peer: &(String, String), layer_name: &str) -> bool {
    let peer_did = &peer.0;

    // Path 1: subscriber permit
    if let Ok(subs) = state.subscribers.read() {
        if let Some(info) = subs.get(peer) {
            if info.can_write_layer(layer_name, &state.page_id) {
                state.emit_permission_check_capture(layer_name, peer_did, "write", true, "subscriber_permit");
                return true;
            }
        }
    }

    // Path 2: sync target
    if let Some(ref config) = state.sync_config {
        if let Some(ref sync_target) = config.sync_target {
            if peer_did == sync_target {
                state.emit_permission_check_capture(layer_name, peer_did, "write", true, "sync_target");
                return true;
            }
        }
    }

    // Path 3: stored permit
    if let Some(ref resolver) = state.peer_resolver {
        if let Some(permit_token) = resolver.load_user_permit(peer_did) {
            if let Ok(permit) = gurkha::Permit::from_token(&permit_token) {
                if permit.can_write_layer(layer_name, &state.page_id, peer_did) {
                    state.emit_permission_check_capture(layer_name, peer_did, "write", true, "stored_permit");
                    return true;
                }
            }
        }
    }

    state.emit_permission_check_capture(layer_name, peer_did, "write", false, "all_paths_failed");
    false
}
```

