fn notify_authenticated(&self, state: &PeerActorState<C>, peer_type: PeerType, did: &str, username: &str) {
    // Existing coordinator notification
    let _ = state.coordinator.cast(CoordinatorMessage::PeerAuthenticated {
        node_id: self.node_id,
        peer_type,
        did: did.to_string(),
        username: username.to_string(),
    });

    // Capture event
    if let Some(tx) = &state.capture_tx {
        let seq = state.capture_seq.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        let ts = chrono::Utc::now().format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string();
        let _ = tx.send(serde_json::json!({
            "type": "peer_identity",
            "ts": ts,
            "seq": seq,
            "node_id": self.node_id.to_string(),
            "peer_type": format!("{:?}", peer_type),
            "did": did,
            "short_did": logging_utils::short_did(did),
            "username": username,
        }).to_string());
    }
}
