  1→//! Broadcast handling for Scribe actor
  2→//!
  3→//! Handles layer update broadcasting to subscribers and page update emission.
  4→
  5→use tokio::sync::mpsc;
  6→use tracing::{info, instrument, warn};
  7→
  8→use crate::message::{BroadcastPayload, PageUpdate};
  9→use crate::state::ScribeState;
 10→
 11→// Layer Broadcasting
 12→
 13→/// Broadcast layer update to all eligible subscribers
 14→///
 15→/// **Context**: Layer has been updated, notify all subscribers
 16→/// **We do**: Send incremental or full snapshot to each subscriber
 17→/// **Cleanup**: Remove subscribers whose channels are closed (disconnected)
 18→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
 19→pub async fn broadcast_update(
 20→    state: &mut ScribeState,
 21→    layer_name: &str,
 22→    from_peer: Option<&(String, String)>,
 23→) {
 24→    let Some(unit) = state.units.get(layer_name) else {
 25→        return;
 26→    };
 27→
 28→    let current_vector = unit.layer().version_vector();
 29→    let layer = unit.layer().clone(); // Clone for use inside subscriber lock
 30→
 31→    // Read authorized_dids once before the subscriber loop
 32→    let authorized = unit.authorized_dids().read().unwrap_or_else(|e| e.into_inner()).clone();
 33→
 34→    // Track subscribers to remove (channel closed = peer disconnected)
 35→    let mut to_remove: Vec<(String, String)> = Vec::new();
 36→
 37→    if let Ok(mut subs) = state.subscribers.write() {
 38→        for ((user_did, device_id), info) in subs.iter_mut() {
 39→            // Skip sender
 40→            if from_peer == Some(&(user_did.clone(), device_id.clone())) {
 41→                continue;
 42→            }
 43→
 44→            // Check authorization via LayerUnit
 45→            if !authorized.contains(user_did) {
 46→                continue;
 47→            }
 48→
 49→            // Incremental export: use subscriber's last known vector
 50→            // Falls back to full snapshot for first sync (no vector cached)
 51→            let update = if let Some(their_vector) = info.vectors.get(layer_name) {
 52→                layer.export_updates(their_vector)
 53→                    .unwrap_or_else(|_| layer.export_snapshot())
 54→            } else {
 55→                layer.export_snapshot()
 56→            };
 57→
 58→            let payload = BroadcastPayload {
 59→                page_id: state.page_id.clone(),
 60→                layer_name: layer_name.to_string(),
 61→                layer_type: domains::LayerType::from_layer_name(layer_name),
 62→                update,
 63→                state_vector: current_vector.clone(),
 64→            };
 65→
 66→            match info.broadcast_tx.try_send(payload) {
 67→                Ok(()) => {
 68→                    // Update their vector on successful send
 69→                    info.vectors.insert(layer_name.to_string(), current_vector.clone());
 70→                }
 71→                Err(mpsc::error::TrySendError::Closed(_)) => {
 72→                    info!(user_did = %user_did, device_id = %device_id, "Subscriber disconnected, removing");
 73→                    to_remove.push((user_did.clone(), device_id.clone()));
 74→                }
 75→                Err(mpsc::error::TrySendError::Full(_)) => {
 76→                    warn!(user_did = %user_did, "Broadcast channel full, update dropped");
 77→                }
 78→            }
 79→        }
 80→
 81→        // Remove disconnected subscribers
 82→        for key in to_remove {
 83→            if let Some(info) = subs.remove(&key) {
 84→                if let Err(e) = state.vector_storage.save_vectors(&key.0, &key.1, &info.vectors) {
 85→                    warn!(error = %e, user_did = %key.0, device_id = %key.1, "Failed to save peer vector on disconnect");
 86→                }
 87→                info!(user_did = %key.0, device_id = %key.1, "Cleaned up disconnected subscriber");
 88→            }
 89→        }
 90→    }
 91→
 92→    // Emit EnsureSync for any sync targets not currently subscribed
 93→    super::reconcile::emit_sync_events_for_missing_targets(state);
 94→}
 95→
 96→// Page Update Emission
 97→
 98→/// Notify page event subscribers of new layer discovery
 99→///
100→/// **Context**: A new layer was created (from peer sync or local creation)
101→/// **We do**: Send PageUpdate::LayerChanged with created=true to unified subscribers
102→#[instrument(skip(state), fields(page_id = %state.page_id, layer = %layer_name))]
103→pub fn notify_layer_discovered(state: &ScribeState, layer_name: &str) {
104→    let full_data = state.units.get(layer_name)
105→        .map(|unit| unit.layer().get_content(layer_name))
106→        .unwrap_or(serde_json::Value::Null);
107→
108→    let state_vector = state.units.get(layer_name)
109→        .map(|unit| unit.layer().version_vector())
110→        .unwrap_or_default();
111→
112→    let update = PageUpdate::LayerChanged {
113→        layer: layer_name.to_string(),
114→        from_peer: None,
115→        ops: None,
116→        delta: None,
117→        state_vector: state_vector.clone(),
118→        full_data: Some(full_data.clone()),
119→        created: true,
120→    };
121→    state.emit_page_update_capture(&update);
122→    if let Ok(subs) = state.page_update_subscribers.read() {
123→        for tx in subs.iter() {
124→            let _ = tx.try_send(update.clone());
125→        }
126→    }
127→}
